(()=>{'use strict';
const seconds=5, storageKey='shinen-math-hints-current-attempt-v2';
const lesson6Hints={"例題1・類題1":[{"title":"例題1 正方形DBEFの1辺","hint1":"大きな三角形ABCと、右側の三角形FECを比べよう。直角と、角Cに印をつけると、対応する辺が見えてくるよ。","hint2":"AB：BCからFE：ECがわかるね。正方形だからBEはFEと同じ長さ。BE：ECを図に書き、2つを合わせたBCの長さを使おう。"},{"title":"類題1 正方形DECFの1辺","hint1":"大きな三角形BCAと、左側の三角形BEDを比べよう。共通の角Bと、それぞれの直角に印をつけよう。","hint2":"BC：CAからBE：EDを考えよう。EDとECは正方形の辺なので等しいね。BEとECを合わせると、長さがわかっているどの辺になるかな？"}],"例題2・類題2":[{"title":"例題2 （1）BD：DC","hint1":"三角形ABCと三角形BDCを、同じ向きに描き直してみよう。直角どうしと角Cが対応するよ。","hint2":"BDに対応する大きな三角形の辺はどれ？ DCに対応する辺はどれ？ その2辺の長さの比を使おう。見た目の向きで決めず、角の印で確かめてね。"},{"title":"例題2 （2）三角形ABDの面積","hint1":"三角形ABDとBCDは、底辺をAD・DCとすると高さが共通だね。まずAD：DCを探そう。","hint2":"相似からAD：DBも調べ、（1）のBD：DCとつなごう。共通のDBの比の数をそろえればAD：DCがわかるよ。三角形ABCの面積を、その比で分けよう。"},{"title":"類題2 （1）BD：DC","hint1":"大きな三角形ABCと、右側の三角形CBDを比べよう。共通の角Bと、それぞれの直角に印をつけてね。","hint2":"BDとDCに対応する、大きな三角形の2辺を探そう。求める比は「BDが先、DCが後」。対応する辺の順番もそろえよう。"},{"title":"類題2 （2）三角形ADCの面積","hint1":"三角形ADCとBDCの高さは、どちらもCD。AD：DBがわかれば、全体の面積を分けられるね。","hint2":"左側の小さい三角形も、大きな三角形と相似だよ。AD：DCを求め、（1）のBD：DCと、共通のDCをそろえてつなごう。最後に三角形ABCの面積のうち、AD側の割合を考えよう。"}],"例題3・類題3":[{"title":"例題3 （1）AE：EBがわかるときのEF","hint1":"AからDCに平行な線を引き、EFとの交点をH、BCとの交点をGにしよう。三角形AEHとABGを探そう。","hint2":"平行四辺形を使うとHFとGCの長さがわかり、BGも求められるね。AE：ABを使ってEHを求めよう。求めたいEFは、EHだけでよいかな？"},{"title":"例題3 （2）EFが14cmのときのAE：EB","hint1":"（1）と同じ補助線を引こう。EFとBCから、共通する平行四辺形の幅を取り除いてみよう。","hint2":"EH：BGからわかるのはAE：ABだよ。求めたいのはAE：EBなので、全体ABからAEを引いた部分に注目しよう。"},{"title":"例題3 （3）台形AEFDの面積は全体の何倍か","hint1":"小さい台形と全体の台形について、「上底＋下底」と「高さの比」をそれぞれ書こう。（1）のEFが使えるよ。","hint2":"高さの比はAE：ABと同じ。台形の面積の公式に、高さそのものの代わりに比の数を入れて比べよう。最後は「小さい台形の面積÷全体の面積」だね。"},{"title":"類題3 （1）EFの長さ","hint1":"AからDCに平行な線を引こう。EFとの交点をH、BCとの交点をGにすると、左側に相似な三角形ができるよ。","hint2":"BGは下底と上底の差。AE：ABでEHを求め、それにHFを足そう。AE：EBをそのままAE：ABとして使わないようにね。"},{"title":"類題3 （2）台形AEFDの面積は全体の何倍か","hint1":"（1）のEFを使い、2つの台形の「上底＋下底」をそれぞれ求めよう。","hint2":"2つの台形の高さの比はAE：AB。面積は「上底＋下底」に高さをかけて比べよう。幅の比だけでも、高さの比だけでも決まらないよ。"}],"例題4・類題4":[{"title":"例題4 （1）アの面積（三角形ABR）","hint1":"まず三角形ABFが、正六角形全体のどれだけに当たるか考えよう。中心と各頂点を結ぶと、合同な正三角形ができるよ。","hint2":"三角形ABFは、中心・A・Bで作る正三角形と、底辺ABも高さも等しいよ。次にABRとFBRを、底辺AR・RFで比べよう。RがAFの真ん中であることを使ってね。"},{"title":"例題4 （2）イの面積（三角形BFE）","hint1":"正六角形の中心をOとして、OB・OF・OEを引こう。三角形BFEが2つに分かれるね。","hint2":"三角形FOEは、正六角形を6等分した1つ。三角形BFOとBAFは底辺BFが共通で、OとAからBFまでの高さも等しいよ。（1）で調べた三角形ABFも使おう。"},{"title":"例題4 （3）ウの面積（四角形PCDQ）","hint1":"BCをCの先へ、EDをDの先へ延ばし、交点をNとしよう。ウを「大きい三角形から小さい三角形を引いた形」にできるよ。","hint2":"三角形PNQから三角形CNDを引こう。CNDは正六角形を6等分した正三角形と合同だよ。同じ角Nをはさむ辺を使うと、2つの面積の比は（NP×NQ）：（NC×ND）。BP：PCと、Qが中点であることから、同じ側の辺の比をそろえよう。"},{"title":"類題4 （1）アの面積（三角形DEH）","hint1":"まず三角形DEFの面積を考えよう。中心と各頂点を結んだ、6つの正三角形と比べてみてね。","hint2":"DEFと、中心・D・Eで作る三角形は、底辺DEも高さも等しいよ。次に三角形DEHは、三角形DEFの面積をEH：HFで分けたうち、どちら側か考えよう。"},{"title":"類題4 （2）イの面積（三角形BGD）","hint1":"ADを引き、まず三角形ABDに注目しよう。その面積を、底辺BGとGAの比で分けられないかな？","hint2":"中心をOとすると、ABDはABOとBDOに分かれるよ。BDOは、BOCとCODを合わせた四角形の半分になることを図で確かめよう。ABDの面積がわかったら、AG：GBを使い、BG側の割合を取ろう。"},{"title":"類題4 （3）ウの面積（四角形GAFH）","hint1":"ABをAの先へ、EFをFの先へ延ばし、交点をPとしよう。ウは、大きい三角形PGHから三角形PAFを引いた形だよ。","hint2":"PAFは、正六角形を6等分した正三角形と合同。AG：GBとEH：HFを使い、PG：PAとPH：PFを求めよう。同じ角Pをはさむので、PGHとPAFの面積比は（PG×PH）：（PA×PF）。大きい方から小さい方を引こう。"}],"例題5・類題5":[{"title":"例題5 （1）三角形ABGの面積","hint1":"三角形ABEとACEは、底辺BE・ECで比べられるね。小さい三角形BGEとCGEも、同じ比になるよ。","hint2":"大きい三角形から小さい三角形をそれぞれ引くと、ABGとACGが残るね。残った面積の比にもBE：ECが使えるよ。わかっているACGの面積をもとに考えよう。"},{"title":"例題5 （2）AF：FC","hint1":"AD：DBを使って、三角形ACGとBCGの面積を比べよう。大きい三角形ACD・BCDから、小さい三角形ADG・BDGを引くと考えてね。","hint2":"次に三角形ABGとCBGを比べよう。BF上にGがあるので、この2つの面積の比から、AF：FCがわかるよ。（1）の面積も使えるね。"},{"title":"例題5 （3）AG：GE","hint1":"AGとGEを底辺にする三角形を探そう。三角形ABGとEBGなら、Bからの高さが共通だね。","hint2":"まず三角形BGCを、BE：ECで三角形BGEとCGEに分けよう。その後、ABGとBGEの面積を比べれば、AG：GEがわかるよ。"},{"title":"類題5 （1）三角形AGCの面積","hint1":"AEの左右にある三角形ABGとACGを比べよう。BE：ECが使えないかな？","hint2":"ABEとACEの面積比も、BGEとCGEの面積比も、BE：ECと等しいよ。それぞれ引き算をして残る部分を考えよう。今回はABGの面積がわかっているね。"},{"title":"類題5 （2）AD：DB","hint1":"AF：FCから、三角形ABGとCBGの面積の比を考え、BCGの面積を求めよう。","hint2":"今度はCDの両側にある三角形ACGとBCGを比べよう。この面積比がAD：DBになるよ。（1）で求めた面積も使ってね。"},{"title":"類題5 （3）AG：GE","hint1":"三角形ABGとEBGなら、AG・GEを底辺として、高さが等しいね。まだわからない面積はどれかな？","hint2":"三角形BCGを、BE：ECでBGEとCGEに分けよう。わかったBGEの面積と、問題文にあるABGの面積を比べよう。求める順番はAGが先だよ。"}],"基本問題1":[{"title":"（1）正方形CDEFの面積","hint1":"三角形ADEとACBを比べよう。直角と角Aに印をつけ、対応する辺を探してね。","hint2":"AD：DEがわかったら、DE＝DCを使ってAD：DCに直そう。ACの長さから正方形の1辺を求め、その後で面積にしよう。"},{"title":"（2）三角形AEDとEBFの面積比","hint1":"DEとEFは正方形の辺なので等しいね。この2辺をそれぞれ底辺にしてみよう。","hint2":"2つの三角形の高さはADとBF。正方形の1辺を使って、この2つの長さを求めて比べよう。"}],"基本問題2":[{"title":"（1）正方形BEFDの1辺","hint1":"大きな三角形ABCと、左側の三角形ADFを比べよう。","hint2":"AD：DFを求め、DF＝DBを使おう。ADとDBの合計がABになるね。"},{"title":"（2）正方形EGHIの1辺","hint1":"今度は三角形CFEの中にある、小さい正方形だけに注目しよう。","hint2":"FEは（1）の1辺、CEはBCからBEを引いた長さ。三角形CFEとCHGは相似なので、FE：ECからHG：GCを求めよう。正方形の辺HGとEGは等しく、EGとGCの合計はECになるよ。"}],"基本問題3":[{"title":"（1）CDの長さ","hint1":"三角形ABCの面積は、直角をはさむ2辺から求められるね。","hint2":"今度はABを底辺、CDを高さとして、同じ面積を表そう。高さを求めるには面積をどう使えばよいかな？"},{"title":"（2）ADの長さ","hint1":"三角形ADCとACBの等しい角に印をつけよう。","hint2":"AD：ACは、大きな三角形のどの2辺の比に等しいかな？ 長さがわかっている対応する辺を使おう。"}],"基本問題4":[{"title":"（1）BDの長さ","hint1":"三角形ABDに注目し、直角と30度、斜辺を確認しよう。","hint2":"30度・60度・90度の三角形は、正三角形を半分にした形。30度の向かいのBDは、斜辺ABとどういう関係かな？"},{"title":"（2）ADの長さ","hint1":"三角形BCDにも30度の角があるよ。どの角か調べ、BCとCDの関係を考えよう。","hint2":"大きな三角形でもACとBCの関係がわかるね。CDからBC、BCからACへ進み、最後にACからCDを引こう。"}],"基本問題5":[{"title":"（1）EFの長さ","hint1":"AからDCに平行な線を引き、EF・BCとの交点をH・Gとしよう。","hint2":"BGは下底と上底の差。AE：ABからEH：BGを求め、EFにするにはHFを足そう。"},{"title":"（2）AE：EB","hint1":"（1）と同じ補助線で、EFとBCから共通の幅ADを取り除こう。","hint2":"残った幅の比からわかるのはAE：AB。ABのうちAE以外の部分がEBだね。"},{"title":"（3）上の台形は全体の何倍か","hint1":"今回は（2）の条件を使うよ。2つの台形の上底・下底と、高さの比を書こう。","hint2":"高さの比はAE：AB。「上底＋下底」に高さの比の数をかけて面積を比べ、小さい方を全体で割ろう。"}],"基本問題6":[{"title":"（1）EFの長さ","hint1":"AE：ABを考えよう。AE：EG：GBのうち、ABはどこまでかな？","hint2":"AからDCに平行な線を引こう。下底と上底の差のうち、AE：ABに当たる長さを上底へ足そう。"},{"title":"（2）台形EGHFの面積","hint1":"面積に必要なのはEF、GH、そして2本の間の高さだね。","hint2":"GHはAG：ABを使って（1）と同じように求めよう。高さは全体の高さDCのうちEG：ABに当たる分。EGそのものを高さにしないようにね。"}],"基本問題7":[{"title":"（1）左下の三角形","hint1":"左端の頂点と、下の辺の右端を結ぼう。色の三角形を含む、少し大きい三角形ができるね。","hint2":"大きい三角形は、中心から分けた6つの正三角形の1つと面積が等しいよ。色の部分の底辺が下の辺のどれだけかを使おう。"},{"title":"（2）左上から下へ伸びる三角形","hint1":"左上の頂点と、下の辺の右端を結ぼう。下の辺全体を底辺とする三角形で考えよう。","hint2":"その大きい三角形の高さは、中心から下の辺までの高さの2倍。まず全体に対する面積を求め、底辺の3等分を使って色の部分を取り出そう。"},{"title":"（3）右側の四角形","hint1":"右上と右下の頂点を結び、色の四角形を2つの三角形に分けよう。","hint2":"右端を含む三角形と、下の辺の一部分を底辺とする三角形を別々に求めよう。後者は下の辺全体を底辺にした三角形と、高さが等しいよ。"}],"基本問題8":[{"title":"（1）アは全体の何倍か","hint1":"ADを引くと、正六角形が左右の同じ形に分かれないかな？","hint2":"正六角形の中心を通る対角線は、図形を対称な2つに分けるよ。アがどちらの部分か確かめよう。"},{"title":"（2）イは全体の何倍か","hint1":"三角形IBCの形と1辺の長さを調べよう。正六角形の1辺と比べてみてね。","hint2":"IBCは、中心から分けた正三角形と合同になるよ。同じ大きさの三角形が正六角形にいくつ入るかで比べよう。"},{"title":"（3）ウは全体の何倍か","hint1":"ウは、三角形IGHから三角形IBCを引いた形だね。","hint2":"AG・HDと正六角形の1辺からIG・IHを求めよう。共通の角Iをはさむので、IGHとIBCの面積比は（IG×IH）：（IB×IC）。差を取り、（2）を使って全体に対する割合にしよう。"}],"基本問題9":[{"title":"（1）AE：EC","hint1":"BEの両側の三角形ABFとCBFに注目しよう。","hint2":"FはBE上にあるので、ABF：CBFはAE：ECと等しいよ。対応する面積の順番を確認しよう。"},{"title":"（2）AF：FD","hint1":"ABFとACFを合わせた部分と、BCFを比べてみよう。","hint2":"AF・FDを底辺にした三角形をB側とC側でそれぞれ考えると、高さが等しいよ。上側2つの面積の合計と、下側の面積を比べよう。"}],"基本問題10":[{"title":"（1）ABGとACGの面積比","hint1":"ADの左右の部分に注目し、BD：DCが使えないか考えよう。","hint2":"ABDとACDも、BGDとCGDも同じ底辺比。引き算して残るABGとACGも、その比になるね。"},{"title":"（2）ABG：BCG：ACG","hint1":"AF：FBから、ACGとBCGの面積比もわかるよ。","hint2":"（1）と今の比で、共通のACGの比の数をそろえよう。答える順番はABG、BCG、ACGだよ。"},{"title":"（3）AE：EC","hint1":"BEの両側の三角形ABGとCBGを探そう。","hint2":"（2）で求めた面積比から、AE：ECを取り出せるよ。どちらの面積がAE側か確かめよう。"},{"title":"（4）AG：GD","hint1":"AG・GDを底辺にした三角形を考えよう。上側は2つの三角形に分かれているね。","hint2":"ABGとACGの面積を合わせたものを、BCGの面積と比べよう。同じ単位でそろえた（2）の比の数を使ってね。"}],"基礎演習1":[{"title":"（1）CF：FE","hint1":"三角形CFEとCABの共通の角C・直角に印をつけよう。","hint2":"CFとFEに対応する大きな三角形の辺を、同じ順番で比べよう。"},{"title":"（2）正方形ADEFの面積","hint1":"（1）のFEを、等しい辺AFに置きかえて考えよう。","hint2":"CFとAFの合計がAC。ACを比で分けて1辺を求め、面積にしよう。"},{"title":"（3）DBEとFECの面積比","hint1":"底辺をDEとFEにすると、長さが等しいね。","hint2":"高さになるDBとFCを求めよう。高さの比が、そのまま面積比になるよ。"}],"基礎演習2":[{"title":"（1）AD：DC","hint1":"三角形ADCとACBで、直角と角Aを対応させよう。","hint2":"AD・DCに対応するのはどの2辺かな？ 向きではなく角の印で確かめよう。"},{"title":"（2）AD：DB","hint1":"右と左の小さな三角形を使い、DC：DBも調べよう。","hint2":"AD：DCとDC：DBのDCを同じ比の数にそろえよう。そこからAD：DBを取り出そう。"}],"基礎演習3":[{"title":"（1）EFの長さ","hint1":"AからDCに平行な線を引こう。左側に相似な三角形ができるね。","hint2":"下底と上底の差のうち、AE：ABに当たる分だけ幅が増えるよ。求めた増加分を上底に足そう。"},{"title":"（2）AEFDとABCDの面積比","hint1":"各台形の「上底＋下底」を書き、高さの比も書こう。","hint2":"高さの比はAE：AB。幅の和と高さの比の数をかけて、2つの面積を比べよう。"},{"title":"（3）台形AEFDの面積","hint1":"（2）で得た比のうち、全体ABCDがどちらかを確かめよう。","hint2":"全体の面積を全体側の比の数で割り、上の台形側の比の数をかけよう。2つの比の数を足す必要があるか、図で考えてね。"}],"基礎演習4":[{"title":"（1）三角形ACEの面積","hint1":"色の外に残る三角形ABC、CDE、EFAを調べよう。","hint2":"それぞれ、中心から分けた正三角形1つと面積が等しいよ。全体から外側の三角形を引こう。"},{"title":"（2）右側の四角形","hint1":"CDの中点をMとして、FDを引こう。色の部分はFDEとFDMに分かれるね。","hint2":"FDEは6等分の1つと同じ面積。FDMは、FDCの面積をDM：MCで分けよう。FDCの高さは中心からCDへの高さの2倍だよ。"}],"基礎演習5":[{"title":"（1）ABG：AGC","hint1":"AEの両側にある三角形の面積比を考えよう。","hint2":"BE：ECが使えるよ。大きい三角形から小さい三角形を引いても、左右の比は変わらないね。"},{"title":"（2）ABG：GBC：AGC","hint1":"（1）とABGの面積から、AGCの面積が求められるね。","hint2":"全体からABGとAGCを引いてGBCを求めよう。3つを指定された順番に並べて比にしよう。"},{"title":"（3）AG：GE","hint1":"AE上のAGとGEを底辺にする三角形を探そう。","hint2":"ABGとAGCの面積の合計を、GBCの面積と比べよう。B側・C側のそれぞれで高さが等しいことが使えるよ。"},{"title":"（4）BG：GF","hint1":"今度はBF上のBGとGFを底辺にしよう。","hint2":"B側にあるABGとBCGの面積を合わせ、反対側のACGと比べよう。"},{"title":"（5）AD：DB","hint1":"CDの両側にある三角形ACGとBCGに注目しよう。","hint2":"ACG：BCGがAD：DBと等しいよ。求める辺の順番と、面積の順番をそろえよう。"},{"title":"（6）AF：FC","hint1":"BFの両側にある三角形ABGとCBGに注目しよう。","hint2":"（2）から、その2つの面積比を取り出そう。AF側に対応する面積はどちらかな？"},{"title":"（7）CG：GD","hint1":"CD上のCGとGDで図を分けて考えよう。","hint2":"C側のACGとBCGの面積を合わせ、AとBの間に残るABGと比べよう。"}],"練習問題1":[{"title":"（1）DF：AD","hint1":"三角形ADFとABCの角を対応させよう。","hint2":"DFはBC、ADはABに対応するよ。対応する辺を同じ順番で比べよう。"},{"title":"（2）AD：DB","hint1":"DF＝BEなので、（1）とDB：BEをつなげられるね。","hint2":"共通のBE（DF）の比の数をそろえて、ADとDBを同じ単位で表そう。"},{"title":"（3）長方形DBEFの面積","hint1":"（2）の比でABを分ければ、DBの長さがわかるね。","hint2":"DB：BEからBEも求め、長方形のたてと横をかけよう。"}],"練習問題2":[{"title":"（1）EH：HG","hint1":"三角形EHGとEFDを比べよう。EFの長さは図のどの長さから求められるかな？","hint2":"BFからBEを引くとEF。EH・HGに対応する辺を使って比を作ろう。"},{"title":"（2）色の三角形の面積","hint1":"底辺ECは求められるね。高さGHを、左右2つの相似から考えよう。","hint2":"（1）のEH：HGと、三角形CHGから得られるCH：HGをそろえよう。EH＋HC＝ECを使えばGHがわかるよ。"}],"練習問題3":[{"title":"正方形DEFGの1辺","hint1":"CからABへ垂線を引き、その高さを三角形ABCの面積から求めよう。","hint2":"FGはABと平行だから、三角形CFGとCABは相似。正方形の1辺を□とすると、底辺の比は「□：AB」、高さの比は「全体の高さから□を引いた長さ：全体の高さ」。この2つの比をそろえよう。"}],"練習問題4":[{"title":"（1）GF：FC","hint1":"DからBCへ垂線を引き、交点をKとしよう。三角形DKCができるね。","hint2":"DKはABと等しく、KCはBCとADの差。三角形GFCとDKCの相似から比べよう。"},{"title":"（2）正方形BFGEの1辺","hint1":"GF＝BFだから、（1）をBF：FCに読みかえられるね。","hint2":"BFとFCを合わせた長さはBC。BCをその比で分けよう。"}],"練習問題5":[{"title":"三角形GFHの面積","hint1":"全体から、四角形ABGF・三角形FEH・四角形GCDHを引く方法を考えよう。","hint2":"BFを引けばABGFはABFとBGFに分けられるよ。FEHはFEDを底辺比で分けよう。GCDHはBCとEDを延ばした交点Nを使い、三角形GNHからCNDを引くと求めやすいね。"}],"練習問題6":[{"title":"（1）AIの長さ","hint1":"中心をOとして、正三角形AOBを描こう。IはAO上にあるよ。","hint2":"BFはAOをどこで横切るかな？ 正三角形の頂点Bから向かいの辺AOへ引いた垂線は、その辺の中点を通るよ。"},{"title":"（2）HDの長さ","hint1":"三角形FIHとFBGを比べよう。IがBFの真ん中であることを使えるね。","hint2":"相似からIHを求めよう。ADは正六角形の1辺とどんな関係かな？ ADからAIとIHを引けばHDになるよ。"},{"title":"（3）台形EFHDと全体の面積比","hint1":"正六角形の右半分は台形AFED。その中に色の台形があるね。","hint2":"EFHDとAFEDは、平行な辺の間の距離が同じ。平行な2辺の和で面積を比べ、右半分と全体の関係も使おう。"}],"練習問題7":[{"title":"（1）EF：FB","hint1":"三角形ABEの中で、Aから斜辺BEへ垂線AFが引かれていると見よう。","hint2":"小さな2つの三角形の相似からEF：AFとAF：FBを求め、共通のAFをそろえてつなごう。"},{"title":"（2）EDの長さ","hint1":"三角形ABEとBCAの等しい角を探そう。BEとACが垂直なことが手がかりだよ。","hint2":"相似からBCを求めればADもわかるね。EDはAD全体ではないので、最後にAEを引こう。"},{"title":"（3）BF：FG：GB","hint1":"まずBF・AFを、BEをもとにした比で表そう。Gは長方形の対角線の交点だよ。","hint2":"ABFとEBAの相似でAF：BEもわかるね。さらにAC：BEを調べ、AG＝GB＝ACの半分を使おう。FGはAGからAFを引いた長さだよ。"}],"練習問題8":[{"title":"（1）CF：FD","hint1":"DからAEに平行な線を引き、BCとの交点をKとしよう。","hint2":"BDKとBAEの相似でBKを求めると、CKもわかるね。今度はCFEとCDKを比べよう。CFとFDは、全体CDを分けた2つの部分だよ。"},{"title":"（2）四角形BEFDの面積","hint1":"三角形BCDから三角形CEFを引く形にできるね。","hint2":"まず三角形CEDの面積を求めよう。CEFとFEDは高さが等しいので、（1）のCF：FDでCEDの面積を分けられるよ。"}],"練習問題9":[{"title":"（1）BP：PD","hint1":"CPを補助線として引こう。BE：ECからABP：ACPがわかるよ。","hint2":"AD＝DCなので、ABPとBCPの面積も等しいね。B側のABP＋BCPと、ACPの面積を比べるとBP：PDになるよ。"},{"title":"（2）BP：PQ：QD","hint1":"CQも引き、（1）と同じ方法でBQ：QDを求めよう。","hint2":"BP：PDとBQ：QDで、全体BDの比の数をそろえよう。PQはBQからBPを引いた長さだね。"},{"title":"（3）四角形EFQPは全体の何倍か","hint1":"四角形EFQPは、三角形AEFから三角形APQを引いた形だよ。","hint2":"AEFは底辺EF：BCで全体と比べられるね。APQは、三角形ABDを底辺PQ：BDで分けて求めよう。どちらも全体ABCをもとにした割合にしてから引こう。"}],"標準演習1":[{"title":"（1）図2の色の部分","hint1":"斜めの2辺の交点をG、GからBCへの垂線の足をHとしよう。色の部分はABCから三角形FGCを引いた形だね。","hint2":"左右の相似からFH：GHとCH：GHを求めよう。FH＋HC＝FCなのでGHがわかるよ。重なる三角形の面積を全体から引こう。"},{"title":"（2）図3の色の部分","hint1":"FDとABの交点をY、ACとDEの交点をX、ACとFDの交点をGとしよう。DEFから、はみ出すFBYとDGXを引こう。","hint2":"FBYとFEDの相似でBY、CEXとCBAの相似でEXを求めよう。次にAYGとXDGを比べると、Gの左右の幅の比がAY：DXになるよ。左右の幅の和はBEなので、DGXの面積も求められるね。"}],"標準演習2":[{"title":"（1）EFの長さ","hint1":"上底から下底まで、幅は全部でどれだけ増えるかな？","hint2":"AからDCに平行な線を引くと、増加分を相似で考えられるよ。EFは上から何段目かを確かめよう。"},{"title":"（2）GHの長さ","hint1":"GHまでの位置は、上から全体のどれだけかな？","hint2":"上底に足す幅の増加分を、AG：ABで求めよう。GHそのものを下底の同じ割合にしないようにね。"},{"title":"（3）台形EGHFの面積","hint1":"まず台形全体の面積と上下の底辺から、全体の高さを求めよう。","hint2":"真ん中の段の高さは全体の高さを3等分した1つ。上底・下底には（1）（2）の長さを使おう。"}],"標準演習3":[{"title":"（1）三角形FGEの面積","hint1":"まず三角形FDEの面積を、中心から分けた正三角形と比べよう。","hint2":"GはDEの中点。FGEとFGDは高さが等しいので、底辺の比でFDEの面積を分けよう。"},{"title":"（2）四角形BCDGの面積","hint1":"BDを引くと、BCDとBDGに分けられるね。","hint2":"BCDは6等分の1つと同じ面積。BDGはBDEをDG：GEで分けよう。BDEは底辺DEを共有する中心の三角形と比べると、高さの関係がわかるよ。"},{"title":"（3）三角形BGFの面積","hint1":"色分けすると、全体から引ける部分が見えてくるよ。","hint2":"正六角形からABF、（1）のFGE、（2）のBCDGを引こう。どの部分も重なりなく引けているか、図を指でたどろう。"}],"標準演習4":[{"title":"（1）AF：FB","hint1":"AEを引こう。AD：DCから、ABEとCBEの面積比がわかるね。","hint2":"全体ABCを比の数で表し、BCEとABEを取り出すと、残りのACEもわかるよ。AF：FBはACEとBCEの面積比から求めよう。"},{"title":"（2）CDEとABCの面積比","hint1":"まず三角形BCDは、ABCのどれだけか考えよう。","hint2":"底辺CD：CAでBCDの割合がわかるね。そこから問題文のBCEの割合を引けばCDEになるよ。"}],"標準演習5":[{"title":"（1）AP：PC","hint1":"対角線ACは、平行四辺形の面積をどう分けるかな？","hint2":"三角形ADCの面積からAPDを引いてPCDを求めよう。APDとPCDは高さが共通なので、面積比をAP：PCに戻せるよ。"},{"title":"（2）三角形CPFの面積","hint1":"ADとCFが平行なので、APDとCPFは相似だね。","hint2":"（1）のAP：PCが相似比。面積比は、相似比のそれぞれの数を2回かけた比になるよ。"},{"title":"（3）DP：PQ：QF","hint1":"まず相似からDP：PFとAD：CFを求めよう。次にECとDFの交点Qを調べよう。","hint2":"CEをEの先へ、DAをAの先へ延ばし、交点をKとしよう。KAEとCBEの相似からAK：BCを求め、BC＝AD、DK＝DA＋AKを使ってDK：ADに直そう。KDQとCFQでDQ：QFを求め、全体DFをそろえてPQを差で取り出そう。"},{"title":"（4）三角形PQCの面積","hint1":"PQCとQFCは、底辺をPQ・QFとすると高さが等しいね。","hint2":"（2）のCPFを、（3）でわかったPQ：QFで分けよう。"},{"title":"（5）四角形AEQPの面積","hint1":"三角形AECから三角形PQCを引いた形にできるね。","hint2":"AECはABCをAE：EBで分けた一方。平行四辺形の面積からABC、次にAECを求め、（4）の面積を引こう。"}],"チャレンジ1":[{"title":"（1）四角形AFOEの面積","hint1":"三角形ADFとDCEを比べよう。正方形の等しい辺と、CE・DFが垂直であることから、合同だとわかるかな？","hint2":"合同な2つの三角形から、共通の三角形DOEを引いてみよう。残るAFOEと、長さがわかっている2辺で面積を求められる三角形を比べよう。"},{"title":"（2）正方形の面積","hint1":"三角形DOEとCODの相似を、等しい角に印をつけて確かめよう。","hint2":"相似からOEを求めれば、DOEとDOCを合わせたDCEの面積がわかるね。さらにDE：DCを相似から調べ、底辺DCの三角形DCEと、同じ1辺をもつ正方形の面積を比べよう。"}],"チャレンジ2":[{"title":"（1）AF：FE","hint1":"三角形AFCとEFCで、AFとFEを底辺にしてみよう。","hint2":"頂点Cからの高さが等しいね。問題文の面積を、そのまま底辺の比に使おう。"},{"title":"（2）四角形AFBCと三角形ABFの面積比","hint1":"ADFとAFCの面積が等しいので、DFとFCにはどんな関係があるかな？","hint2":"その関係からBDFとBFCも面積が等しいね。四角形AFBCはAFC＋BFC、三角形ABFはADF＋BDFに分けて比べよう。"},{"title":"（3）四角形BEFDの面積","hint1":"求めたい部分はBDF＋BEF。まずABFとBEFの面積比に（1）を使おう。","hint2":"（2）の考え方から、ABF＝ADF＋BFC、BFC＝BEF＋ECF。つまりABFとBEFの面積の差は、ADFとECFの合計になるよ。「比」と「差」でBEFを求め、BDFも求めて足そう。"}],"チャレンジ3":[{"title":"（1）ABGはDCGの何倍か","hint1":"BEの両側にあるABGとBCGの面積比に、AE：ECを使おう。","hint2":"次にBCGを、底辺BD：DCでBDGとDCGに分けよう。比の単位をそろえてABGとDCGを比べよう。"},{"title":"（2）三角形ABCの面積","hint1":"BDGの面積をもとに、DCGとABGの面積を順に求めよう。","hint2":"ABGとBDGを合わせると三角形ABD。ABDとADCは、高さが等しいので底辺BD：DCで比べられるね。ABDの面積から全体ABCへ広げよう。"},{"title":"（3）三角形GHIの面積","hint1":"正三角形を120度回すと、3本の線と交点が重なるね。三角形ABG・BCH・CAIは合同になるよ。","hint2":"全体ABCから、ABG・BCH・CAIを取り除くと、中央のGHIが残るよ。3つの三角形を別々の色でなぞり、重なりなく引けることを確かめて、（1）（2）でわかった面積を使おう。"}]};
const allLessonHints={"6u-1":{"例題1・類題1・2":[{"title":"例題1 (1)","hint1":"高いペンの本数を順に決め、残りのお金で鉛筆が買えるか調べよう。","hint2":"残金が鉛筆の値段で割り切れる場合を表にしよう。両方とも1本以上だよ。"},{"title":"例題1 (2)","hint1":"値下げ後の値段で、(1)と同じ表を作ろう。","hint2":"ペンを何本か増やしたとき、鉛筆を整数本減らせる組み合わせに注目しよう。"},{"title":"類題1","hint1":"25gのおもりの個数を決め、残りを10gで作れるか考えよう。","hint2":"残りの重さが10の倍数になる場合を調べよう。両方とも1個以上という条件も確認しよう。"},{"title":"類題2","hint1":"160円のペンを何本買うか決め、残りの代金を調べよう。","hint2":"残金を120円で割って整数になる場合を数えよう。買える本数の上限から先は調べなくてよいね。"}],"基本問題1":[{"title":"1","hint1":"80gのおもりの個数を決め、残りを50gで作れるか調べよう。","hint2":"残りが50の倍数になる場合を、両方1個以上の範囲で数えよう。"}],"基本問題2":[{"title":"2 (1)","hint1":"5gのおもりの個数を決め、残りの重さを調べよう。","hint2":"残りが3で割り切れる場合を、抜けがないように表にしよう。"},{"title":"2 (2)","hint1":"70円のペンの本数を順に変えて、残金を調べよう。","hint2":"残金が40円で割り切れる場合を数えよう。2種類とも買う条件も確認しよう。"}],"基礎演習1":[{"title":"1 (1)","hint1":"x冊、y冊にそれぞれ何をかけると代金になる？","hint2":"「1冊の値段×冊数」をAとBについて作り、合わせよう。"},{"title":"1 (2)","hint1":"片方の冊数を決め、残金で他方が整数冊買えるか調べよう。","hint2":"両方1冊以上になる範囲で表を作り、条件に合う行を数えよう。"}],"基礎演習2":[{"title":"2","hint1":"240円のノートの冊数を決めて、残金を調べよう。","hint2":"残金が180円で割り切れる場合を数えよう。両方買う条件を忘れずに。"}],"例題2・類題3":[{"title":"例題2 (1)","hint1":"なし1個とりんご3個を、ひと組にしよう。","hint2":"その組の1個あたりの平均の値段を出せば、みかんとの2種類のつるかめ算にできるよ。求めるのは、みかんの個数だよ。"},{"title":"例題2 (2)","hint1":"全部がみかんだった場合と、実際の代金を比べよう。","hint2":"なしやりんごに替えると増える代金を使って表を作ろう。3種類とも買い、(1)の組み合わせは除くよ。"},{"title":"類題3 (1)","hint1":"250円のケーキ4個と210円のケーキ1個を、ひと組にしよう。","hint2":"組の平均の値段を出すと、150円のケーキとの2種類として比べられるよ。"},{"title":"類題3 (2)","hint1":"全部150円だった場合から、代金がいくら増えたか考えよう。","hint2":"高い2種類に替えて増える金額の組み合わせを調べよう。各種類1個以上で、(1)と同じ場合は数えないよ。"}],"基本問題3":[{"title":"3 (1)","hint1":"5円と10円の紙を1枚ずつ、ひと組にしよう。","hint2":"ひと組の代金を、ひと組の枚数で割ると平均の値段になるよ。"},{"title":"3 (2)","hint1":"紙を(1)の平均の値段でまとめ、厚紙と比べよう。","hint2":"紙全体の枚数をつるかめ算で求めよう。そのうち10円の紙はどれだけかな？"}],"基本問題4":[{"title":"4","hint1":"120円のプリン2個と180円のプリン1個をまとめよう。","hint2":"プリンの平均の値段とケーキの値段でつるかめ算をしよう。最後にプリンを2対1に分けよう。"}],"基本問題5":[{"title":"5","hint1":"全部60円の鉛筆だった場合から、増えた代金を考えよう。","hint2":"100円・90円に替えて増える金額の組み合わせを表にしよう。各種類1本以上で、合計15本になるかも確かめよう。"}],"基本問題6":[{"title":"6","hint1":"全部5gのおもりだった場合と比べよう。","hint2":"15g・30gに替えて増える重さを使って表にしよう。各種類1個以上、合計27個の条件を両方確かめよう。"}],"基礎演習3":[{"title":"3 (1)","hint1":"Bを3本、Cを2本でひと組にしよう。","hint2":"組の代金を組の本数で割ろう。2種類の値段をただ足して2で割らないようにね。"},{"title":"3 (2)","hint1":"図の長方形全体は、全20本がB・Cの平均の値段だったときの代金だよ。","hint2":"その仮の代金と、実際に払った代金の差が、空いている部分になるよ。"},{"title":"3 (3)","hint1":"Aを1本入れると、B・Cの平均の値段より代金がいくら下がる？","hint2":"図の空いている部分をその差で割ると、Aの本数になる。全体から引けばBとCの合計だね。"},{"title":"3 (4)","hint1":"BとCの合計を3対2に分けよう。","hint2":"まず比の1つ分を求めてから、BとCをそれぞれ求めよう。"}],"練習問題1":[{"title":"1 (1)","hint1":"150円のペン2本と200円のペン1本を、ひと組にしよう。","hint2":"ペンの平均の値段を出し、鉛筆とのつるかめ算をしよう。ペンの合計を求めたら2対1に分けよう。"},{"title":"1 (2)","hint1":"1円玉1枚と10円玉5枚を、ひと組にしよう。","hint2":"組の平均の金額を出せば、5円玉とのつるかめ算にできるよ。最後に組に含まれる10円玉を数えよう。"}],"練習問題2":[{"title":"2 (1)","hint1":"80円と100円の鉛筆で、代金が同じになる最小のひと組を作ろう。","hint2":"その組の平均の値段と40円の値段を使い、全体の本数・代金を比べよう。"},{"title":"2 (2)","hint1":"40円の鉛筆から余分な3本を先に取り分けよう。","hint2":"残りの40円と80円は同じ本数。1本ずつの平均の値段を使い、100円とのつるかめ算をしよう。"}],"練習問題3":[{"title":"3 (1)","hint1":"2つ目の買い方から、値段がわかるAの代金を引こう。","hint2":"残った2つの条件でCの本数をそろえ、引き算しよう。先にBの値段を出してからCを求めよう。"},{"title":"3 (2)","hint1":"全部Aだった場合から、BやCに替えたときの代金の変化を考えよう。","hint2":"Bの本数を順に決めてCの本数を調べよう。本数の合計が24本以下なら、残りをAにできるよ。"}],"練習問題4":[{"title":"4 (1)","hint1":"青3個と白1個をひと組にして、その得点を求めよう。","hint2":"全部赤だった場合との差を考えよう。ひと組に替えると、何個分の得点がどれだけ増える？"},{"title":"4 (2)","hint1":"白2個と赤1個をひと組にしよう。","hint2":"その組の1個あたりの平均点と、青1個の点を使って、15個の合計点を比べよう。"}],"標準演習1":[{"title":"1","hint1":"全部40円だった場合から、60円・85円に替えて増える代金を考えよう。","hint2":"2種類の本数を表にし、3種類とも10本以上になる場合を残そう。鉛筆を最多にするには、残り2種類の合計をどうすればよい？"}],"標準演習2":[{"title":"2","hint1":"100円3本と150円2本をひと組にしよう。","hint2":"組の平均の値段と80円の値段でつるかめ算をし、組の中の100円の本数に戻そう。"}],"標準演習3":[{"title":"3","hint1":"鳥1羽とバッタ3匹をひと組にしよう。","hint2":"組の1匹あたりの足の平均本数を出すと、猫とのつるかめ算にできるよ。"}],"標準演習4":[{"title":"4 (1)","hint1":"全部60円のお菓子だった場合との差を考えよう。","hint2":"キャラメル・チョコに替えて増える代金の組み合わせを表にしよう。種類ごとの個数と合計25個の条件を確かめよう。"},{"title":"4 (2)","hint1":"60円のラムネと90円のキャラメルで、代金が同じになる最小のひと組を作ろう。","hint2":"組の平均の値段とチョコの値段を使って個数を求め、キャラメルの個数に戻そう。"}],"チャレンジ1":[{"title":"1 (1)","hint1":"BとCを入れ替えて増えた代金を、1本あたりの値段の差で割ろう。","hint2":"BとCの本数の和と差から本数を求めよう。Aの代金を除き、残りのBを全部Cに替えると、Bの本数×値段の差だけ安くなる。その仮の代金をB・Cの合計本数で割ると、Cの値段が出せるよ。最後に値段の差を足してBの値段を求めよう。"},{"title":"1 (2)","hint1":"全部Aだった場合と比べ、B・Cに替えると代金がどう変わるか調べよう。","hint2":"Bの本数を多いほうから試し、残りの本数・代金をAとCで作れるか確認しよう。3種類とも1本以上だよ。"},{"title":"1 (3)","hint1":"Bの本数を1つ決めると、残りの本数と代金が決まるよ。","hint2":"AとCの本数が整数で0以上になる場合を表にしよう。この小問では、買わない種類があってもよいよ。"}],"チャレンジ2":[{"title":"2 (1)","hint1":"BとCの重さは、ともに7の倍数。全体の重さはどうかな？","hint2":"Aの重さの合計も7の倍数になる必要があるね。各種類1個以上で、700gを超えない範囲からAの個数をしぼろう。"},{"title":"2 (2)","hint1":"Aの重さを取り除き、残りをBとCで作ろう。","hint2":"残りの重さとCの重さが5の倍数であることから、Bの個数をしぼろう。残りでCが1個以上になるか確かめよう。"}],"チャレンジ3":[{"title":"3 (1)","hint1":"みかんとりんごの代金は、どちらも50円の倍数。全体からなし代を引いた金額も50円の倍数になるね。","hint2":"なしの個数を順に試し、残金が50円の倍数になるものを探そう。みかんとりんごも1個以上買える残金が必要だよ。"},{"title":"3 (2)","hint1":"全体の代金から、(1)のなし代を引こう。","hint2":"みかんを1個、2個…と増やし、残金でりんごが整数個買える場合を探そう。両方1個以上の条件で、みかんの個数をすべて挙げよう。"}],"例題3・類題4":[{"title":"例題3 (1)","hint1":"6年前にいた3人を、今の年齢に直そう。","hint2":"3人分の年齢の増加を足し、今の4人の合計との差を求めよう。"},{"title":"例題3 (2)","hint1":"母と自分の年齢の差は、生まれたときから変わらないよ。","hint2":"妹を除いた3人の合計から母と自分の年齢差を引くと、自分の年齢の何倍分になる？　最後に自分と妹の差を求めよう。"},{"title":"類題4 (1)","hint1":"10年前にいた3人の合計を、今の合計に直そう。","hint2":"その合計と今の4人の合計との差が、誰の年齢になるかな？"},{"title":"類題4 (2)","hint1":"母は姉より何歳上？　父の年齢も姉の年齢をもとに表そう。","hint2":"ひろとさん以外の3人の合計から、姉の年齢を求めよう。姉がひろとさんより何歳上か考えよう。"}],"基本問題7":[{"title":"7 (1)","hint1":"11年前にいた3人の合計を今の年齢に直そう。","hint2":"今の4人の合計との差は、弟の年齢になるね。"},{"title":"7 (2)","hint1":"今の合計から弟の年齢を除こう。","hint2":"残りは「父母の合計」と「自分」。父母の合計が自分の何倍かを使おう。"},{"title":"7 (3)","hint1":"父母の合計は(2)から求められるよ。","hint2":"父と母の年齢の差を使い、和差算で分けよう。"}],"基本問題8":[{"title":"8 (1)","hint1":"10年前にいた3人の合計を今に直そう。","hint2":"今の合計との差が双子2人分。同じ年齢だから等しく分けよう。"},{"title":"8 (2)","hint1":"家族の合計を、両親と子ども3人に分けよう。","hint2":"合計の比から子ども3人分を求め、双子2人分を引こう。"}],"基礎演習4":[{"title":"4 (1)","hint1":"10年前にいた4人の合計を、今の年齢に直そう。","hint2":"今の5人の合計との差が、弟の年齢だよ。"},{"title":"4 (2)","hint1":"弟から父、父から母の年齢が求められるね。","hint2":"4年前の父とさちさんの関係から、さちさんの今の年齢を求めよう。家族の合計で妹を求め、母との年齢差を考えよう。"},{"title":"4 (3)","hint1":"母と妹の年齢の差は、昔も変わらないよ。","hint2":"母が妹の5倍だったとき、年齢の差は妹の何倍？　そのときの妹と今の妹を比べよう。"}],"練習問題5":[{"title":"5 (1)","hint1":"今一緒に暮らす4人の年齢の合計を、5年前に戻そう。","hint2":"5年前の5人の合計との差が、姉の5年前の年齢。そこから今に戻そう。"},{"title":"5 (2)①","hint1":"姉を含めた今の5人の合計を求めよう。","hint2":"15年前にいた4人の合計を今に直し、5人の合計から引こう。"},{"title":"5 (2)②","hint1":"今の4人の合計から、あやさんと弟を引くと両親の合計になるね。","hint2":"あやさんと弟の年齢差は、両親の年齢差でもあるよ。和差算で父を求めよう。"}],"標準演習5":[{"title":"5 (1)","hint1":"10年前にいた3人の合計を今に直して妹を求め、4歳差から自分を求めよう。","hint2":"両親の合計と子ども2人の合計は、どちらも毎年2歳ずつ増える。その差と2.5倍の関係から、そのときの子どもの合計を求めよう。"},{"title":"5 (2)","hint1":"両親の合計と子ども2人の合計の差を使おう。","hint2":"両親の合計が12倍なら、差は子どもの合計の何倍？　今との差を、1年あたりの増減に直そう。"}],"標準演習6":[{"title":"6 (1)","hint1":"3年後の3人の合計を求めよう。母は、そのときの自分の3倍だね。","hint2":"祖母と母は30年前から3年後まで同じだけ年をとる。「祖母＝母の3倍」からずれる分を考え、3年後の合計に結びつけよう。"},{"title":"6 (2)","hint1":"まず(1)を使って、祖母と自分の今の年齢を求めよう。","hint2":"2人の年齢差は変わらない。祖母が7倍だったとき、差は自分の何倍だったかな？"}],"例題4・類題5":[{"title":"例題4 (1)","hint1":"「少なくとも片方が好きな人」は何人？","hint2":"その人数から国語が好きな人を除くと、算数だけが好きな人が残るよ。"},{"title":"例題4 (2)","hint1":"重なりを最も小さくする場合と、最も大きくする場合を別々に考えよう。","hint2":"最小ではクラスの人数からはみ出す分に注目。最大では少ないほうの集団をすべて重ねよう。(1)の条件は使わないよ。"},{"title":"類題5 (1)","hint1":"犬が好きな人の中には、両方好きな人もいるよ。","hint2":"犬が好きな人数から、両方好きな人数を引こう。"},{"title":"類題5 (2)","hint1":"2つの人数の合計がクラスの人数を超える分は、必ず重なるよ。","hint2":"重なりの最大は、少ないほうの人数まで。(1)の重なりの人数には固定しないよ。"}],"基本問題9":[{"title":"9 (1)","hint1":"自転車を利用する人と利用しない人を合わせると、クラス全員になるよ。","hint2":"クラスの人数から、電車を利用する人数を引こう。"},{"title":"9 (2)","hint1":"自転車と電車の利用者を足すと、両方利用する人を2回数えるよ。","hint2":"重なりを1回引いてから、どちらも利用しない人を足そう。"},{"title":"9 (3)","hint1":"2つの人数の合計と、クラスの人数を比べよう。","hint2":"最小はクラスからはみ出す分。最大は少ないほうの人数まで重ねられるよ。"}],"基本問題10":[{"title":"10 (1)","hint1":"「B公園に行った人」を、行っていない人数から求めよう。","hint2":"Bに行った人からBだけの人を除けば、両方に行った人が残るね。"},{"title":"10 (2)","hint1":"少なくとも片方に行った人が多いほど、どちらも行かない人は少なくなるよ。","hint2":"AとBをできるだけ離す場合と、少ないほうをすべて重ねる場合を図にしよう。(1)の条件は使わないよ。"}],"基礎演習5":[{"title":"5 (1)","hint1":"まず、少なくとも片方が好きな人数を求めよう。","hint2":"そこから体育が好きな人を引くと、音楽だけが好きな人になるよ。"},{"title":"5 (2)","hint1":"2つの人数の合計が、全体を超えた分は必ず重なるよ。","hint2":"最大は、少ないほうの集団をすべて重ねたとき。(1)の条件は使わないよ。"}],"練習問題6":[{"title":"6","hint1":"全員を1として、少なくとも片方に参加する割合を求めよう。","hint2":"スキーとハイキングの割合を足したものとの差が、両方参加する割合。実際の両方の人数と対応させよう。"}],"練習問題7":[{"title":"7 (1)","hint1":"英語だけが好きな人数を1つ分とすると、数学だけが好きな人数は何つ分？","hint2":"両方好きな人数は共通なので、英語と数学の人数の差から「だけ」の人数を求められるよ。英語が好きな人数から英語だけの人数を引けば、両方好きな人数になるね。"},{"title":"7 (2)","hint1":"英語だけが好き・数学だけが好き・両方好き・どちらも好きではない、の4つに分けよう。","hint2":"両方好きな人数から、どちらも好きではない人数を求め、重ならない4つの人数を足そう。"}],"練習問題8":[{"title":"8 (1)","hint1":"音楽と体育、音楽と図工の重なりには、3つとも好きな人も含まれるよ。","hint2":"音楽の人数から2つの重なりを引くと、3つとも好きな人を2回引いてしまう。1回分戻そう。"},{"title":"8 (2)","hint1":"3教科の人数を足し、2教科ずつの重なりを引こう。","hint2":"この計算では、3つとも好きな人を何回数えている？　少なくとも1つ好きな人数になるように補おう。最後にクラス全体から引くと、どれも好きではない人数になるよ。"}],"練習問題9":[{"title":"9 (1)","hint1":"英語とフランス語の人数を足し、先生全体と比べよう。","hint2":"最小は全体を超える分。最大は少ないほうの集団をすべて重ねたときだよ。"},{"title":"9 (2)","hint1":"「3か国語すべて話せる人」以外、つまり「少なくとも1つ話せない人」に注目しよう。","hint2":"各言語を話せない人数をできるだけ重ならないように置くと、3つとも話せる人数が最小になる。最大は最も少ない言語の人数を上限に考えよう。"}],"標準演習7":[{"title":"7 (1)","hint1":"3問すべて正解した人は、どの問題の正解者にも含まれるよ。","hint2":"いちばん正解者の少ない問題を上限にしよう。その人数を全部重ねる置き方ができるか確認しよう。"},{"title":"7 (2)","hint1":"全員から「全問不正解」と「第2問だけ正解」を除くと、どんな人が残る？","hint2":"第1問・第3問の少なくとも片方の正解者がわかるね。両方正解を求め、そこから「第1問・第3問だけ正解」を除こう。"}],"例題5・類題6":[{"title":"例題5 (1)","hint1":"まず人数の合計からAとBの合計を出そう。","hint2":"平均点から全員の得点の合計を出し、人数がわかる欄の得点を引こう。残った2種類の点数でつるかめ算をしよう。"},{"title":"例題5 (2)","hint1":"5点の人には「第3問だけ正解」と、もう1種類の正解のしかたがあるよ。","hint2":"第2問の正解者から、3点・8点・10点の人を除こう。5点の内訳がわかれば、第3問の正解者を集められるね。"},{"title":"類題6 (1)","hint1":"人数の合計と、全員の得点の合計をそれぞれ使おう。","hint2":"わかる欄を引けば、AとBの人数の合計と得点の合計が残るよ。"},{"title":"類題6 (2)","hint1":"4点の人を「第3問だけ」と「第1問・第2問」に分けよう。","hint2":"1問だけ正解の人数から、1点と3点の人数を引こう。4点の人のうち、残りが何を正解した人か考えよう。"}],"基本問題11":[{"title":"11 (1)","hint1":"人数の合計からAとBの合計を求めよう。","hint2":"平均点から全得点を出し、既知の欄を引こう。残りの人数と得点でつるかめ算をしよう。"},{"title":"11 (2)","hint1":"1問だけ間違えた人は、2問正解した人。5点の内訳に注目しよう。","hint2":"2問正解の人数から7点・8点の人数を引こう。5点の人を2種類に分け、第3問正解の点数を集めよう。"}],"基礎演習6":[{"title":"6 (1)","hint1":"全員の人数と全員の得点の合計から、わかる欄を引こう。","hint2":"AとBの人数の合計・得点の合計を使って、つるかめ算をしよう。"},{"title":"6 (2)","hint1":"5点には、第3問だけ正解した人も、第1問と第2問を正解した人もいるよ。","hint2":"第3問正解の人数から6点・9点・10点を除いて、5点の内訳を出そう。第1問正解の人を点数ごとに集めよう。"}],"標準演習8":[{"title":"8 (1)","hint1":"人数の合計と、平均点から求めた得点の合計を使おう。","hint2":"既知の欄を除き、AとBの人数・得点でつるかめ算をしよう。"},{"title":"8 (2)","hint1":"30点の人には、第3問だけ正解した人と、第1問・第2問を正解した人がいるよ。","hint2":"第3問正解の人数から30点の内訳を出そう。第1問正解の人だけの得点合計と人数を集め、その人数で割ろう。"}]},"6u-2":{"例題1・類題1":[{"title":"例題1 (1) 1日にする仕事量の比","hint1":"同じ仕事を、短い日数で終えるのはどちら？　その人の1日分は多いはずだね。","hint2":"仕事全体を、21と28の最小公倍数で置こう。「全体÷かかる日数」で、それぞれの1日分を求めて比べよう。"},{"title":"例題1 (2) 2人で一緒に働く日数","hint1":"2人が一緒に働くと、1日に進む仕事はどうなる？","hint2":"2人の1日分を足そう。全体の仕事の中に、その量が何日分あるかな？"},{"title":"例題1 (3) 春子さんが15日働き、残りを秋子さんがする","hint1":"まず、春子さんが終えた仕事を求めよう。15は「仕事量」かな、それとも「日数」かな？","hint2":"「春子さんの1日分×働いた日数」を全体から引こう。残りを秋子さんの1日分で割ったら、求めたのは誰の日数？　問題は「全部の日数」を聞いているよ。"},{"title":"類題1 (1) 1日にする仕事量の比","hint1":"20日と30日の比を、そのまま仕事量の比にしてよいかな？　速いのはどちら？","hint2":"全体を20と30の最小公倍数で置き、それぞれの日数で割ろう。A君、B君の順に比べよう。"},{"title":"類題1 (2) 2人で一緒に働く日数","hint1":"(1)で求めた2人の1日分を使えるよ。","hint2":"全体を、2人が1日に進める仕事量で割ろう。1人で働くときより早く終わりそうかな？"},{"title":"類題1 (3) A君が14日働いたあと、B君が働く日数","hint1":"全体から、A君が終えた仕事量を引こう。","hint2":"残りの仕事は、B君の1日分の何日分？　今回は「B君が働く日数」を聞いているよ。最初の14日を足す必要があるかな？"}],"基本問題1":[{"title":"1 (1)","hint1":"全体を、24と40の最小公倍数で置こう。","hint2":"全体を各日数で割り、A・Bの順に1日分を比べよう。"},{"title":"1 (2)","hint1":"2人が1日に進める量を足そう。","hint2":"全体の中に、2人分の1日の仕事が何日分あるかな？"},{"title":"1 (3)","hint1":"Aが18日で終えた仕事を求めよう。","hint2":"全体からその量を引き、Bの1日分で割ろう。聞かれているのはBの日数だよ。"}],"基礎演習1":[{"title":"1 (1)","hint1":"全体を20と30の最小公倍数で置こう。","hint2":"全体を各日数で割って、1日分の比に直そう。"},{"title":"1 (2)","hint1":"2人の1日分を足そう。","hint2":"全体を、2人が1日に進める量で割ろう。"},{"title":"1 (3)","hint1":"Aの6日分を、仕事量に直そう。","hint2":"全体から引いて、残りをBの1日分で割ろう。"}],"練習問題2":[{"title":"2 (1)","hint1":"A＋B、B＋C、A＋Cの1日分を並べよう。","hint2":"3つを足すと、それぞれの人を2回ずつ数えるよ。3人の1日分に直して全体を割ろう。"},{"title":"2 (2)","hint1":"3人の1日分から、A＋Cの1日分を引こう。","hint2":"残ったBの1日分で、全体を割ろう。"}],"練習問題3":[{"title":"3 (1)","hint1":"同じ満水量を24と20の公倍数で置こう。","hint2":"2つの組み合わせの1分分の差は、細いホース1本分。そこから太いホース1本分も求めよう。"},{"title":"3 (2)","hint1":"太いホース3本と細いホース4本の1分分を足そう。","hint2":"満水量を割り、分の端数を秒に直そう。小数部分に何をかければ秒になる？"}],"例題2・類題2":[{"title":"例題2 (1) Bだけで働く日数","hint1":"全体を30・12・20の最小公倍数で置き、A、B＋C、A＋Cの1日分を並べてみよう。","hint2":"「A＋C」からAを引くと、誰の1日分が残る？　それを使えば「B＋C」からBの1日分も求められるね。最後に全体とBの1日分を使おう。"},{"title":"例題2 (2) Aが5日休んだときの、全部の日数","hint1":"Aが休んだ分を「何日」ではなく「どれだけの仕事ができなかったか」に直そう。","hint2":"もしAも休まず働いていたら、同じ日数で「実際の全体＋Aが休んだ分」の仕事ができるね。その量を、3人の1日分で割ってみよう。"},{"title":"例題2 (3) 全部で9日かかったとき、Cが休んだ日数","hint1":"もし全員が9日間ずっと働いたら、仕事量はいくつになる？","hint2":"その量と実際の全体の差が、Cが休んだ分の仕事量。Cが1日休むごとに、どれだけ仕事が少なくなるかな？"},{"title":"類題2 (1) A・B・Cの1日分の比","hint1":"全体を22・11・12の最小公倍数で置き、A、B＋C、A＋Cの1日分を出そう。","hint2":"まず「A＋C」からAを引いてCを求めよう。次にBを求め、A・B・Cの順に並べて比を簡単にしよう。"},{"title":"類題2 (2) Aが2日休んだときの、全部の日数","hint1":"Aが2日間で進められたはずの仕事量は？","hint2":"全体にその仕事量を足し、「3人とも休まなかった場合」に直して考えよう。(1)の比を使うなら、全体も同じ尺度になっているか確かめよう。"},{"title":"類題2 (3) 全部で9日かかったとき、Cが休んだ日数","hint1":"全員が休まなかったとしたら、9日間でどれだけ進む？","hint2":"実際の全体との差を求めよう。その差は、Cの1日分がいくつ分かな？"}],"基本問題2":[{"title":"2 (1)","hint1":"全体を、45と30の最小公倍数で置こう。","hint2":"全体をそれぞれの日数で割ると、太郎・次郎の1日分がわかるよ。"},{"title":"2 (2)","hint1":"もし2人とも20日間働いていたら、どれだけの仕事ができる？","hint2":"実際の全体より多い分が、太郎の休んだ分。その量を太郎の1日分で割ろう。"}],"基本問題3":[{"title":"3 (1)","hint1":"全体を32・48・96の最小公倍数で置き、各自の1日分を出そう。","hint2":"3人の1日分を足し、全体を割ろう。"},{"title":"3 (2)","hint1":"Bの3日分とCの6日分を、仕事量に直そう。","hint2":"その量を全体に足すと、全員が休まず働いた場合の仕事量になる。3人の1日分で割ろう。"}],"基礎演習2":[{"title":"2 (1)","hint1":"全体を56・40・35の公倍数で置き、A、A＋B、A＋Cの1日分を出そう。","hint2":"A＋B、A＋CからAを引き、3人それぞれの1日分を並べよう。"},{"title":"2 (2)","hint1":"Aが6日間でできたはずの仕事量を出そう。","hint2":"全体にその量を足して、3人の1日分で割ろう。"}],"例題3・類題3":[{"title":"例題3 (1) A・Bが1時間に入れる水量の比","hint1":"それぞれの条件で「台数×時間」を計算しよう。何台を何時間使ったかを、1台が働く時間にそろえられるよ。","hint2":"どちらの条件でも満水量は同じ。A同士、B同士の共通部分を取り除くと、「Aの何時間分＝Bの何時間分」が残るね。同じ量を短い時間で入れるほうが、1時間分は多いよ。"},{"title":"例題3 (2) 台数を変えたあと、満水までにかかる時間","hint1":"(1)の比をA・Bの1台・1時間分として置こう。最初の条件のどちらかから、満水量を求められるかな？","hint2":"満水量から、最初の2時間で入れた量を引こう。その後もAは3台のまま。Bを1台にしたあとの1時間分で、残りを割ろう。「あと何時間」だから、最初の2時間はどう扱う？"},{"title":"類題3 (1) A・Bが1日にする仕事量の比","hint1":"2つの条件を、それぞれ「Aの1台・1日分×台数×日数」と「Bの1台・1日分×台数×日数」に分けよう。","hint2":"どちらも同じ作業全体を表す。共通部分を引くと、Aの何日分とBの何日分が等しくなる？　求めたいのは「1日分」の比だよ。"},{"title":"類題3 (2) Bを増やしたときの、全部の日数","hint1":"(1)の比で1台・1日分を置き、元の条件から仕事全体を求めよう。次に、最初の7日間で終えた仕事を引こう。","hint2":"「Bをさらに3台増やす」は、Bが全部で何台になること？　変更後の1日分で残りを割ったら、求めたのは「あと何日」。問題が聞く「全部の日数」に直そう。"}],"基本問題4":[{"title":"4 (1)","hint1":"各条件を「台数×時間」に直してAとBを並べよう。","hint2":"同じ全体なので共通部分を引けるよ。残ったAとBの時間分を比べ、1台・1時間分の比に直そう。"},{"title":"4 (2)","hint1":"1時間分の比を使い、元の条件から全体を求めよう。","hint2":"最初の3時間の仕事を引き、変更後のA2台・B3台の1時間分で割ろう。"}],"基本問題5":[{"title":"5 (1)","hint1":"2つの条件を、大人・子どもの「人数×分数」で比べよう。","hint2":"共通部分を除いて1人・1分分の比を出そう。その比から全体を求め、大人5人の1分分で割ろう。"},{"title":"5 (2)","hint1":"全29分を、子どもを増やしたあとの人数で働いたことにしてみよう。","hint2":"実際の全体より多い分は、前半にいなかった子ども2人の仕事量。その2人の1分分で割ると前半の時間だよ。"}],"基礎演習3":[{"title":"3 (1)","hint1":"2つの条件はどちらも満水。共通して入れた分を引こう。","hint2":"Aの増えた時間分とBの減った時間分が等しいよ。その関係を1分分の比に直そう。"},{"title":"3 (2)","hint1":"1分分の比から満水量を求め、Bが最初の8分に入れた量を引こう。","hint2":"残りをAの1分分で割ったら、最初の8分を足して全体の時間にしよう。"},{"title":"3 (3)","hint1":"満水量から、Aが最初の6分に入れた量を引こう。","hint2":"残りをA＋Bの1分分で割ろう。最後に最初の6分を足そう。"}],"練習問題4":[{"title":"4","hint1":"Bが2時間、Cが1時間働く3時間をひと組にしよう。","hint2":"B・Cの1時間あたりの平均の仕事量を出そう。13時間すべてAとした場合との差で、B・Cの時間を求められるよ。"}],"練習問題5":[{"title":"5 (1)","hint1":"満水量を置き、A4台とA1台＋B1台の1時間分を求めよう。","hint2":"A4台からA1台を求め、A＋Bから引くとBが出るね。"},{"title":"5 (2)","hint1":"予定と実際では、残りの水量は同じだね。","hint2":"残りを入れる時間を、予定のA4台と変更後のA2台＋B1台でそれぞれ求め、差を比べよう。"}],"標準演習2":[{"title":"2 (1)","hint1":"全体を10と15の公倍数で置き、A＋B＋CとA＋Bの1日分を出そう。","hint2":"差がCの1日分。A＋BとCを比べよう。"},{"title":"2 (2)","hint1":"「B＋Cが5日とAが17日」を、「3人が5日とAだけが残りの日数」に組み替えよう。","hint2":"全体から3人の5日分を引くと、Aだけの残りの日数分。Aを出せば、(1)を使ってBも求められるよ。"},{"title":"2 (3)","hint1":"全13日を、まずAだけが働いたことにしてみよう。","hint2":"残る仕事量からCの7日分を引くと、Bが働いた分になる。Bが働いた全日数を出し、13日との差を考えよう。"}],"標準演習3":[{"title":"3 (1)","hint1":"AとBをそれぞれ「台数×分数」に直そう。","hint2":"同じ満水量を入れるのに必要な時間分の比を、1台・1分分の比に直そう。"},{"title":"3 (2)","hint1":"比を1台・1分分として置き、元の条件から満水量を出そう。","hint2":"A管2本とB管7本の1分分を足し、満水量を割ろう。"},{"title":"3 (3)","hint1":"満水量から、最初の5分間に入れた量を引こう。","hint2":"残りを、変更後のA管1本とB管3本の1分分で割ろう。「あと」の時間だよ。"}],"標準演習4":[{"title":"4 (1)","hint1":"2つの条件をAとBの「台数×時間」で表そう。","hint2":"共通のAの分を引き、残った関係から1台・1時間分の比を求めよう。"},{"title":"4 (2)","hint1":"1時間分の比を使い、元の条件から全体を求めよう。","hint2":"全体をB6台の1時間分で割ろう。"},{"title":"4 (3)","hint1":"まず予定の時間を求めよう。実際の時間は、その1時間後だね。","hint2":"実際の全時間をA8台で働いたとすると、全体より仕事が多くなる。超えた量を、故障後の1時間あたりの仕事の減り方で割ると、故障後の時間が出るよ。実際の全時間から引いて、故障までの時間に戻そう。"}],"チャレンジ1":[{"title":"1 (1)","hint1":"A3本＋B2本は、A1本の6倍の速さで満水にする、と読み替えよう。","hint2":"両方からA3本分を取り除こう。残った関係をA1本とB1本の1時間分の比に直そう。"},{"title":"1 (2)","hint1":"3時間45分を、時間か分のどちらかに統一しよう。","hint2":"1時間分または1分分の比を使い、A1本＋B2本の条件から満水量を出そう。それを各管の1本分で割ろう。"},{"title":"1 (3)","hint1":"満水量から、Aが最初の2時間で入れた量を引こう。","hint2":"残りをA＋Bの1時間分で割り、最初の2時間を足そう。時間の端数は分に直そう。"}],"練習問題1":[{"title":"1 (1)","hint1":"全体を置き、A、B、B＋Cの1日分を出そう。","hint2":"B＋CからBを引けばCの1日分。全体をその量で割ろう。"},{"title":"1 (2)","hint1":"A・B・Cが順に働く3日間をひと組にしよう。","hint2":"全体に何組分入るか調べ、残りをA、次にB、次にCの順で進めよう。最後は、その日の担当者の1日分で割るよ。"}],"標準演習1":[{"title":"1 (1)","hint1":"3組の1日分を足すと、3人を2回ずつ数えるよ。","hint2":"3人の1日分に直してA＋Cを引こう。全体をBの1日分で割ろう。"},{"title":"1 (2)","hint1":"B＋Cが1日、Aが1日働く2日間をひと組にしよう。","hint2":"何組分進められるか求め、残りをB＋C、次にAの順に進めよう。最後の端数は、その日の1日分で割ろう。"}],"例題4・類題4":[{"title":"例題4 (1) ポンプ1台が毎分くみ出す量","hint1":"最初の水が、何分でなくなった？　そこから1分で実際に減った量を求めよう。","hint2":"ポンプは、その間にわき出る水もくみ出しているよ。「実際に減る量」に何を足せば、ポンプがくみ出す量になる？"},{"title":"例題4 (2) ポンプ2台で空になる時間","hint1":"ポンプ2台がくみ出す量は、(1)の何倍？　わき出す量も2倍になるかな？","hint2":"2台が毎分くみ出す量から、毎分わく量を引こう。最初の水量を「毎分実際に減る量」で割ればよいね。"},{"title":"類題4 (1) ポンプ1台が毎分くみ出す量","hint1":"「毎分」で考えるため、1時間40分を何分かに直そう。","hint2":"最初の水量を、その分数で割ると「毎分実際に減る量」。ポンプの力を求めるには、わき出す水をどう扱えばよいかな？"},{"title":"類題4 (2) ポンプ2台で空になる時間","hint1":"2倍にするのは、どの量？　泉が毎分わき出す量は変わらないよ。","hint2":"2台分のくみ出す量から、わき出す量を引こう。「はじめの量÷毎分実際に減る量」で、時間を求めよう。"}],"基本問題6":[{"title":"6 (1)","hint1":"窓口が1分に進める人数から、1分に加わる人数を引こう。","hint2":"はじめの人数を、その「実際に減る人数」で割ろう。"},{"title":"6 (2)","hint1":"40分で最初の行列をなくすには、1分に何人ずつ減る必要がある？","hint2":"窓口では新しく加わる人も受け付けるよ。実際に減らしたい人数に、何を足せばよい？"}],"基本問題7":[{"title":"7 (1)","hint1":"最初の行列が50分でなくなることから、1分に実際に減る人数を出そう。","hint2":"その人数に毎分加わる人数を足すと、1窓口の1分分になるよ。"},{"title":"7 (2)","hint1":"2窓口の1分分を求めよう。","hint2":"毎分加わる人数を引いてから、はじめの人数を割ろう。加わる人数まで2倍にしないでね。"}],"基礎演習4":[{"title":"4 (1)","hint1":"はじめの水量を24分で割ると、何の量になる？","hint2":"それは1分に実際に減る量。わき出す量を足すとポンプ1台の力になるよ。"},{"title":"4 (2)","hint1":"2台がくみ出す量から、わき出す量を引こう。","hint2":"はじめの水量を、1分に実際に減る量で割ろう。"}],"基礎演習5":[{"title":"5 (1)","hint1":"はじめの行列が32分でなくなることから、1分に実際に減る人数を出そう。","hint2":"毎分加わる人数を足して、1窓口の1分分を求めよう。"},{"title":"5 (2)","hint1":"4分間に入場させるのは、最初の人と、その間に来る人だよ。","hint2":"必要な総人数を、1窓口が4分間に入場させる人数で割ろう。"}],"例題5・類題5":[{"title":"例題5 (1) 1窓口から1分間に入場する人数","hint1":"どちらの場合も、「入場した人数＝最初の人数＋途中で加わった人数」。2つの条件で同じなのは、どの部分？","hint2":"「窓口数×分数」の差と、「途中で加わった人数」の差をそれぞれ求めよう。前者は、1窓口が1分働く分を何回分比べているのかな？　2つの差から1回分を求めよう。"},{"title":"例題5 (2) 最初に並んでいた人数","hint1":"(1)の1窓口の力を使い、4窓口なら1分に何人入場するか求めよう。","hint2":"その人数から、1分に加わる人数を引こう。行列が1分に何人ずつ減るかがわかれば、それが45分続いたときの人数を考えられるね。"},{"title":"例題5 (3) 12分以内になくすための窓口数","hint1":"12分間に入場させるのは、最初にいた人だけかな？　その間に加わる人も数えよう。","hint2":"1窓口が12分間に入場させられる人数を求めよう。必要な総人数をそれで割ると、必要な窓口数がわかる。小数や余りが出たら、全員を入場させるにはどうする？"},{"title":"類題5 (1) 1窓口から1分間に入場する人数","hint1":"50分間に加わる人数と30分間に加わる人数を比べよう。最初の行列の人数は、どちらも同じだね。","hint2":"「3窓口が50分働く分」と「4窓口が30分働く分」を、それぞれ「窓口数×分数」で表そう。その差は、途中で加わる人数の差に対応するよ。"},{"title":"類題5 (2) 最初に並んでいた人数","hint1":"(1)を使って、3窓口が1分に入場させる人数を求めよう。","hint2":"そこから毎分加わる人数を引くと、行列が実際に減る人数になる。それが50分間続いて、行列がなくなったんだね。"},{"title":"類題5 (3) 15分以内になくすための窓口数","hint1":"最初の人数に、15分間に加わる人数を足そう。","hint2":"1窓口が15分間に入場させられる人数と比べよう。窓口を整数個用意するとき、時間内に終わるほうへ調整できているかな？"}],"基本問題8":[{"title":"8 (1)","hint1":"2つの場合の「台数×分数」の差を出そう。","hint2":"くみ出した量の差は、時間の差の間にわいた水量。その対応から1台・1分分を求めよう。"},{"title":"8 (2)","hint1":"4台が1分にくみ出す量から、1分にわく量を引こう。","hint2":"実際に減る量が45分続いたと考えると、はじめの水量がわかるよ。"},{"title":"8 (3)","hint1":"8台がくみ出す量と、わき出す量を比べよう。","hint2":"はじめの水量を、1分に実際に減る量で割ろう。"}],"基本問題9":[{"title":"9 (1)","hint1":"2つの場合にくみ出した水の総量を出そう。","hint2":"総量の差は、時間の差の間にわいた量。時間の差で割ろう。"},{"title":"9 (2)","hint1":"まずはじめの水量を出し、15分間にわく水を足そう。","hint2":"1台が15分間にくみ出せる量と比べよう。台数に端数が出たら、15分以内に終わるように切り上げよう。"}],"基礎演習6":[{"title":"6 (1)","hint1":"2つの場合で、最初の人数は同じだね。","hint2":"入場した総人数の差は、かかった時間の差の間に加わった人数だよ。"},{"title":"6 (2)","hint1":"それぞれの「窓口数×分数」を出し、差を求めよう。","hint2":"その差は1窓口・1分分の何回分？　(1)の人数の差と対応させよう。"},{"title":"6 (3)","hint1":"どちらかの条件で、1分に実際に減る人数を求めよう。","hint2":"その人数にかかった分数をかけると、はじめの行列になるよ。"}],"練習問題7":[{"title":"7 (1)","hint1":"使った総額の差は、長く続けた分だけ多くもらったおこづかいだよ。","hint2":"2つの場合の支出総額の差を、月数の差で割ろう。"},{"title":"7 (2)","hint1":"まず、もともとの貯金額を求めよう。","hint2":"毎月「おこづかい−使う額」ずつ増えるよ。目標の15000円から、ヒント1で求めたはじめの貯金額を引こう。その差を1か月に増える額で割れば、必要な月数になるね。"}],"標準演習5":[{"title":"5 (1)","hint1":"2つの場合にくみ出した総量を求めよう。","hint2":"総量の差を時間の差で割ると、1分にわく量だよ。"},{"title":"5 (2)","hint1":"どちらかの条件で、1分に実際に減る量を出そう。","hint2":"それにかかった分数をかけると、はじめの水量になるよ。"},{"title":"5 (3)","hint1":"8台がくみ出す量から、わき出す量を引こう。","hint2":"はじめの水量をその量で割り、分の端数を秒に直そう。"}],"練習問題6":[{"title":"6 (1)","hint1":"まず、午後1時開始の条件から1窓口の1分分を求めよう。","hint2":"午後2時までの間に行列は増える。その人数を出し、1分に実際に減る人数で割って、開始時刻に足そう。"},{"title":"6 (2)","hint1":"2窓口の1分分から、毎分加わる人数を引こう。","hint2":"最初の行列がなくなるまでの時間を出し、午後1時に足そう。"},{"title":"6 (3)","hint1":"午後1時から3時までに入場させる総人数を出そう。","hint2":"全時間を1窓口で受け付けた場合に足りない人数を、増やす1窓口が担当する。その窓口の稼働時間から、増やした時刻を求めよう。"}],"練習問題8":[{"title":"8 (1)","hint1":"1頭が1週間に食べる量を1とし、2つの場合の総量を比べよう。","hint2":"総量の差を期間の差で割ると、1週間に生える量。草を減らさずに食べ続けられる頭数を考えよう。"},{"title":"8 (2)","hint1":"はじめの草の量を出し、最初の10週間で実際に減った量を引こう。","hint2":"残りを8週間で食べきるには、毎週減らす量に加え、毎週生える量も食べる必要があるね。"}],"練習問題9":[{"title":"9 (1)","hint1":"1台が1時間にくみ出す量を1とし、2つの場合の総くみ出し量を出そう。","hint2":"差を所要時間の差で割ると、1時間にわく量。元の条件から途中でわいた分を引き、はじめの量を求めよう。"},{"title":"9 (2)","hint1":"12台が1時間にくみ出す量から、1時間にわく量を引こう。","hint2":"はじめの水量を、その実際に減る量で割ろう。"}],"標準演習6":[{"title":"6 (1)","hint1":"1頭・1週間分を1として、2つの場合の総食草量の差から、毎週生える量を求めよう。","hint2":"はじめの草の量を出そう。200頭が食べる量から毎週生える量を引き、何週間分あるか考えよう。"},{"title":"6 (2)","hint1":"22週間で食べる総量は、はじめの草と22週間で生える草の合計だよ。","hint2":"60頭が22週間食べる分を除くと、増やした40頭の食べた分。その期間を22週間から引くと、増やす前の期間になる。「何週目」は、その次の週だよ。"}],"チャレンジ2":[{"title":"2","hint1":"はじめの水量を1と置こう。30分で元に戻ることから、1分にわく量を求められるね。","hint2":"2台が1分に実際に減らす量に、わく量を足して2台の力を出そう。4台の力からわく量を引き、はじめの量を割ろう。"}],"チャレンジ3":[{"title":"3 (1)","hint1":"9時15分〜35分と、35分〜45分で、行列が1分に何人ずつ減ったか比べよう。","hint2":"窓口が1つ増えて、実際に減る人数がどれだけ増えた？　来る人数は一定だから、その差が1窓口の力だよ。"},{"title":"3 (2)","hint1":"1窓口の力と2窓口のときの減り方から、毎分来る人数を出し、9時5分の行列を求めよう。","hint2":"並んだ時点で前にいた人だけを追おう。9時15分までは1窓口、その後は2窓口で前の人が進む。後から来た人は自分の後ろに並ぶよ。"}]},"6u-3":{"例題1・類題1":[{"title":"例題1 （1）4の倍数","hint1":"4の倍数かどうかは、下2けたで決まるよ。まず十の位と一の位だけを調べよう。","hint2":"下2けたが「4の倍数」または「00」になる組を、小さい順に書こう。それぞれに百の位をつけるとき、0は使えるかな？ 同じ数字のカードは3枚ずつあるよ。"},{"title":"例題1 （2）3の倍数","hint1":"3つの位の数字の和が3の倍数になればよいね。まず「使う3つの数字」を決めよう。","hint2":"数字を小さい順に書いて組を探し、組ごとに並べ方を調べよう。同じ数字を入れかえただけのものは同じ数。百の位が0になる並べ方と、000も除こう。"},{"title":"類題1 （1）4の倍数","hint1":"例題と同じく、先に下2けたを決めよう。ただし、今回は使える数字に2がないよ。","hint2":"0・1・3・4だけで下2けたを調べ、「00」も忘れずに。それぞれに、0以外の百の位をつける方法を数えよう。"},{"title":"類題1 （2）3の倍数","hint1":"使える数字は0・1・3・4。3つの数字の和が3の倍数になる組を探そう。","hint2":"小さい順に3つの数字を書くと、同じ組を重ねて探さずにすむよ。その後で並べ方を数えよう。「同じ数字があるか」「0があるか」で分けると整理しやすいね。000は3けたの整数ではないよ。"}],"基本問題1":[{"title":"1 (1)","hint1":"百の位から順に決めよう。最初に0は置けるかな？","hint2":"カードは各1枚。使ったカードを除き、次の位に置ける枚数を数えよう。"},{"title":"1 (2)","hint1":"5の倍数になる一の位を先に決めよう。","hint2":"一の位が0のときと、0以外のときに分けよう。百の位に使える数字の数が違うよ。"},{"title":"1 (3)","hint1":"4の倍数かどうかは、下2けたで決まるよ。","hint2":"使えるカードで下2けたを作り、それぞれに残った0以外の百の位をつけよう。"}],"基本問題2":[{"title":"2 (1)","hint1":"各位の和が9の倍数になる組を探そう。","hint2":"1〜6を3つ使った和の範囲を考え、小さい順に組を書こう。各組の並べ方は、同じ目の数によって変わるよ。"},{"title":"2 (2)","hint1":"十の位と一の位を先に決めよう。","hint2":"1〜6だけで作れる4の倍数の下2けたを並べよう。さいころなので、百の位に同じ目を使ってもよいね。"}],"基礎演習1":[{"title":"1 (1)","hint1":"百の位だけは0を選べないよ。","hint2":"各数字は3枚ずつあるので、同じ数字を続けて使ってもよいね。各位の選び方を組み合わせよう。"},{"title":"1 (2)","hint1":"下2けたが4の倍数か00になる場合を調べよう。","hint2":"使える数字だけで下2けたの表を作り、0以外の百の位をつけよう。"},{"title":"1 (3)","hint1":"3つの数字の和が3の倍数になる組を先に決めよう。","hint2":"同じ数字の入れ替えを重ねて数えず、百の位が0になる並びを除こう。"}],"練習問題1":[{"title":"1 (1)","hint1":"下2けたが4の倍数になる場合を先に調べよう。","hint2":"カードは各1枚。下2けたで使った数字と0を、百の位の候補から除こう。"},{"title":"1 (2)","hint1":"和が3の倍数になる3枚の組を選ぼう。","hint2":"各組を並べるとき、0を含むかどうかで分けると数えやすいよ。"},{"title":"1 (3)","hint1":"6の倍数には、3の倍数であり偶数でもあるという条件があるよ。","hint2":"(2)で調べた組について、一の位を偶数に固定し、残り2枚を並べよう。百の位の0は除くよ。"}],"練習問題2":[{"title":"2 (1)","hint1":"積が奇数になるのは、どんな目が3回出たとき？","hint2":"全体から、3回とも奇数になる場合を引こう。"},{"title":"2 (2)","hint1":"この小問では、出た目の組み合わせを数えるよ。出た目を小さい順の組に整理しよう。","hint2":"和が4の倍数になる組を、最小の目から順に調べよう。目を並べ替えただけのものは、この小問では同じ組として数えるよ。"},{"title":"2 (3)","hint1":"今度は1回目・2回目・3回目を区別するよ。","hint2":"(2)の組ごとに、すべて違う目・2つ同じ目・すべて同じ目に分け、並べ方を数えよう。"}],"標準演習1":[{"title":"1 (1)","hint1":"4の倍数になる下2けたを、使える数字で作ろう。","hint2":"00も候補だよ。各数字は3枚あるので、百の位には0以外のどの数字を使えるか考えよう。"},{"title":"1 (2)","hint1":"3つの数字の和が9の倍数になる組を調べよう。","hint2":"和の最小・最大を確認し、小さい順の組を作ってから並べよう。同じ数字の重複と先頭の0に注意しよう。"},{"title":"1 (3)","hint1":"各位の和が3の倍数で、一の位が偶数になる必要があるよ。","hint2":"和の条件を満たす組を作り、偶数を一の位に置こう。同じ数字を入れ替えただけのものは数えないよ。"}],"標準演習2":[{"title":"2","hint1":"「14以下」より、反対の「14より大きい」を数えるほうが短く済みそうだね。","hint2":"和が15以上の組を探し、色の違いを区別して並べ方を数えよう。全体から引こう。"}],"例題2・類題2":[{"title":"例題2 （1）全部の並べ方","hint1":"白石を置く場所が決まると、黒石の場所も決まるね。","hint2":"7か所から白石の場所を3か所選ぼう。場所を選ぶ順番を変えても同じ並びだから、重ねて数えないようにしよう。"},{"title":"例題2 （2）両はしが黒石","hint1":"先に両はしへ黒石を置いてしまおう。残りだけを考えればよいね。","hint2":"真ん中に残る場所と、残っている黒石・白石の数を書こう。その場所から、一方の色を置く場所を選ぼう。"},{"title":"例題2 （3）白石がとなり合わない","hint1":"黒石を先に並べ、白石を入れられる「すき間」を探そう。","hint2":"黒石と黒石の間だけでなく、両はしにも入れられるよ。白石がとなり合わないように、違うすき間を3か所選び、1個ずつ置こう。"},{"title":"類題2 （1）全部の並べ方","hint1":"数の少ない黒石の置き場所を決めると考えてみよう。","hint2":"8か所から黒石の場所を3か所選ぶと、白石の場所も決まるね。黒石どうしを入れかえても同じ並びだよ。"},{"title":"類題2 （2）両はしが黒石","hint1":"両はしに黒石を置いた後、まだ置いていない黒石は何個かな？","hint2":"残った黒石を、真ん中のどこに置けるか調べよう。黒石の位置が決まれば、残りはすべて白石だね。"},{"title":"類題2 （3）黒石がとなり合わない","hint1":"今度は黒石どうしを離したいね。先に並べるのは、どちらの色かな？","hint2":"白石を並べ、その間と両はしに印をつけよう。そこから黒石を入れる場所を3か所選び、1個ずつ置けばよいね。"}],"基本問題3":[{"title":"3 (1)","hint1":"白石を置く4か所を決めると、黒石の場所も決まるよ。","hint2":"8か所から4か所を選ぼう。選ぶ順番だけが違うものは同じ並びだよ。"},{"title":"3 (2)","hint1":"両はしの黒石を先に固定しよう。","hint2":"残る場所と石の個数を書き、真ん中で白石の場所を選ぼう。"},{"title":"3 (3)","hint1":"左はしの色を決めると、その次の色はどうなる？","hint2":"最初の色を変えて、それぞれ最後まで交互に置けるか確かめよう。"},{"title":"3 (4)","hint1":"「白石が少しでもとなり合う」の反対を考えよう。","hint2":"黒石を先に置き、すき間に白石を1個ずつ置く場合を数えよう。それを(1)の全体から引こう。"}],"基礎演習2":[{"title":"2 (1)","hint1":"黒石を置く場所を決めよう。","hint2":"6か所から3か所を選ぶ方法を数えよう。同じ色の石は区別しないよ。"},{"title":"2 (2)","hint1":"両はしの白石を固定しよう。","hint2":"真ん中の残りの場所に、残った白石をどこへ置けるか考えよう。"},{"title":"2 (3)","hint1":"「黒石がとなり合わない」場合を先に数えよう。","hint2":"白石の間と両はしのすき間から、黒石を入れる場所を選ぼう。全体からそれを引こう。"}],"練習問題3":[{"title":"3 (1)","hint1":"両はしに緑を固定すると、真ん中には何が残る？","hint2":"真ん中で赤の位置を選べば、青の位置も決まるよ。"},{"title":"3 (2)","hint1":"まず緑2個の場所を決め、次に赤の場所を決めよう。","hint2":"それぞれの場所の選び方を組み合わせよう。同じ色の入れ替えは数えないよ。"},{"title":"3 (3)","hint1":"赤と青を先に並べよう。","hint2":"その並べ方ごとに、間と両はしから緑を入れる異なるすき間を選ぼう。"}],"標準演習3":[{"title":"3","hint1":"○の個数によって場合を分けよう。","hint2":"○が×より多い組だけを並べ、同じ記号が3つ以上続くものを除こう。○が多すぎる場合に条件を満たせるかも調べよう。"}],"例題3・類題3":[{"title":"例題3 （1）270円を払う方法","hint1":"まず100円硬貨の枚数で場合を分けよう。使わない場合もあるよ。","hint2":"100円硬貨の枚数を決めたら、残った金額の範囲で50円硬貨の枚数を変えよう。残りを10円硬貨で払えるか確かめ、表にすると数え落としを防げるよ。"},{"title":"例題3 （2）10円3枚・50円1枚・100円2枚までで作れる金額","hint1":"それぞれの硬貨について「0枚から何枚まで使えるか」を書こう。","hint2":"3種類の枚数の選び方を組み合わせよう。違う選び方で同じ金額にならないか、少額の硬貨だけで次の硬貨の金額に届くかを確かめてね。全部0枚の選び方は最後に除こう。"},{"title":"例題3 （3）10円2枚・50円3枚・100円1枚までで作れる金額","hint1":"50円硬貨2枚と100円硬貨1枚は同じ金額。同じ金額を別々に数えない工夫が必要だね。","hint2":"まず50円硬貨と100円硬貨で作れる金額を、0円も入れて小さい順に書き、重なりをなくそう。それぞれに10円硬貨で作れる金額を足してみよう。支払いにならない0円は除こう。"},{"title":"類題3 （1）90円を払う方法","hint1":"先に50円硬貨を使うかどうかで分けよう。","hint2":"それぞれの場合に、10円硬貨を0枚から順に増やして表にしよう。残りを5円硬貨で払えるか確かめれば、1行ずつ数えられるよ。"},{"title":"類題3 （2）5円1枚・10円と50円を各3枚までで作れる金額","hint1":"硬貨ごとに、使える枚数の選び方を考えよう。「使わない」も含めるよ。","hint2":"少額の硬貨を全部使っても、次の大きな硬貨1枚の金額に届くかな？ 違う選び方で同じ金額にならないことを確かめてから、枚数の選び方を組み合わせよう。全部0枚は除こう。"},{"title":"類題3 （3）5円3枚・10円と50円を各2枚までで作れる金額","hint1":"5円硬貨2枚と10円硬貨1枚は同じ金額。枚数の選び方をそのまま数えると重なりそうだね。","hint2":"まず5円硬貨と10円硬貨だけで作れる金額を、0円も含めて重複なく並べよう。その一覧に、50円硬貨を使う分を足そう。金額の重なりがないか確かめ、最後に0円を除こう。"}],"基本問題4":[{"title":"4 (1)","hint1":"100円硬貨の枚数から決め、残金を表にしよう。","hint2":"次に50円硬貨の枚数を変え、残りを10円硬貨で払えるか確かめよう。各硬貨の上限も確認しよう。"},{"title":"4 (2)","hint1":"100円、50円、10円の順に枚数を決めよう。","hint2":"残金が10円硬貨だけで払える範囲か注意しよう。10円硬貨は無制限ではなく25枚までだよ。"}],"基本問題5":[{"title":"5 (1)","hint1":"各種類について、0個から最大何個まで選べるか書こう。","hint2":"軽いおもりを全部使っても、次の種類1個の重さに届くかな？　同じ重さが重ならないことを確かめ、全く使わない場合を除こう。"},{"title":"5 (2)","hint1":"1gを5個と、5gを1個は同じ重さになるよ。","hint2":"まず1g・5gだけで作れる重さを重複なく並べ、25gを使う場合を加えよう。0gは除こう。"}],"基礎演習3":[{"title":"3 (1)","hint1":"各硬貨の枚数を、0枚も含めて選ぼう。","hint2":"小さい硬貨だけで次の硬貨と同じ金額を作れるか確かめよう。重複がなければ選び方を組み合わせ、0円を除こう。"},{"title":"3 (2)","hint1":"5円玉2枚と10円玉1枚の重なりに注意しよう。","hint2":"先に5円玉・10円玉で作れる金額を重複なく並べ、それぞれに1円玉で作れる金額を足そう。0円は除こう。"}],"練習問題4":[{"title":"4 (1)","hint1":"枚数を多くするには、小さい硬貨をできるだけ使おう。","hint2":"10円・50円を使った残りを大きい硬貨で払えるか確かめよう。使える枚数の上限も忘れずに。"},{"title":"4 (2)","hint1":"500円の枚数で場合を分けよう。","hint2":"残金を100円と50円で払う方法を、上限を守って表にしよう。"},{"title":"4 (3)","hint1":"10円硬貨の合計は、ほかの硬貨で払えない端数を残さない金額にしよう。","hint2":"使う10円硬貨の枚数で分け、残金を大きい硬貨から順に払う表を作ろう。0枚の場合は(2)が使えるよ。"}],"練習問題5":[{"title":"5 (1)","hint1":"1円・5円のグループと、50円・100円のグループに分けよう。","hint2":"各グループで作れる金額を重複なく並べてから組み合わせよう。同じ金額になる選び方と、0円を除こう。"},{"title":"5 (2)","hint1":"まず5円と10円で作れる金額を、重複なく並べよう。","hint2":"そこに1円で作れる端数を足し、最後に50円を加える場合を調べよう。抜ける金額や重なる金額がないか確かめよう。"}],"標準演習4":[{"title":"4 (1)","hint1":"小さい硬貨から順に、作れる金額の範囲を調べよう。","hint2":"5円・10円だけで5円きざみにどこまで作れる？　50円を加えた範囲と重なる端の金額を1回だけ数え、0円を除こう。"},{"title":"4 (2)","hint1":"5円・10円だけで作れる金額を、5円きざみで整理しよう。","hint2":"50円が0枚・1枚・2枚の範囲を書き、重なる部分をまとめよう。数えているのは硬貨の選び方ではなく金額だよ。"}],"例題4・類題4":[{"title":"例題4 （1）平行四辺形の個数","hint1":"平行四辺形を1つ囲むには、2方向の直線をそれぞれ何本選べばよいかな？","hint2":"ア〜ウからの選び方と、①〜④からの選び方を別々に数えよう。片方の選び方1つに、もう片方のどの選び方も組み合わせられるね。"},{"title":"例題4 （2）9個の点から作る三角形","hint1":"まず3点の選び方を全部数え、三角形にならないものを引く方法を考えよう。","hint2":"3点が一直線に並ぶと三角形にならないよ。三角形ABCの各辺について、その辺の上だけで3点を選べるか調べよう。選べるのは①〜⑨で、A・B・Cは含めないよ。"},{"title":"類題4 （1）平行四辺形の個数","hint1":"小さい区画を数えるのではなく、平行四辺形を囲む線の選び方を考えよう。","hint2":"2つの方向ごとに、外側の辺も含めて直線が何本あるか数えよう。それぞれから2本ずつ選ぶ方法を組み合わせれば、大きい平行四辺形も数えられるよ。"},{"title":"類題4 （2）8個の点から作る三角形","hint1":"①〜⑧から3点を選ぶ方法の中に、三角形にならないものがまじっているよ。","hint2":"同じ辺の上だけで3点を選べるのはどの辺かな？ 全体の選び方から、そのような選び方を除こう。A・B・Cは選ぶ点に含めないよ。"}],"基本問題6":[{"title":"6","hint1":"図の中で四角形を囲む、縦方向と横方向の線を考えよう。","hint2":"縦方向から2本、横方向から2本を選ぶ方法を組み合わせよう。平行でなくても、図の範囲で四角形を囲めるね。"}],"基本問題7":[{"title":"7 (1)","hint1":"7点から3点を選ぶとき、三角形にならない選び方はどれ？","hint2":"3点とも同じ直線上にある場合を、全体から引こう。"},{"title":"7 (2)","hint1":"四角形には、片方の直線だけから3点選んでもよいかな？","hint2":"それぞれの直線から2点ずつ選ぶ方法を組み合わせよう。"}],"基礎演習4":[{"title":"4 (1)","hint1":"直線ℓの点を1つ決めたら、mのどの点と結べる？","hint2":"ℓの点の選び方とmの点の選び方を組み合わせよう。"},{"title":"4 (2)","hint1":"8点から3点を選ぶ中には、一直線に並ぶものがあるよ。","hint2":"ℓだけで3点、mだけで3点を選ぶ場合を全体から除こう。"}],"練習問題6":[{"title":"6 (1)","hint1":"三角形の頂点はA、底辺はBC上にあるよ。","hint2":"Aから出る線を外側の辺も含めて数え、2本選ぶ方法を考えよう。"},{"title":"6 (2)","hint1":"底辺をどの水平な線に置くか、先に決めよう。","hint2":"どの底辺でも、Aから出る2本の線を選べるね。底辺の選び方と組み合わせよう。"}],"チャレンジ2":[{"title":"2 (1)","hint1":"一辺が小さい辺の何本分かで分けよう。","hint2":"大きさごとに、上向き・下向きの置ける場所を段ごとに数えよう。外側にはみ出すものは除こう。"},{"title":"2 (2) 左の向き","hint1":"図全体と同じ向きのひし形を、一辺の長さごとに探そう。","hint2":"一辺の長さを決めてから、2方向に動かせる位置の数を組み合わせよう。"},{"title":"2 (2) 右の向き","hint1":"一辺の長さを決め、この向きのひし形を1つ描こう。","hint2":"段ごとに置ける位置を数えよう。外側の斜めの境界で入らない場所に注意しよう。"},{"title":"2 (3)","hint1":"ひし形の辺は、図にある3方向のうち2方向を使うよ。","hint2":"(2)で数えた2つの向きに加え、残る向きも数えよう。対称で同じ個数になるか、図で確かめて合計しよう。"}],"例題5・類題5":[{"title":"例題5 （1）正方形の種類","hint1":"辺がたて・横に向く正方形だけで終わっていないかな？ 傾いた正方形も描いてみよう。","hint2":"傾いた正方形を、たて・横の辺をもつ四角い枠で囲んでみよう。小さい枠から順に調べると探しやすいよ。回したり裏返したりして重なる正方形は、同じ種類にまとめよう。"},{"title":"例題5 （2）正方形の個数","hint1":"（1）で見つけた種類ごとに、図の中のどこへ置けるか数えよう。","hint2":"まっすぐな正方形は、横へ動かせる位置と、たてへ動かせる位置を調べよう。傾いたものは外側の枠を動かして数え、傾きが反対の置き方も確認しよう。同じ4点の組は1回だけ数えるよ。"},{"title":"類題5 （1）正方形の種類","hint1":"点が増えたから、新しい種類が必ず増えるとは限らないよ。たてと横、それぞれ何区間あるか見よう。","hint2":"まっすぐな正方形と傾いた正方形を、小さいものから描こう。傾いたものは外側の四角い枠がこの図に入るか確認してね。位置や向きが違うだけなら同じ種類だよ。"},{"title":"類題5 （2）正方形の個数","hint1":"種類が同じでも、置ける場所が増えることがあるね。種類ごとに数え直そう。","hint2":"まっすぐなものは、たて・横それぞれの位置の数を組み合わせよう。傾いたものは、囲む枠の位置と、枠の中での傾きの向きを調べよう。同じ4点を重ねて数えないようにね。"}],"基本問題8":[{"title":"8 (1)","hint1":"一辺の長さごとに分けよう。","hint2":"その大きさの正方形を、横に何か所、縦に何か所置けるか数えてかけよう。"},{"title":"8 (2)","hint1":"まず正方形を含め、長方形を囲む線の選び方を数えよう。","hint2":"縦と横の線から2本ずつ選ぶ方法を組み合わせ、(1)の正方形を引こう。"}],"基本問題9":[{"title":"9 (1)①","hint1":"アの左上の頂点を、どこに置けるか考えよう。","hint2":"右と下に辺を伸ばせる場所を、横・縦に分けて数えよう。"},{"title":"9 (1)②","hint1":"イを、縦横の辺をもつ正方形の枠で囲もう。","hint2":"その枠を図の中に置ける場所を数えよう。イそのものも含めるよ。"},{"title":"9 (2)","hint1":"まっすぐな正方形と、傾いた正方形に分けて描こう。","hint2":"傾いたものは外側の枠を小さい順に調べよう。回転・裏返しで重なる形は1種類にし、アとイを除こう。"},{"title":"9 (3)","hint1":"種類ごとに、置ける位置と向きを数えよう。","hint2":"外側の枠を動かして数えると整理できるよ。アとイも戻して合計しよう。"}],"基礎演習5":[{"title":"5 (1)","hint1":"アの形を、横と縦に動かしてみよう。","hint2":"右と下に一辺分の長さが取れる頂点の位置を数えよう。"},{"title":"5 (2)","hint1":"イを囲む縦横の正方形の枠をかこう。","hint2":"枠を横に何か所、縦に何か所置けるか数えよう。"},{"title":"5 (3)","hint1":"まっすぐなものも傾いたものも、小さい順に描こう。","hint2":"図の横幅と縦幅に入るか確かめ、回転・裏返しで重なるものを1種類にまとめよう。"},{"title":"5 (4)","hint1":"各種類を置ける場所の数を求めよう。","hint2":"傾いたものは、枠の位置に加え、傾きが反対の置き方も調べよう。同じ4点は1回だけ数えるよ。"}],"練習問題7":[{"title":"7 (1)","hint1":"アは、直角をはさむ辺が縦横の方向だね。","hint2":"囲む長方形の位置と、その中で直角を置く隅を調べよう。縦長・横長も分けて数えよう。"},{"title":"7 (2)","hint1":"イの直角をはさむ2辺を、マスの縦横の移動で表そう。","hint2":"直角に向きを変えるには、横と縦の移動を入れ替え、一方の向きを逆にするよ。図の中に収まる位置・向きを調べよう。"},{"title":"7 (3)","hint1":"直角をはさむ辺が縦横のものと、斜めのものに分けよう。","hint2":"縦横なら2辺の長さの組、斜めならマスの移動の組で整理しよう。回転・裏返しで重なるものは1種類だよ。"}],"標準演習5":[{"title":"5 (1)","hint1":"直角をはさむ等しい2辺が縦横のものと、斜めのものに分けよう。","hint2":"斜めの辺は「横に何区間・縦に何区間」で表し、90度回した同じ長さの辺を作ろう。図に収まる形を、合同なら1種類にまとめよう。"},{"title":"5 (2)","hint1":"2辺が縦横のものでは、長さの組を調べよう。斜めのものも忘れずに。","hint2":"斜めの1辺に対し、横と縦の進み方を入れ替え、一方の向きを逆にして直角な方向を作ろう。各方向に伸ばせる長さを調べ、回転・裏返しで重なる形をまとめよう。"}],"例題6・類題6":[{"title":"例題6 （1）三角形の個数","hint1":"三角形1つは、異なる頂点3つを決めれば作れるね。","hint2":"8個の頂点から3つを選ぼう。選ぶ順番が違っても同じ三角形だから、その重なりを除く必要があるよ。"},{"title":"例題6 （2）合同なものをまとめた種類","hint1":"選んだ3頂点で、正八角形の周りが3つに分かれるね。それぞれの部分に「外周の辺が何本あるか」を書いてみよう。","hint2":"3つの間隔はどれも1以上で、合計は8。小さい順に並べた3つの数の組を、もれなく探そう。数字の順番が違うだけの組は、回したり裏返したりすると重なるので同じ種類だよ。数えているのは三角形の辺の長さではなく、外周の間隔だよ。"},{"title":"類題6 （1）三角形の個数","hint1":"円周上の異なる3点を選ぶと、三角形が1つできるよ。","hint2":"A〜Fから3点を選ぶ方法を考えよう。ABCとBCAのように、選ぶ順番だけが違うものを重ねて数えないようにしよう。"},{"title":"類題6 （2）合同なものをまとめた種類","hint1":"選んだ3点の間で、円周の小さな区間をそれぞれいくつ通るか数えよう。","hint2":"3つの間隔はすべて1以上で、合計は6。小さい順に3つの数を書いて組を探そう。同じ組なら、回したり裏返したりすると重なるよ。見つけた組を図に描いて確かめよう。"}],"基本問題10":[{"title":"10 (1)","hint1":"2頂点を選んで結ぶと、辺か対角線になるよ。","hint2":"2頂点の選び方から、正九角形の辺になるものを引こう。"},{"title":"10 (2)","hint1":"三角形は異なる3頂点で決まるよ。","hint2":"3頂点を選ぶ順番が違うだけのものを、重ねて数えないようにしよう。"},{"title":"10 (3)","hint1":"選んだ3頂点の間の、外周の区間数を調べよう。","hint2":"3つの正の整数で合計9になる組を小さい順に並べよう。同じ組は回転・裏返しで重なるよ。"}],"基礎演習6":[{"title":"6 (1)","hint1":"正七角形の3頂点を選べば、三角形が決まるね。","hint2":"選ぶ順番を変えただけのものは同じ三角形として数えよう。"},{"title":"6 (2)","hint1":"外周を3つに区切ったときの区間数で整理しよう。","hint2":"3つとも1以上、合計7となる組を小さい順に並べ、図にして確かめよう。"}],"練習問題8":[{"title":"8 (1)","hint1":"頂角になる点を1つ決め、左右に同じ区間数だけ離れた2点を選ぼう。","hint2":"等しい2辺がどの長さになるかを小さい順に調べよう。別の頂点から作っても、重なる形は同じ種類だよ。"},{"title":"8 (2)","hint1":"1つの頂点を頂角としたとき、何個作れるかな？","hint2":"頂角をほかの点へ移して数えよう。同じ三角形を別の頂角から数えていないか確認しよう。"},{"title":"8 (3)","hint1":"先に直径になる2点を選ぼう。","hint2":"そのあと、残りの点から3つ目を選べるよ。1つの直角三角形に直径の辺がいくつあるかを確認しよう。"}],"標準演習6":[{"title":"6 (1)","hint1":"頂角を1つ決め、円周を左右に同じ区間数だけ進もう。","hint2":"作れた形のうち、3辺とも等しくなるものを除こう。頂角を移しただけなら同じ種類だよ。"},{"title":"6 (2)","hint1":"(1)の各種類について、頂角を置ける場所を数えよう。","hint2":"正三角形は除いているので、頂角を変えると別の三角形になるね。"}],"標準演習7":[{"title":"7 (1)","hint1":"立方体の頂点を結ぶ線を、辺・面の対角線・立体の対角線に分けよう。","hint2":"三角形の3辺がどの種類の組になるか、1頂点を固定して図にしよう。実際に作れる組だけを数えよう。"},{"title":"7 (2)","hint1":"3辺が同じ長さになる頂点の組を探そう。","hint2":"1頂点を決め、同じ距離にある候補から残り2点を選ぼう。全頂点について数えるなら、同じ三角形を何回数えたか確かめよう。"},{"title":"7 (3)","hint1":"3種類の長さを1本ずつ使う三角形を考えよう。","hint2":"立体の対角線を先に選び、残り1頂点をどこに置けるか調べよう。1つの三角形にその対角線が何本あるかも確認しよう。"}],"チャレンジ1":[{"title":"1 (1)","hint1":"円周上の4点を選ぶと、四角形が1つ決まるよ。","hint2":"選ぶ順番が違っても同じ4点。今回は位置が違えば別の四角形として数えよう。"},{"title":"1 (2)","hint1":"対称の軸を1本決め、その軸の左右に対応する点の組を作ろう。","hint2":"その組から2組選ぶと、平行な2辺をもつ四角形ができるね。軸の位置を変えて数えるとき、同じ台形を重ねて数えないか確認しよう。"},{"title":"1 (3)","hint1":"4頂点の間の外周の区間数を、順番つきで記録しよう。","hint2":"合計11の4つの正の整数で表せるよ。始める場所をずらしたものと逆順は同じ種類。ただし、順を自由に並べ替えると別の形になる場合があるよ。"}]},"6u-4":{"例題1・類題1":[{"title":"例題1 (1)","hint1":"1から始まるまとまりごとに、区切り線を入れよう。","hint2":"各組の個数を順に足し、50番目が何組に入るか探そう。その前の組までの個数を引くと、組の中の位置がわかるよ。"},{"title":"例題1 (2)","hint1":"12が初めて入るのは何組かな？","hint2":"その組のどの位置に12があるかを考え、そこまでの個数を足そう。"},{"title":"類題1 (1)","hint1":"同じ数が続く部分を1組にしよう。","hint2":"各組の個数を足し、60番目を含む組を見つけよう。その組に並ぶ数字を答えるよ。"},{"title":"類題1 (2)","hint1":"18の組の、最初の位置を探す問題だね。","hint2":"17の組までに並ぶ個数を求め、その次の位置に進もう。"}],"基本問題1":[{"title":"1 (1)","hint1":"第20組の最初の数を、組番号から考えよう。","hint2":"最初から4番目までは、数を何回増やす？　最初の数に足そう。"},{"title":"1 (2)","hint1":"第15組の最初・最後・個数を調べよう。","hint2":"一定ずつ増える数の和なので、両はしの数を組にして求めよう。"}],"基本問題2":[{"title":"2 (1)","hint1":"分母が同じ部分を1組にしよう。","hint2":"組の個数を足して30番目を含む組を探そう。組番号が分母、組の中の位置が分子に対応するね。"},{"title":"2 (2)","hint1":"分母10の組の最初の数だね。","hint2":"その前の分母の組までの個数を足し、1つ先へ進もう。"}],"基礎演習1":[{"title":"1 (1)","hint1":"4個ずつ区切って、各組の最初の数を調べよう。","hint2":"30番目が何組の何番目かを割り算で出し、その組では数が減ることに注意しよう。"},{"title":"1 (2)","hint1":"各組の最大の数は、最初にあるね。","hint2":"25が初めて組の最初に来るのは何組か考え、その前の組の個数を足そう。"}],"基礎演習2":[{"title":"2 (1)","hint1":"8が並ぶ組より前には、どんな組がある？","hint2":"1から7の組までの個数を足し、次の位置を求めよう。"},{"title":"2 (2)","hint1":"各組の個数を順に足そう。","hint2":"88番目が入る組を見つけ、その組で繰り返されている数を答えよう。"},{"title":"2 (3)","hint1":"組ごとの「個数」と「数の和」を別の列に書こう。","hint2":"合計240の手前まで組ごとに足し、残りを次の組の数で割ろう。最後に個数へ戻すよ。"}],"練習問題1":[{"title":"1 (1)","hint1":"分母が同じ数を1組にしよう。組の中の分子は減っていくよ。","hint2":"分母7の組より前の個数を足し、その組の中で6/7が何番目かを加えよう。"},{"title":"1 (2)","hint1":"各組の個数を足して、100番目が入る組を探そう。","hint2":"前の組までの個数を引き、その組の何番目かを求めよう。分子は大きいほうから並ぶことに注意しよう。"},{"title":"1 (3)","hint1":"完成した組の和と、最後の途中の組の和に分けよう。","hint2":"同じ分母の組は分子をまとめて足せるね。(2)でわかった最後の組の位置までを加えよう。"}],"標準演習1":[{"title":"1 (1)","hint1":"最初の1を別にし、その後を「2から増え、1まで戻る山」に区切ろう。","hint2":"各山の個数を調べて40番目が入る山を探そう。その中で増える側か減る側かを確認しよう。"},{"title":"1 (2)","hint1":"13が初めて出るのは、頂上が13の山だね。","hint2":"その前の山までの個数と、その山の頂上までの個数を足そう。山の間の1を二重に数えないようにしよう。"}],"標準演習2":[{"title":"2 (1)","hint1":"分母が同じ部分を組にしよう。この列では分子が分母と同じになる数はないよ。","hint2":"各組の個数を足して50番目の組を決め、組の中の位置から分子を求めよう。"},{"title":"2 (2)","hint1":"各分母について、分子がどこまでなら1/2以下か調べよう。","hint2":"分母が偶数か奇数かで個数を分け、分母20まで足そう。同じ値でも別の位置に並ぶ分数はそれぞれ数えるよ。"},{"title":"2 (3)","hint1":"同じ分母の組で、最初と最後、2番目と最後から2番目を組にしよう。","hint2":"両はしの分数の和がそろうね。各組の平均と個数から和を出し、全部の組を足そう。"}],"例題2・類題2":[{"title":"例題2 (1)","hint1":"1段目の数を、列番号と比べてみよう。","hint2":"列番号を2回かけた数になっているか、表の初めで確かめよう。"},{"title":"例題2 (2)","hint1":"まず1段目の7列目を基準にしよう。","hint2":"同じ列を下へ進むと、数はどう変わる？　1段目から5段目への移動回数を数えよう。"},{"title":"例題2 (3)","hint1":"85の前後にある平方数を探そう。","hint2":"小さいほうの平方数の次から、新しい段の左端へ進むよ。数の差を使い、横に進む途中か、曲がった後か確かめよう。"},{"title":"類題2 (1)","hint1":"1段目の9列目を先に求めよう。","hint2":"そこから同じ列の3段目まで、何回進むか考えよう。"},{"title":"類題2 (2)","hint1":"55をはさむ平方数から、どの大きさの組かを決めよう。","hint2":"組の始めから横に進み、角を曲がって縦に進む順を小さな図にかこう。"}],"基本問題3":[{"title":"3 (1)","hint1":"1列目にある数のきまりを調べよう。","hint2":"5段目の1列目を基準に、右へ1列動くごとに数がどう変わるか考えよう。"},{"title":"3 (2)","hint1":"52の前後の平方数を探そう。","hint2":"この表は例題と進む向きが違うよ。新しい列を下へ進み、そのあと左へ曲がる順を確認しよう。"}],"基本問題4":[{"title":"4 (1)","hint1":"この表は段を下から数えるよ。まず6段目の左端を求めよう。","hint2":"1つ前の大きさの正方形が終わった次の数が、新しい段の最初になる。そこから5列目まで進もう。"},{"title":"4 (2)","hint1":"115をはさむ平方数から、何番目の組に入るか調べよう。","hint2":"その組の横の部分か縦の部分かを確かめ、表の段が下から数えられていることに注意しよう。"}],"基礎演習3":[{"title":"3 (1)","hint1":"1列目の数を、段番号と比べよう。","hint2":"同じ数を2回かけた数になっているか、最初の数で確かめよう。"},{"title":"3 (2)","hint1":"7列目の最初の数は、ひとつ前の正方形が終わった次の数だよ。","hint2":"そこから5段目まで下がると、何回1ずつ増えるかな？"},{"title":"3 (3)","hint1":"71をはさむ平方数を探そう。","hint2":"新しい列を下がる部分か、最下段を左へ進む部分かを、組の最初からの個数で調べよう。"}],"練習問題2":[{"title":"2 (1)","hint1":"正方形の外側に増えるL字の組を見よう。奇数番目と偶数番目で向きが違うよ。","hint2":"15列目の組の最初がどこかを、前の平方数から調べよう。そこから8段目まで進もう。"},{"title":"2 (2)","hint1":"300をはさむ平方数で、何番目のL字の組かを決めよう。","hint2":"その組が奇数番目か偶数番目かで向きを確かめ、組の始めからの歩数で位置を出そう。"}],"練習問題3":[{"title":"3 (1)","hint1":"斜めに並ぶ数を1組にし、各組の個数を調べよう。","hint2":"同じ斜めの組では「段番号＋列番号」が一定だね。5段6列が何組かを求め、前の組までの個数と組内の位置を使おう。"},{"title":"3 (2)","hint1":"斜めの組までに並ぶ個数を、順に足そう。","hint2":"100番目が入る組と、その中の何番目かを調べよう。各組は右上から左下へ進むよ。"}],"標準演習3":[{"title":"3 (1)","hint1":"L字の組が偶数番目のとき、どの隅で終わるか見よう。","hint2":"正方形全体に入る個数と、1段目の偶数列の数の関係を考えよう。"},{"title":"3 (2)","hint1":"1段目の10列目を基準にしよう。","hint2":"この列を下へ進むと数がどう変わる？　6段目までの移動回数を使おう。"},{"title":"3 (3)","hint1":"111をはさむ平方数から、L字の組を決めよう。","hint2":"奇数・偶数で向きが変わることを確認し、近い端の数から位置を求めよう。"}],"チャレンジ1":[{"title":"1 (1)","hint1":"1を中心に、ひと回りずつ正方形の枠をかこう。","hint2":"各枠の右下の数と、枠の一辺のマス数を比べよう。左上の目標まで、角を通って何マス戻るか考えよう。"},{"title":"1 (2)","hint1":"左右・上下のうち大きい移動量から、何番目の枠にいるか決めよう。","hint2":"その枠の右下の数を基準に、下辺を何マス戻ると目標になるか数えよう。"},{"title":"1 (3)","hint1":"240をはさむ、奇数を2回かけた数を探そう。","hint2":"その枠の右下から、数の差だけ逆向きにたどろう。角をいくつ通るかを調べ、中心からの左右・上下の位置に直そう。"}],"例題3・類題3":[{"title":"例題3 (1)","hint1":"「持っているシール・もらうお菓子・余るシール」の表を作ろう。","hint2":"交換したお菓子のシールも、余りに足して次の交換に使えるよ。交換できなくなるまで続け、買った個数も合わせよう。"},{"title":"例題3 (2)","hint1":"交換1回で、お菓子は増え、手持ちのシールは実際に何枚減る？","hint2":"最初の交換と2回目以降を分けて、買う数の候補を出そう。その数で150個に届き、1個少なく買うと届かないか確かめよう。"},{"title":"類題3 (1)","hint1":"交換で増えたお菓子にもシールがつくよ。","hint2":"毎回、もらった分のシールと余りを合わせ、もう交換できないところまで表にしよう。"},{"title":"類題3 (2)","hint1":"全部100個と、買った個数は違うね。交換でもらう分を考えよう。","hint2":"交換1回で実際に減るシールの枚数を使い、買う数の候補を出そう。1個少ない場合も試して最小を確かめよう。"}],"基本問題5":[{"title":"5 (1)","hint1":"空きビンを6本ずつ交換し、余りを記録しよう。","hint2":"もらった牛乳を飲むと、また空きビンができるよ。余りと合わせて、交換を続けよう。"},{"title":"5 (2)","hint1":"交換して飲むたびに、手元の空きビンは実際に何本減る？","hint2":"80本に届く購入本数の候補を出し、実際に交換して確認しよう。1本少なく買うと届かないことも確かめよう。"}],"基本問題6":[{"title":"6 (1)","hint1":"最初に1600円で買える本数を求めよう。","hint2":"買った分を飲んだ空きビンから交換を始めよう。交換したジュースを飲むと、その空きビンも次の交換に使えるよ。必要な本数がそろわなくなるまで、表で追おう。"},{"title":"6 (2)","hint1":"まず必要なお金ではなく、買う本数を考えよう。","hint2":"交換で50本に届く最小の購入本数を試し、最後に1本の値段をかけよう。"}],"基礎演習4":[{"title":"4 (1)","hint1":"36本分の空きビンから、交換を始めよう。","hint2":"交換したジュースを飲んだあとのビンと、余りを合わせ、次の交換に使おう。"},{"title":"4 (2)","hint1":"1回交換して飲むと、空きビンは差し引き何本減る？","hint2":"購入本数の候補を出し、50本以上に届くか表で確かめよう。1本少ない候補も確認しよう。"}],"練習問題4":[{"title":"4 (1)","hint1":"6000円で買える本数を出し、A店とB店を別々に計算しよう。","hint2":"A店は購入本数でおまけが決まる。B店は交換でもらった分の空きビンも次に使うよ。最後に飲める総数を比べよう。"},{"title":"4 (2)","hint1":"各店で150本に届く最小の購入本数を探そう。","hint2":"B店では交換のたびに手持ちの空きビンが何本減るかも使おう。候補と1本少ない場合を確認し、購入本数に値段をかけよう。"}],"標準演習4":[{"title":"4 (1)","hint1":"1900円で買える本数から始めよう。","hint2":"空きビン4本を交換したあと、飲んで戻る1本と余りを合わせよう。これを繰り返して総数を数えよう。"},{"title":"4 (2)","hint1":"まず90本以上に届く最小の購入本数を考えよう。","hint2":"交換1回で実際に減る空きビンの本数を使い、候補と1本少ない場合を確認しよう。最後に購入金額へ直すよ。"}],"例題4・類題4":[{"title":"例題4 (1)","hint1":"最後の一歩が1段か2段かで分けよう。","hint2":"最後が1段なら、その前は2段目。最後が2段なら、その前は1段目。それぞれまでの上がり方を数えて足そう。"},{"title":"例題4 (2)","hint1":"各段までの上がり方を表にしよう。","hint2":"最後の一歩が1段・2段の場合を分けると、直前の2つの段までの通り数を足せるね。"},{"title":"例題4 (3)","hint1":"2段上がり3回で、何段分進むかな？","hint2":"残りの1段上がりの回数を出し、全部の歩数の中で2段上がりをする位置を選ぼう。"},{"title":"類題4 (1)","hint1":"1段目・2段目から順に、通り数を表にしよう。","hint2":"各段の通り数は、1つ前と2つ前の通り数の和になるよ。"},{"title":"類題4 (2)","hint1":"2段上がり2回を除くと、1段上がりは何回必要？","hint2":"全部の歩数を求め、その中から2段上がりをする位置を選ぼう。"}],"基本問題7":[{"title":"7 (1)","hint1":"最後の一歩で、1つ前か2つ前の段から来るよ。","hint2":"各段までの通り数を、直前2つの和として10段目まで表にしよう。"},{"title":"7 (2)","hint1":"2段上がり4回で進む段数を除こう。","hint2":"残る1段上がりの回数から全部の歩数を求め、2段上がりをする位置を選ぼう。"},{"title":"7 (3)","hint1":"5段目を境に、前半と後半に分けよう。","hint2":"5段目までの上がり方1つにつき、5段目から10段目までのどの上がり方も組み合わせられるよ。"}],"基本問題8":[{"title":"8 (1)①","hint1":"右端を縦1枚で埋めると、残りの横幅はどれだけ？","hint2":"残りの長方形の並べ方は、すでに図2で調べたものだよ。"},{"title":"8 (1)②","hint1":"右端を横2枚で埋めると、残りの横幅はどれだけ？","hint2":"残りの長方形について、図2の通り数を使おう。"},{"title":"8 (1)③","hint1":"右端の置き方は、①と②のどちらかだね。","hint2":"2つの場合は重ならないので、それぞれの通り数を合わせよう。"},{"title":"8 (2)","hint1":"横幅ごとに、並べ方の数を表にしよう。","hint2":"右端が縦1枚なら幅が1小さい場合、横2枚なら幅が2小さい場合になる。2つを足して進めよう。"}],"基礎演習5":[{"title":"5 (1)ア","hint1":"最初に1を置くと、残りはいくつの合計を作ればよい？","hint2":"その合計の並べ方は、問題文にすでに示されているよ。"},{"title":"5 (1)イ","hint1":"最初に2を置いた場合の、残りの合計を考えよう。","hint2":"問題文にある、その合計の並べ方を使おう。"},{"title":"5 (1)ウ","hint1":"最初のカードは1か2のどちらかだね。","hint2":"アとイの場合を合わせよう。最初のカードが違うので、重なりはないよ。"},{"title":"5 (2)","hint1":"合計ごとの並べ方を表にしよう。","hint2":"合計が1小さい場合と2小さい場合を足し、8になるまで続けよう。"}],"練習問題5":[{"title":"5 (1)①","hint1":"1番から2番に行くまでに、途中の部屋を選ぶ必要があるかな？","hint2":"移動できるドアだけをたどり、2番に着く道を確認しよう。"},{"title":"5 (1)②","hint1":"3番へ最後に入る直前の部屋で場合を分けよう。","hint2":"1番から来る場合と2番から来る場合の通り数を足そう。"},{"title":"5 (1)③","hint1":"4番へ入る直前の部屋を確認しよう。","hint2":"それぞれの部屋までの通り数を足すと、4番までの通り数になるよ。"},{"title":"5 (2)","hint1":"各部屋に「ここまで何通り」を書き込もう。","hint2":"番号の小さい隣室から来る通り数だけを足し、10番まで進めよう。"},{"title":"5 (3)","hint1":"図2でも、番号の小さい部屋から順に通り数を書こう。","hint2":"真上からだけでなく、同じ段の隣室からも入れる場合があるよ。接している部屋と番号を両方確認しよう。"}],"練習問題6":[{"title":"6 (1)","hint1":"最後の一歩が1段・2段・3段の3つに分けよう。","hint2":"0段目は「まだ動かない」1通りとし、各段までの数を直前3つの和で求めよう。地面より下の段から来る場合はないよ。"},{"title":"6 (2)","hint1":"各段に着く通り数を表にする方法が使えるよ。","hint2":"6段目の通り数を0として、その後も直前3つを足そう。6段目を飛び越す動きは使えるね。"},{"title":"6 (3)","hint1":"4歩すべてを3段上がりとした場合から考えよう。","hint2":"合計10段になるよう、各歩を1段または2段小さくする方法を調べよう。減らし方の位置が違えば別の順番だよ。"},{"title":"6 (4)","hint1":"最後の一歩を1段と3段だけに分けよう。","hint2":"1つ前の段と3つ前の段の通り数を足す表を作ろう。2段上がりは数えないよ。"}],"標準演習5":[{"title":"5 (1)","hint1":"最後に1段・2段・3段上がる場合に分けよう。","hint2":"0段目を1通りとして、各段までの通り数を前の3つの和で表にしよう。"},{"title":"5 (2)","hint1":"(1)の表を9段目まで続けよう。","hint2":"毎回、最後の一歩の出発点がどの3段かを確かめて足そう。"},{"title":"5 (3)","hint1":"5段目までと、その先の残りの段数に分けよう。","hint2":"前半の上がり方1つに、後半のどの上がり方も組み合わせられるので、2つの通り数をかけよう。"}],"チャレンジ2":[{"title":"2 (1)","hint1":"18から、規則どおりに次の数を書いていこう。","hint2":"数の個数ではなく、矢印の本数を数えるよ。初めて1に着いたところで止めよう。"},{"title":"2 (2)","hint1":"1から逆向きに戻る樹形図をかこう。","hint2":"前の数の候補は2倍した数と、条件が合うときの1小さい数。1小さい数から本当に「奇数なら1を足す」で来られるか確認し、途中で1に戻る枝は除こう。"},{"title":"2 (3)","hint1":"操作回数ごとに「偶数の個数・奇数の個数」の表を作ろう。","hint2":"逆にたどると、どの数からも2倍の偶数が作れ、偶数からは1小さい奇数も作れるよ。10回の欄を出発点に、15回まで2列を更新しよう。"}],"例題5・類題5":[{"title":"例題5 (1)","hint1":"ほかの1人に残りの票が全部入っても勝てる票数を考えよう。","hint2":"全票を2人で分けて同票になる境目を超えよう。同票では「必ず」とは言えないよ。"},{"title":"例題5 (2)","hint1":"3人当選なら、自分を含む何人が同票だと落選の可能性がある？","hint2":"その人数で全票をできるだけ均等に分けた境目より、多い票を取る必要があるよ。"},{"title":"例題5 (3)","hint1":"残りの票を求め、A以外で票の多い3人を競争相手にしよう。","hint2":"Aに追加票を入れたあと、その3人全員をAと同票以上にするには、あと何票必要？　それが残票では足りなくなる最小の追加票を探そう。"},{"title":"類題5 (1)","hint1":"残りの票が1人に集中しても、自分に追いつけないようにしよう。","hint2":"全票の半分を超える最小の整数を考えよう。"},{"title":"類題5 (2)","hint1":"自分を含む3人が同票になると、2人の枠に必ず入れるかな？","hint2":"3人で分けられる票数の境目を超えることを考えよう。"},{"title":"類題5 (3)","hint1":"A以外で、現在の票が多い2人を選ぼう。","hint2":"Aに追加票を入れ、残りの票でその2人をAと同票以上にできるか調べよう。できなくなる最小の追加票を探そう。"}],"基本問題9":[{"title":"9","hint1":"1人だけ当選するなら、最も不利なのは残りの票が1人に集中する場合だよ。","hint2":"全体の半分より多い、最小の整数の票数を考えよう。"}],"基本問題10":[{"title":"10 (1)","hint1":"2人当選では、3人が同票になる境目が大切だよ。","hint2":"全体を3人で分けたときの票数より多く取れば、ほかの2人は同票以上になれないね。"},{"title":"10 (2)","hint1":"C以外で得票の多い2人を選び、未開票の票数も出そう。","hint2":"Cに追加票を入れたあと、相手2人をCと同票以上にするのに必要な票を計算しよう。残票で足りなくなるところを探そう。"}],"基礎演習6":[{"title":"6 (1)","hint1":"残りの票が1人に集まっても勝てることが必要だよ。","hint2":"25票の半分を超える最小の整数を考えよう。"},{"title":"6 (2)①","hint1":"Aの相手では、今いちばん票が多いのは誰？","hint2":"Aに追加票を入れ、残票が全部その相手に入っても、Aのほうが多くなる最小の追加票を探そう。"},{"title":"6 (2)②","hint1":"Cが増やした票以外が、最も強い相手に全部入る場合を考えよう。","hint2":"Cの最終票と、その相手の最大票を比べよう。同票では確実な当選とは言えないよ。"}],"練習問題7":[{"title":"7 (1)","hint1":"未開票の票数を出し、A以外で票が多い2人を探そう。","hint2":"Aの追加票を仮に決め、その2人がAと同票以上になるのに必要な票が残っているか調べよう。"},{"title":"7 (2)①","hint1":"全票から、今までの得票の合計を引こう。","hint2":"各候補に残票が全部入った場合でも、現在の上位2人に届かないなら落選確定だよ。同票に届く人まで除かないようにね。"},{"title":"7 (2)②","hint1":"Cの追加票を仮に決め、C以外の上位2人の票と比べよう。","hint2":"すでにC以上の票を持つ人には追加票がいらないよ。相手2人をCと同票以上にするのに必要な票と、残票を比べよう。"}],"標準演習6":[{"title":"6 (1)","hint1":"未開票の票数を求めよう。","hint2":"各候補に残票が全部入っても、すでに3人がそれより多い票を持つなら落選確定だよ。同票の場合は確定とはしないよ。"},{"title":"6 (2)","hint1":"E以外で票が多い3人を相手に考えよう。","hint2":"Eに追加票を入れた後、相手3人全員をEと同票以上にするには、何票必要？　すでにE以上の人は追加0票として、残票と比べよう。"}]},"6u-5":{"基本問題1":[{"title":"1　果物の買い方","hint1":"りんごの個数を決めると、残りのみかん代が決まるよ。","hint2":"残りが90円で割り切れるかを表にしよう。どちらも1個以上という条件を忘れずに。"}],"基本問題2":[{"title":"2　3種類のえんぴつ","hint1":"40円を2本、50円を3本にまとめた組の、1本あたりの平均を求めよう。","hint2":"その平均のえんぴつと60円のえんぴつの2種類として、つるかめ算を使おう。組に入る本数から50円の分を取り出そう。"}],"基本問題3":[{"title":"3　おもりの組み合わせ","hint1":"16個を全部5gにしたとき、200gまであと何g足りないかな？","hint2":"15gへの交換は1個で10g、30gへの交換は25g増えるね。30gの個数を順に決め、残りを調べよう。各種類1個以上かも確認。"}],"基本問題4":[{"title":"4　家族の年令","hint1":"8年前にいた4人だけを、現在の年令に直そう。","hint2":"4人の年令の和が8年間に増えた分を79才に足し、現在の5人の合計から引こう。"}],"基本問題5":[{"title":"5　集合と人数の範囲","hint1":"2つの輪を描こう。重なる人数を最も少なくするには、輪の外をどうすればよいかな？","hint2":"最小は2つの人数の和が全体を超えた分。最大は人数の少ない輪が、もう一方にすっぽり入る場合だよ。"}],"基礎演習1":[{"title":"1　代金と買い方","hint1":"（1）えんぴつ代とボールペン代を別々に表そう。（2）ボールペンの本数を決めてみよう。","hint2":"残りの代金が50円で割り切れる本数だけを表に残そう。どちらも1本以上だよ。"}],"基礎演習2":[{"title":"2　3種類のノート","hint1":"（1）120円2冊と180円1冊をひと組として、1冊平均を求めよう。","hint2":"（2）100円と、その平均のノートの2種類として冊数を求めよう。求めた組の冊数のうち、180円が占める割合を使おう。"}],"練習問題1":[{"title":"1　3種類のおもり","hint1":"10gと25gは、重さの比をそのまま個数の比にはできないね。それぞれ1個の重さで割ろう。","hint2":"その個数比でひと組を作り、組の個数・重さを求めよう。全部5gとした重さとの差を、組への交換で考えよう。"}],"練習問題2":[{"title":"2　プリンの箱売り","hint1":"（1）箱の値段を中の個数で割ろう。（2）全部ばら売りならいくらになるかな？","hint2":"箱A1箱、箱B1箱にするごとの値引き額を使い、値引き合計になる組を探そう。プリンが合計39個に収まるかも確認。"}],"練習問題3":[{"title":"3　家族の年令","hint1":"（1）12年前にいた3人を現在に直そう。4人全体との差が妹だよ。","hint2":"（2）妹から一郎君を求め、子ども2人を全体から引こう。両親の和と年令差で母の年令を求めよう。"}],"練習問題4":[{"title":"4　テストと集合","hint1":"両方できた人数を④、どちらもできなかった人数を①と置いて輪を描こう。","hint2":"Aの人数＋Bの人数は、全体に重なりを足し、外側を引いたもの。その差が比のいくつ分か考えよう。"}],"練習問題5":[{"title":"5　3つの集合","hint1":"（1）BまたはCの外側には「Aだけ」と「どれも解けない」がいるよ。","hint2":"（2）Aだけ・Bだけ・Cだけを同じ方法で求めよう。全体から、その3つと「2問だけ」「どれもなし」を引こう。"}],"標準演習1":[{"title":"1　3種類の消しゴム","hint1":"（1）80円1個と100円3個の平均を使おう。（2）は全部80円にした代金との差に注目。","hint2":"（1）平均の組と120円の2種類にする。（2）100円・120円に替えたときの増加額で表を作り、3種類とも1個以上にしよう。"}],"標準演習2":[{"title":"2　2つの集合と人数","hint1":"（1）輪の重なりを最小・最大にしてみよう。（2）両方好き②、両方きらい①と置こう。","hint2":"好きな人数の和と全体の差から①がわかるよ。山が好きな人数から、両方好きな人数を引けば「山だけ」だね。"}],"チャレンジ1":[{"title":"1　3種類のペン","hint1":"（1）同じ本数のAとBは入れ替えても代金が変わらないね。余分な本数だけに注目。","hint2":"（2）多い方の余分な本数の代金を除くと、AとBを同じ本数ずつ買う問題になるよ。A＋Bの組とCの本数を整数で調べよう。"}],"チャレンジ2":[{"title":"2　硬貨の両替","hint1":"100円玉2枚を1組にすると、両替後は100円玉1枚と10円玉10枚。50円玉2枚の組も同じように考えよう。","hint2":"各組の元の金額と両替後の枚数を表にしよう。金額の合計と160枚の両方に合う組数を探し、最後に元の枚数へ戻そう。"}],"チャレンジ3":[{"title":"3　家族の年令","hint1":"（1）父以外の3人が16年で増える年令の合計が、現在の父の年令になるよ。","hint2":"（2）8年前の父から子ども2人の和を求めよう。母が現在の父と同じ年令になる時点の「母以外の3人の和」と比べ、その時点を求めると現在へ戻せるね。"}],"チャレンジ4":[{"title":"4　3問の正解者と集合","hint1":"5点は「問3だけ」と「問1・問2」の2通りあるよ。得点を3つの輪に書き込もう。","hint2":"（1）2問だけ正解した人数を使い、5点の2種類を分けよう。（2）問3正解の人数からイ＋ウを求め、差の条件で分けよう。最後にアを求めよう。"}],"基本問題6":[{"title":"6　2人の仕事量","hint1":"全体を42と56の公倍数にすると、2人の1日の仕事量を整数で表せるよ。","hint2":"（1）全体÷日数で比を作ろう。（2）全体を、2人の1日の仕事量の和で割ろう。"}],"基本問題7":[{"title":"7　3人の仕事算","hint1":"全体を24・36・90の公倍数にして、まずC、次にB、Aの順に1日の仕事量を求めよう。","hint2":"Aの8日分とCの6日分を全体に足せば、3人が休まず働いたときの仕事量に直せるよ。それを3人の1日分で割ろう。"}],"基本問題8":[{"title":"8　大人と子どもの仕事","hint1":"2つの条件で、大人と子どもが働いた「人数×時間」をそれぞれ書こう。","hint2":"全体の仕事が等しいので、その差から大人1人と子ども1人の仕事量の比がわかるよ。全体と、求める組の1時間分を同じ単位で表そう。"}],"基本問題9":[{"title":"9　窓口と行列","hint1":"窓口1つの1分の人数を□として、2つ・3つのときの「1分で減る人数」を書こう。","hint2":"（1）減る人数×時間は、どちらもはじめの人数。（2）はじめの人数を求め、窓口1つのときの減り方で割ろう。"}],"基礎演習3":[{"title":"3　2人の仕事算","hint1":"全体を40と24の公倍数に置き、AとBの1日分を求めよう。","hint2":"（2）Aの16日分と2人の4日分を全体から引こう。残りをBの1日分で割り、すでに働いた日数を足そう。"}],"基礎演習4":[{"title":"4　入口と行列","hint1":"600人が50分・30分で減るとき、それぞれ1分に何人ずつ減るかな？","hint2":"入口が1つ増えたときの減り方の差が、入口1つの能力になるよ。そこから行列に加わる人数を逆算し、指定の順に答えよう。"}],"練習問題6":[{"title":"6　3本の管と注水","hint1":"（1）満水になる3つの条件を比べ、共通の管の分を引こう。A40分分＋B60分分と、A40分分＋B40分分＋C30分分が手がかり。","hint2":"（2）全体からAの20分分を引き、B＋Cの1分分で割り、最初の20分を足す。（3）最初の18分分を引き、残りをB＋CとA＋Cの2種類で分けよう。Aを使った最初の時間も足そう。"}],"練習問題7":[{"title":"7　牧場の草と牛","hint1":"牛1頭が1日に食べる量を1とし、2条件で食べた総量の差を日数の差で割ろう。","hint2":"（1）生える量と食べる量をつり合わせる。（2）はじめの草を「60頭分−生える分」で割る。（3）はじめの草の8日分の割り当てに、生える分を足そう。"}],"標準演習3":[{"title":"3　3人の仕事量","hint1":"全体を90・30・15の公倍数に置こう。","hint2":"（1）A、A＋B、B＋Cから引き算で3人の1日分を出す。（2）全体をA＋Cの1日分で割ろう。"}],"標準演習4":[{"title":"4　入口と行列の人数","hint1":"入口2つで行列が変わらないなら、入る人数と加わる人数が等しいね。","hint2":"入口3つで減った人数から、入口1つの能力がわかるよ。3つで実際に減らした時間からはじめの人数を出し、5つのときの減り方で割ろう。"}],"チャレンジ5":[{"title":"5　3人が交代する仕事","hint1":"全体を60・45・30の公倍数に置いて、各人の1日分を求めよう。","hint2":"（1）は3人分の和で割り、終わる日を数える。（2）は休む人の順に3日分をひと組にし、余りは1日ずつ処理しよう。最後に（1）の日数との差を取ろう。"}],"チャレンジ6":[{"title":"6　水を使いながら注水","hint1":"午前11時から正午までは、使わずに水が増えるね。この1時間も図に入れよう。","hint2":"半分の水量を、Aが使った2時間と、その後の5時間の条件でそれぞれ表そう。注水量と使用量の比が出たら、全体の水量を注水の1時間分で割ろう。"}],"チャレンジ7":[{"title":"7　窓口と券売機","hint1":"（1）は1日目の入場総数を窓口数と時間で割る。（2）は2日目の2条件で、はじめの人数が同じことを使おう。","hint2":"（3）3日目を最初の10分・次の5分に分け、減った人数を足そう。それが残り人数にも等しいね。10分で処理するために必要な追加能力を、窓口1つの能力で割り、端数を切り上げよう。"}],"基本問題10":[{"title":"10　整数と倍数の場合の数","hint1":"（1）下2けたで4の倍数を選ぼう。（2）3枚の数字の和が3の倍数になる組を選ぼう。","hint2":"百の位は0にできないよ。0のカード2枚を入れ替えただけの整数は、同じものとして数えよう。"}],"基本問題11":[{"title":"11　旗の立て方","hint1":"（1）青い旗の場所を選べば並び方が決まるね。（2）両端の赤を先に置こう。","hint2":"（1）は9か所から青の場所を選ぶ。（2）は両端以外の場所から選ぼう。選ぶ順番を変えても同じ並び方だよ。"}],"基本問題12":[{"title":"12　硬貨の支払い方","hint1":"（1）100円玉の枚数から決めよう。（2）100円玉・50円玉で作る金額を先に並べよう。","hint2":"（1）残りを50円・10円で払う場合を数えよう。（2）各金額に10円玉0〜3枚を足し、0円を除こう。同じ金額を重ねて数えないでね。"}],"基本問題13":[{"title":"13　平行四辺形の個数","hint1":"平行四辺形を1個作るのに、それぞれの向きの線が何本必要かな？","hint2":"3本から2本を選ぶ方法と、5本から2本を選ぶ方法を求めてかけよう。"}],"基本問題14":[{"title":"14　直線上の点と三角形","hint1":"8点から3点を選ぶ方法を先に数えよう。","hint2":"同じ直線上の3点では三角形にならないね。上の直線・下の直線ごとに、除く組を数えよう。"}],"基本問題15":[{"title":"15　格子点から正方形","hint1":"（1）まっすぐな正方形と、傾いた正方形を分けて描こう。","hint2":"傾いたものは外側の正方形から四隅の三角形を引くと面積がわかるよ。（2）は同じ大きさでも位置の違うものをすべて数え、面積に個数をかけて足そう。"}],"基本問題16":[{"title":"16　円周上の点と三角形","hint1":"（1）3点の選ぶ順番は区別しないよ。（2）3つの頂点の間にある円周の区間数を考えよう。","hint2":"（2）は7を3つの正の整数に分けよう。順番を替えただけの組は、回したり裏返したりすると重なるよ。"}],"基礎演習5":[{"title":"5　白石と黒石の並べ方","hint1":"（1）両端の黒を置こう。（2）白4個を1つのかたまりにしよう。","hint2":"（1）残りの場所から黒の場所を選ぶ。（2）黒5個の間と両端に、白のかたまりを置ける場所を数えよう。"}],"基礎演習6":[{"title":"6　硬貨で作る金額","hint1":"（1）100円玉を使う・使わないに分け、合計3枚にしよう。","hint2":"（2）10円玉だけでできる部分と、50円・100円でできる部分を表にしよう。同じ金額はまとめ、0円は除こう。"}],"練習問題8":[{"title":"8　硬貨で作る金額","hint1":"（1）1円玉と5円玉で、どこまでの金額を途切れず作れるかな？","hint2":"（1）そこに10円玉を足して範囲を広げよう。（2）1〜4円、5〜9円、10円以上の順に、欠ける金額が出ない最少の硬貨をそろえよう。"}],"練習問題9":[{"title":"9　正方形の中の三角形","hint1":"正方形の1辺を基準に、必要な三角形の底辺と高さの組を探そう。","hint2":"（1）は辺全体を底辺にする図を探す。（2）は底辺が半分の場合、対角線などを使う場合を分けて図に印をつけよう。同じ3頂点を重ねて数えないでね。"}],"標準演習5":[{"title":"5　格子点から正方形","hint1":"（1）（2）は左上などの目印を決め、図をずらして置ける場所を数えよう。","hint2":"（3）は水平な辺をもつものと、傾いたものを分けよう。傾いた1辺の「横に進む数・縦に進む数」を組にして、抜けを防ごう。"}],"標準演習7":[{"title":"7　取り出し方の場合の数","hint1":"（1）最後に1個取る場合・2個取る場合に分け、少ない個数の結果を使おう。","hint2":"（2）全部1個ずつ8回なら何個？ 10個にするため2個取る回が何回必要かを求め、その回の場所を選ぼう。"}],"チャレンジ9":[{"title":"9　正三角形と二等辺三角形","hint1":"（1）Bから等しい長さになる2辺を探そう。（2）は大きい正三角形の辺に沿うものと、沿わないものに分けよう。","hint2":"（3）二等辺三角形の等しい2辺が集まる頂点を決めて数えよう。A型・B型・C型のように対称な位置でまとめ、正三角形を除こう。"}],"チャレンジ10":[{"title":"10　奇数・偶数と線の色","hint1":"（1）和が奇数になるのは、どんな2数の組かな？","hint2":"（2）3辺とも赤にするには、3頂点の偶奇をどうそろえる？ 奇数の組と偶数の組を別々に数えよう。"}],"基本問題17":[{"title":"17　組に並んだ整数","hint1":"第8組の前までに並んだ数の個数を求めよう。","hint2":"第1組から第7組までの個数を足してから、第8組の中の位置を足そう。"}],"基本問題18":[{"title":"18　数表の段と列","hint1":"（1）1段目の数は平方数だね。そこから同じ列を下へ進むとどう変わるかな？","hint2":"（2）85をはさむ平方数を探そう。1つ前の正方形の表の次から、下の段を右へ、その後上へ進む順で数えよう。"}],"基本問題19":[{"title":"19　空きびんの交換","hint1":"（1）交換で受け取ったジュースも空きびんになるね。残ったびんと合わせて次を調べよう。","hint2":"（2）1回交換して飲むと、びんは差し引き何本減るかな？ 候補の購入本数で、実際に50本まで飲めるか、1本少なくしてもよいか確認しよう。"}],"基本問題20":[{"title":"20　硬貨で払う方法","hint1":"最後に置く硬貨が50円の場合と100円の場合に分けよう。","hint2":"ある金額の作り方は「50円少ない金額の作り方＋100円少ない金額の作り方」。50円刻みの表を500円まで伸ばそう。"}],"基本問題21":[{"title":"21　選挙と当選に必要な票","hint1":"3人を選ぶとき、自分を含む4人が同じ票数だと確実には当選できないね。","hint2":"38票を4人にできるだけ均等に分けよう。その同票の境目を超えるには何票必要かな？"}],"基礎演習7":[{"title":"7　組に並んだ整数","hint1":"4個ずつに線を引き、各組の最初と最後を表にしよう。","hint2":"（1）38番目が何組の何番目か調べる。（2）20が最初に現れる組の末尾を探し、前の組までの個数を足そう。"}],"基礎演習8":[{"title":"8　空きびんの交換","hint1":"（1）交換した分を飲んだ後のびんも、残りと合わせよう。","hint2":"（2）交換1回でびんが差し引き何本減るかを使おう。購入本数の候補で50本以上飲めるか、1本少ない場合も確認しよう。"}],"練習問題10":[{"title":"10　分数の並び","hint1":"各組を1/n、2/n、…、n/nと書き直そう。（1）（2）は目当ての分数が何組目のどこにあるかを探すよ。","hint2":"（3）1＋2＋…の個数の和で120番目の組を探そう。（4）1組の和は両端を組にすると求めやすいね。組ごとの和を足そう。"}],"練習問題11":[{"title":"11　連絡する人数の増え方","hint1":"「その1分で新しく連絡を受けた人数」と「そこまでの合計」の2段の表を作ろう。","hint2":"新しく伝わる人数は、1分前に受けた人の1回目と、2分前に受けた人の2回目を合わせたもの。（1）は合計、（2）は合計が人数に届く時刻を探そう。"}],"標準演習6":[{"title":"6　選挙と当選の票数","hint1":"（1）自分を含む3人で票を分ける場合を考えよう。（2）残り票をBとEで争う場合が手がかり。","hint2":"（2）Eに入る票を仮に決め、残り全部がBに入ってもEが上回るか調べよう。答えるのは最終票数ではなく追加票だよ。"}],"チャレンジ8":[{"title":"8　仕切りを入れる方法","hint1":"○がn個なら、仕切りを置けるすき間は何か所かな？","hint2":"各すき間で「置く・置かない」を選ぶので2を順にかけよう。仕切りを1つも置かない場合を除くよ。（3）は除く前に戻して、2を何回かけたか調べよう。"}],"チャレンジ11":[{"title":"11　組に分けた分数の並び","hint1":"1を目印に区切り、第n組をn/n、n/(n−1)、…と書き直そう。","hint2":"（1）組の個数を足して100番目の組と位置を探す。（2）値が2になる分母を考え、最後の組では100番目より前に現れるか確認しよう。"}],"チャレンジ12":[{"title":"12　平方数を使う数表","hint1":"（1）段と列が等しいマスの数を並べよう。（2）その近くの対角線上の数を目印にしよう。","hint2":"（3）260の直前の平方数を探そう。そこから数が1増えるたび、図では段と列がどう動くかを追おう。空白のマスを飛ばして数えるよ。"}],"チャレンジ13":[{"title":"13　前の数を使う数列","hint1":"（1）分母をそろえて順に足そう。（2）は全部3倍した整数の列で考えると調べやすいよ。","hint2":"（2）3倍した数を3で割った余りを並べ、余り0が出る間隔を探そう。整数が初めて出る位置から、50個目までの間隔の個数を数えよう。"}]},"6u-7":{"例題1・類題1":[{"title":"例題1 (1)","hint1":"折ってぴったり重なる折り目を、図に1本ずつかこう。","hint2":"縦・横だけでなく、頂点や辺の真ん中を通る斜めの線も調べよう。同じ線を2回数えないでね。"},{"title":"例題1 (2)","hint1":"図を中心のまわりに半回転させてみよう。","hint2":"180度回したあと、頂点だけでなく辺も全部重なるか確認しよう。"},{"title":"類題1 (1)","hint1":"半分に折って重なる線を探そう。","hint2":"頂点を通る折り目と、向かい合う辺の真ん中を通る折り目を分けて調べよう。"},{"title":"類題1 (2)","hint1":"中心のまわりに180度回した図を想像しよう。","hint2":"1つの頂点が、反対側の頂点に移るかな？　ほかの頂点も同じように確かめよう。"}],"基本問題1":[{"title":"1 (1)","hint1":"折り目の候補をかき、色のついた部分が重なるか調べよう。","hint2":"外形だけでなく、内側の穴や白い部分も確かめよう。斜めの折り目も忘れずに。"},{"title":"1 (2)","hint1":"中心のまわりに180度回して、色の配置を比べよう。","hint2":"1つの部分だけで決めず、反対側の部分がすべて対応するか確かめよう。"}],"基礎演習1":[{"title":"1 (1)","hint1":"折れ曲がる点を1つずつ、軸の反対側に移そう。","hint2":"軸から垂直な方向に、同じマス数だけ離れた点を取り、元と同じ順につなごう。"},{"title":"1 (2)","hint1":"各頂点からOまでの、縦と横のマス数を数えよう。","hint2":"Oから反対方向へ同じマス数進んだ点が対応する点。全部の点を移してからつなごう。"}],"練習問題1":[{"title":"1 (1)","hint1":"中心のマスの中心を軸に、色のついたマスを半回転させよう。","hint2":"対応先に色がないマスを探そう。数字の形ではなく、ぬった部分の形を見るよ。"},{"title":"1 (2)","hint1":"縦・横・斜めに折る場合をそれぞれ試そう。","hint2":"それぞれの折り目で、足りない色のマスが1つだけなら条件に合う。同じ答えを重ねて数えないでね。"}],"標準演習1":[{"title":"1 (1)","hint1":"中心のまわりに180度回したとき、どの区画どうしが対応するか組にしよう。","hint2":"すでに置かれた2枚が対応するか確認し、残る2枚をどの組に置けるか数えよう。"},{"title":"1 (2)","hint1":"残りの区画から2つ選ぶ組み合わせを、抜けがないように書き出そう。","hint2":"各配置で、縦・横・斜めなどの折り目を試そう。1つの配置に複数の対称の軸があっても、その配置は1通りだよ。"}],"例題2・類題2":[{"title":"例題2 (1)","hint1":"OとDは、折って重なる2点だね。","hint2":"重なる2点を結ぶ線と折り目は、どんな角度で交わるかな？"},{"title":"例題2 (2)","hint1":"ODをかき、半径で等しい辺と、折って等しくなる辺に印をつけよう。","hint2":"三角形BODの形からBの角を調べよう。BCがその角を二等分することを使い、三角形BOCの角を求めよう。"},{"title":"類題2 (1)","hint1":"ODを結ぼう。OA・ODは半径で、OAとADは折って重なる辺だよ。","hint2":"三角形AODの形を調べよう。折り目ACは、OADの角をどう分ける？"},{"title":"類題2 (2)","hint1":"折る前の三角形AOCで、Cの角を求めよう。","hint2":"折ったあともCの対応する角は等しい。B・C・Oが一直線であることを使おう。"}],"基本問題2":[{"title":"2 (1)","hint1":"BO・OC・BCが等しいことを、半径と折り返しから説明してみよう。","hint2":"三角形BOCの形から、角CBDを求めよう。三角形BODでDの角を出し、折ったあとの角に移そう。"},{"title":"2 (2)","hint1":"OCとOAを結んだ二等辺三角形に注目しよう。","hint2":"中心角COAは、中心角BOAから角BOCを除いた角。三角形AOCの内角の和から、その中心角を引こう。残った2つの角は等しいので、二等分してAの角を求めよう。"}],"基本問題3":[{"title":"3","hint1":"Oも折り返したと考え、その移った点をO′としよう。PはOに重なるよ。","hint2":"OO′は元のOPと同じ半径の長さ。AO・AO′・OO′、BO・BO′・OO′を比べ、できる三角形から角AOBを考えよう。"}],"基礎演習2":[{"title":"2 (1)","hint1":"ODを結び、半径と折り返しで等しい3辺を探そう。","hint2":"三角形AODの形からAの角がわかるね。折り目ACがその角を二等分するよ。"},{"title":"2 (2)","hint1":"三角形AOCでCの角を求め、折ったあとの角ACDに移そう。","hint2":"B・C・Oが一直線なので、Cのまわりのどの角を足すと180度になるか見よう。"}],"練習問題2":[{"title":"2 (1)","hint1":"2回目の折り目DGは角ADFを二等分するよ。","hint2":"DAとDBは一直線。角BDFを求め、1回目の折り返しでDEがそれを二等分することを使おう。Eの角も折り返しと一直線から求めよう。"},{"title":"2 (2)","hint1":"三角形ABCのBの角は(1)でわかるね。","hint2":"直角三角形ABCからAの角を求め、三角形ADGの内角の和を使おう。"}],"標準演習2":[{"title":"2 (1)","hint1":"OCを結び、半径と折り返しで等しい辺を探そう。","hint2":"三角形AOCの形からAの角を出し、折り目ADが二等分する角を使おう。最後にDの一直線の角を考えよう。"},{"title":"2 (2)","hint1":"周りを、曲線の部分と直線の部分に分けよう。","hint2":"曲線を合わせると元のおうぎ形の弧になる。直線ではACとAO、CDとDOが等しいことを使い、まとめられる長さを探そう。"}],"例題3・類題3":[{"title":"例題3 (1)","hint1":"折ったあとのFEとEIが作る角に注目し、三角形AEFとDIEを比べよう。","hint2":"対応はA↔D、E↔I、F↔E。AFとDEの比からDIを求め、底辺と高さで面積を出そう。"},{"title":"例題3 (2)","hint1":"BFとEF、BCとEHは、それぞれ折って重なる辺だよ。","hint2":"まずEIを相似で求め、EHから引いてHIを出そう。次に三角形DIEとHIGの相似でHGを求め、CGとの関係を考えよう。"},{"title":"類題3 (1)","hint1":"三角形BFEとCEIの等しい角を探そう。","hint2":"対応はB↔C、F↔E、E↔I。BEとCEを出し、相似比からCIを求めて面積を出そう。"},{"title":"類題3 (2)","hint1":"AFとFE、ADとEHは折る前後で等しいよ。","hint2":"まずEIからHIを求めよう。三角形CEIとHGIの相似でHGを出したら、折り目上のGからD・Hまでの長さを比べよう。"}],"基本問題4":[{"title":"4 (1)","hint1":"三角形BGFとAHGの等しい角を探そう。","hint2":"対応はB↔A、G↔H、F↔G。AGを求め、BFとAGの比からAHを出そう。"},{"title":"4 (2)","hint1":"GFは、折る前のどの辺と等しいかな？","hint2":"CFからGFを出し、(1)と同じ相似比でGHを求めよう。"}],"基本問題5":[{"title":"5 (1)","hint1":"三角形ABEとDGBを比べよう。","hint2":"ABとDGが等しいので、相似比を使ってAEを求められるね。折る前の縦9cmの残りがEBに重なるよ。"},{"title":"5 (2)","hint1":"(1)の三角形ABEとDGBは、相似で対応する辺も等しいので合同だよ。EBとBGが等しいことを使い、元の長方形の横と等しいBCからBGを引こう。","hint2":"三角形CGFとDGBの対応はC↔D、G↔G、F↔B。CGとDGの比でCFを求めよう。"},{"title":"5 (3)","hint1":"三角形CFGの直角はどの頂点？","hint2":"直角をはさむCFとCGを、底辺と高さに使おう。"}],"基礎演習3":[{"title":"3 (1)","hint1":"Fの折り返された角が直角であることを図に書こう。","hint2":"左上の小さい直角三角形に、DFCと等しい角があるか探そう。答えるときは対応する頂点の順もそろえよう。"},{"title":"3 (2)","hint1":"まずDFを、長方形の横とAFから求めよう。","hint2":"(1)の相似な三角形で、DFに対応する辺と、CDに対応する辺を見つけ、比を立てよう。"},{"title":"3 (3)","hint1":"三角形EFCは、折る前の三角形EBCと同じ面積だよ。","hint2":"CDからAEを引いてEBを求め、折る前の直角三角形で面積を出そう。"}],"練習問題3":[{"title":"3 (1)","hint1":"折り目BDをはさむ等しい角と、AD・BCが平行なことを使おう。","hint2":"三角形BFDで、BとDの角が等しくなるか確認しよう。二等辺三角形なら、どの辺が等しい？"},{"title":"3 (2)","hint1":"折り返しからBEを求め、BFを引いてEFを出そう。","hint2":"まずAFを出して三角形ABFの面積を求めよう。AEFとABFは、底辺を同じ直線上のEF・BFに取ると高さが共通だよ。"}],"練習問題4":[{"title":"4 (1)","hint1":"BHはEHと等しいので、ABからBHとHGを引いてAGを求めよう。","hint2":"三角形AGJとEGHの対応はA↔E、G↔G、J↔H。AGとEGの比でAJを出そう。"},{"title":"4 (2)","hint1":"相似でGJを求め、折り返しでEFを求めると、FJがわかるよ。","hint2":"三角形FJKとEGHの相似からJKを出し、JDから引いてDKを求めよう。最後に三角形DKIとEGHの相似でDIを出そう。"},{"title":"4 (3)","hint1":"折り返した四角形EFIHの面積から、紙の外へ出た2つの三角形を引こう。","hint2":"折る前の台形BHICで面積を求め、三角形EGHとFJKを除こう。台形の平行な辺はBHとCIだよ。"}],"標準演習3":[{"title":"3 (1)","hint1":"三角形BEGとCGIを比べよう。EGは折る前のAEと同じ長さだよ。","hint2":"対応はB↔C、E↔G、G↔I。BEとCGの比から、EGに対応するGIを求めよう。"},{"title":"3 (2)","hint1":"GHはADと等しいので、GIを引くとHIがわかるね。","hint2":"三角形CGIとHFIの対応はC↔H、G↔F、I↔I。CIとHIの比を使ってFHを出そう。"},{"title":"3 (3)","hint1":"折り返した台形EGHFから、外へ出た三角形HFIを引こう。","hint2":"台形は折る前のAEFDと同じ面積。AEとDFを平行な2辺として求め、直角三角形HFIの面積を引こう。"}],"チャレンジ1":[{"title":"1 (1)","hint1":"BとDを結ぶ線は、折り目PQと垂直に交わり、Sで二等分されるよ。","hint2":"Sは長方形の中心。三角形BSTとQSTの相似で、BT・STからQTを求めよう。"},{"title":"1 (2)①","hint1":"BQとDQは最初の折り返しで等しいよ。(1)からQCを出すと、三角形QCDの辺と面積がわかるね。","hint2":"三角形QCDの面積を、今度はQDを底辺として使おう。CからQDへの高さを出せば、CUは折り返しによってその何倍になる？"},{"title":"1 (2)②","hint1":"三角形PDQの中から、三角形UDQを取り除こう。","hint2":"PDとQからPDまでの高さを求めよう。三角形UDQの面積は、折る前の三角形CDQと同じだよ。"}],"例題4・類題4":[{"title":"例題4","hint1":"へいの影の先端から、電柱まで水平線を引こう。","hint2":"できた直角三角形の横が8.4m。棒の「高さ：影」と同じ比で縦を求め、へいにうつった高さを足そう。"},{"title":"類題4","hint1":"かべの影の先端から、木まで水平線を引こう。","hint2":"棒の「高さ：影」の比を使い、木の上の部分の高さを求めよう。最後にかべの影の高さを足し、単位をそろえよう。"}],"基本問題6":[{"title":"6 (1)","hint1":"同じ時刻なら「高さ：影」の比が同じだよ。","hint2":"電柱の影から木の影へ何倍になったか調べ、その倍率を高さにもかけよう。"},{"title":"6 (2)","hint1":"電柱の高さとえみさんの身長を比べよう。","hint2":"高さが何倍になれば影も同じ倍率になるよ。"}],"基本問題7":[{"title":"7 (1)","hint1":"土手の影の先端から棒まで、水平線を引こう。","hint2":"横3.6mの三角形で縦の長さを求め、棒全体の高さから引こう。"},{"title":"7 (2)","hint1":"土手の上面の高さで、電柱まで水平線を伸ばそう。","hint2":"電柱のうち土手より上の高さに対応する横の長さを求めよう。その横の長さには、土手までの4mも含まれるよ。"}],"基礎演習4":[{"title":"4 (1)","hint1":"高さ、影の順に、同じ単位で比べよう。","hint2":"小数がある比は両方を同じ数倍し、整数の簡単な比に直そう。"},{"title":"4 (2)","hint1":"高さが元の棒の何倍になったか考えよう。","hint2":"影も同じ倍率になるよ。(1)の比を使っても求められるね。"},{"title":"4 (3)","hint1":"96cmは、比のうち「高さ」と「影」のどちら？","hint2":"比の1つ分を出して高さを求めよう。cmのままそろえて計算できるよ。"}],"練習問題5":[{"title":"5 (1)","hint1":"階段を横から見た図をかき、AからBまでの高さの差と水平距離を段数で数えよう。","hint2":"棒の先とBを結ぶ直線を、Aと同じ高さまで伸ばそう。できる相似な三角形から、平らな地面なら影がどこまで伸びるか求めよう。"},{"title":"5 (2)","hint1":"棒を遠ざけても、光の傾きは変わらないよ。Cの高さとAからの水平距離を調べよう。","hint2":"棒の先とCの高さの差から、棒からCまでの水平距離を求めよう。そこには元からあるAとCの水平距離も含まれるよ。"}],"標準演習4":[{"title":"4 (1)","hint1":"人の影の先を使う、大きい三角形と小さい三角形をかこう。","hint2":"大きい底辺は、電灯から人までに人の影を足した長さ。底辺の比を高さに移そう。"},{"title":"4 (2)","hint1":"今度は、へいの影の先を使う三角形をかこう。","hint2":"電灯からへいの影の先までと、へい自身の影の長さの比を、電灯とへいの高さの比に移そう。"}],"例題5・類題5":[{"title":"例題5 (1)","hint1":"街灯・人・影の先を結び、大きい三角形と小さい三角形をかこう。","hint2":"高さの比は「街灯から影の先まで：人の影」。そこから「歩いた距離：人の影」の比に直し、6秒間の歩行距離を使おう。"},{"title":"例題5 (2)","hint1":"影が5mのとき、街灯から人までの距離はどれだけになる？","hint2":"高さから決まる比は変わらないよ。歩いた距離を求めてから、歩く速さで割ろう。"},{"title":"類題5 (1)","hint1":"街灯の高さと身長の比を、地面の2つの長さの比に移そう。","hint2":"大きい三角形の底辺から影の長さを引いた部分が、街灯から人までの距離だよ。"},{"title":"類題5 (2)","hint1":"街灯から人までの距離と影の比は、(1)と同じだよ。","hint2":"4.2mが比のどの部分に当たるか確かめて、影の長さを求めよう。"}],"基本問題8":[{"title":"8 (1)","hint1":"大きい三角形の底辺は、5.1mだけではないよ。","hint2":"人までの距離と影の長さを足し、小さい三角形との底辺の比を高さに移そう。"},{"title":"8 (2)","hint1":"高さが変わらないので、人までの距離と影の比も変わらないよ。","hint2":"元の影から4mの影へ何倍かを調べ、5.1mにも同じ倍率をかけよう。"}],"基本問題9":[{"title":"9 (1)","hint1":"高さの比から、「街灯から人まで：影」の比を出そう。","hint2":"4秒後の影から歩行距離を出し、かかった時間で割ろう。"},{"title":"9 (2)","hint1":"一定の速さで歩くと、影も時間に比例して長くなるよ。","hint2":"4秒後の影と2.5mの影を比べ、その倍率を時間にも使おう。"}],"基礎演習5":[{"title":"5 (1)","hint1":"三角形ABCとDECの高さの比を、BCとECに移そう。","hint2":"BEはBCからECを引いた長さ。比の数でも同じ引き算ができるよ。"},{"title":"5 (2)","hint1":"2秒間に進んだ距離がBEだね。","hint2":"(1)の比で、BEからECを求めよう。"},{"title":"5 (3)","hint1":"影の先端の位置はBCで表すよ。人の移動距離はBEだね。","hint2":"BEが1秒に増える分に対し、BCは何倍増える？　BEとBCの比を使おう。"}],"練習問題6":[{"title":"6","hint1":"左右の街灯について、それぞれ「人までの距離：影」の比を出そう。","hint2":"CFとCGを同じ1つ分にそろえると、ACとCBの比がわかるよ。全体9mをその比で分けよう。"}],"練習問題7":[{"title":"7 (1)","hint1":"兄と弟それぞれについて、街灯から影の先までの距離を求めよう。","hint2":"高さの比から「人まで：影の先まで」の比に直そう。同じ街灯から測った2つの距離の差が、先端どうしの間隔だよ。"},{"title":"7 (2)","hint1":"弟が1m進むと、街灯から影の先までの距離は何m増える？","hint2":"人までの距離から先端までの距離への倍率を、歩く速さにも使おう。"},{"title":"7 (3)","hint1":"兄の影の先端の速さも、(2)と同じように求めよう。","hint2":"(1)の間隔を、2つの先端の速さの差で割ろう。人の歩く速さの差ではないよ。"}],"標準演習5":[{"title":"5 (1)","hint1":"高さの比から「歩いた距離：影」の比を求めよう。","hint2":"5秒後の影を使って歩いた距離を出し、5秒で割ろう。"},{"title":"5 (2)","hint1":"BとCについて、それぞれ「人までの距離：影」の比を出そう。","hint2":"Bによる影を1つ分、Cによる影を2つ分としてそろえよう。両街灯までの距離の比で、全体20.4mを分けよう。"}],"例題6・類題6":[{"title":"例題6 (1)","hint1":"まず三角形PQDを横から見た図として取り出そう。","hint2":"PQとEAの比を、QDとADの比に移そう。QDとADの差がQAだよ。"},{"title":"例題6 (2)","hint1":"今度は地面を真上から見て、三角形QABとQDCを比べよう。","hint2":"QAとQDの比が、ABとDCの比になる。(1)で求めた長さを使おう。"},{"title":"例題6 (3)","hint1":"影ABCDを真上から見ると、平行な2辺はどれかな？","hint2":"ABとCDを上底・下底とする台形だよ。台形の高さは、へいの高さではなく地面上のADだね。"},{"title":"類題6 (1)","hint1":"横から見た三角形PQDとEADをかこう。","hint2":"高さの比をQDとADに移し、差のQAを使ってADを求めよう。"},{"title":"類題6 (2)","hint1":"真上から見た三角形QABとQDCを比べよう。","hint2":"QAとQDの比から、へいの幅ABが影の幅DCに何倍されるか考えよう。"},{"title":"類題6 (3)","hint1":"台形ABCDの平行な2辺と、その間の距離を確認しよう。","hint2":"上底・下底にはABとCD、高さにはADを使おう。"}],"基本問題10":[{"title":"10 (1)","hint1":"三角形PHIとAEIを横から見て比べよう。","hint2":"電球の地面からの高さは、立方体の高さに4mを足したもの。HIとEIの比と、その差HEを使って、求めるEIの長さを出そう。"},{"title":"10 (2)","hint1":"真上から見て、三角形HEFとHIJを比べよう。","hint2":"HEとHIの比から、EFとIJの比がわかるよ。"},{"title":"10 (3)","hint1":"真上から見た外側の正方形HIJKから、立方体の底面を除こう。","hint2":"外側の一辺はHI。影に含めない正方形EFGHの面積を引こう。"}],"基礎演習6":[{"title":"6 (1)","hint1":"横から見た三角形PQDとEADを取り出そう。","hint2":"高さの比からQDとADの比を出し、その差QAを使おう。"},{"title":"6 (2)","hint1":"真上から見た三角形QABとQDCは相似だよ。","hint2":"QAからQDへ何倍になったかを、ABからDCにも使おう。"},{"title":"6 (3)","hint1":"影はABとCDが平行な台形だね。","hint2":"上底・下底・高さを、これまで求めた長さから選ぼう。高さは地面上のADだよ。"}],"練習問題8":[{"title":"8","hint1":"板の上辺と下辺が地面にうつる位置を、それぞれ横から見て求めよう。","hint2":"上から見ると、その2本の影は平行になる。Pからの距離の比でそれぞれの幅を出し、2本の間を台形として求めよう。"}],"練習問題9":[{"title":"9 (1)","hint1":"電球と屋根の各頂点を結び、その先にできる影を横から見て考えよう。","hint2":"高さの比で、街灯から頂点の真下までの距離が何倍になるか求めよう。上からの図で各頂点を同じ倍率だけ遠ざけ、建物との間も含めて影の輪郭をかこう。"},{"title":"9 (2)","hint1":"かいた影を、長方形・三角形・台形などに分けよう。","hint2":"建物そのものの底面は、地面に見える影に含めないよ。マスの一辺が何mか確認して面積を出そう。"}],"標準演習6":[{"title":"6 (1)","hint1":"横から見た相似を使い、屋根の各頂点の影までの距離の倍率を求めよう。","hint2":"上からの図で、街灯から各頂点へ線を伸ばし、倍率に合う点を取ろう。倉庫との間も影になり、倉庫の底面自体はぬらないよ。"},{"title":"6 (2)","hint1":"影の輪郭を、面積を求めやすい図形に分けよう。","hint2":"倉庫を含む大きな図形から求めた場合は、倉庫の底面を引こう。マスと実際の長さの対応も確認しよう。"}],"チャレンジ2":[{"title":"2 (1)","hint1":"真上から見たマス目を別にかこう。電球・立方体の上の頂点・影の先を横から見ると相似が使えるよ。","hint2":"Aから各頂点の真下までの距離を、相似で求めた倍率だけ伸ばそう。床にできる輪郭をかき、立方体の底面を除いて面積を数えよう。"},{"title":"2 (2)","hint1":"3個の立方体の上面の頂点を、上から見たマス目に写そう。","hint2":"それぞれの影を(1)と同じ倍率でかき、重なりは1回だけ数えよう。立方体の置かれた床も除こう。"},{"title":"2 (3)","hint1":"上面の高さが異なる場所を分けよう。1段の上面と2段の上面では、影を伸ばす倍率が違うよ。","hint2":"それぞれの高さで横からの相似比を出し、上からの図に影を重ねよう。内側の線を除いて外周を決め、重なりと立方体の底面を除いて面積を求めよう。"}]},"6u-8":{"例題1・類題1":[{"title":"例題1(1)","hint1":"自転車と徒歩に分けて、道のりの割合を書こう。","hint2":"それぞれの道のりの割合を、それぞれの分速で割って比にしよう。"},{"title":"例題1(2)","hint1":"24分を、(1)で求めた時間の比で分けよう。","hint2":"自転車と徒歩の道のりをそれぞれ「速さ×時間」で出し、合わせよう。"},{"title":"類題1(1)","hint1":"走った部分と、残りの部分の割合を出そう。","hint2":"それぞれの割合を160、80で割って、時間の比を作ろう。"},{"title":"類題1(2)","hint1":"12分を、走る時間と歩く時間に分けよう。","hint2":"各部分の速さに、その部分の時間をかけて道のりを出そう。"}],"基本問題1":[{"title":"1(1)","hint1":"ABとBCの道のりを、5と2で置こう。","hint2":"それぞれを、その区間の分速で割って比べよう。"},{"title":"1(2)","hint1":"14分を、(1)の時間の比で分けよう。","hint2":"歩いたのはBCの区間だよ。比のどちらに当たるか確認しよう。"},{"title":"1(3)","hint1":"走った時間は、全体から歩いた時間を引くと出るよ。","hint2":"ABは走った区間。対応する分速と時間をかけよう。"}],"基礎演習1":[{"title":"1(1)","hint1":"「BCはABの3/5」を、AB：BCの整数の比に直そう。","hint2":"各区間の道のりの比の数を、各区間の速さで割ろう。"},{"title":"1(2)","hint1":"全体の118分を、歩く時間と走る時間に分けよう。","hint2":"比の合計に全体の時間を当てはめ、走った区間の分を取り出そう。"},{"title":"1(3)","hint1":"BCは走った区間だね。","hint2":"走る速さに、(2)の時間をかけよう。"}],"練習問題1":[{"title":"1(1)","hint1":"3：4は「歩いた時間：全体の時間」だよ。","hint2":"走った時間の分を引き算で作り、各区間の速さと時間の比の数をかけよう。"},{"title":"1(2)","hint1":"1600mを、(1)の道のりの比で分けよう。","hint2":"家から公園は歩いた区間。比のどちらを使うか確かめよう。"}],"練習問題4":[{"title":"4(1)","hint1":"平地を歩く時間は、行きと帰りで同じだね。","hint2":"全体の時間の差は、坂道の時間の差だけから生まれるよ。"},{"title":"4(2)","hint1":"上りと下りの時間の比を、速さの逆比から作ろう。","hint2":"(1)を時間の比の差に合わせて坂道の時間を出そう。残りが平地の時間なので、各区間の道のりを出して足そう。"}],"標準演習4":[{"title":"4","hint1":"3区間の道のりを1、2、3として、各区間の時間を比で表そう。","hint2":"それぞれの数を各区間の時速で割ろう。合計時間をその比で分け、1区間の実際の距離から全体へ広げよう。"}],"チャレンジ1":[{"title":"1(1)","hint1":"残りの道のりは、最初の2時間で進んだ道のりの何倍かな。","hint2":"同じ速さで残りを進む時間を出し、速さを2倍にした分だけ時間を縮めよう。最初の2時間を足して予定と比べよう。"},{"title":"1(2)","hint1":"予定までの残り時間と、残りの道のりを取り出そう。","hint2":"最初と後半それぞれの「道のりの割合÷時間」を比べると、速さの倍率が出るよ。"}],"例題2・類題2":[{"title":"例題2(1)","hint1":"ABとBCで速さは変わるかな。","hint2":"道のりの比で48分を分け、ABの分を取り出そう。"},{"title":"例題2(2)","hint1":"Aがゴールした瞬間までに、Bが走った距離を出そう。","hint2":"同じ時間の距離の比が速さの比。Bが100m走る間にAが走る距離を求め、100mと比べよう。"},{"title":"例題2(3)","hint1":"いつもと今日で、学校までの道のりは同じだね。","hint2":"速さの逆比で時間の比を作り、その差を到着時刻の差に合わせよう。いつもの通学時間と20分を出発時刻に足そう。"},{"title":"類題2(1)","hint1":"速さが一定なので、ABとACの距離の比が時間の比になるよ。","hint2":"ABの20分をもとに、AC全体にかかる時間へ広げよう。"},{"title":"類題2(2)","hint1":"同じ時間にAは50m、Bは40m走っているね。","hint2":"Bが50m走るときのAの距離を比で出し、普通のスタートからの差を考えよう。"},{"title":"類題2(3)","hint1":"いつもより何分長く歩いたか、始業時刻の前後を線に描こう。","hint2":"速さの逆比で時間の比を作り、その差に「2分前から5分後まで」を対応させよう。"}],"基本問題2":[{"title":"2(1)","hint1":"BCの時間は、25分そのものかな。","hint2":"出発からCまでの時間から、Bまでの時間を引こう。ABとBCの時間を比べよう。"},{"title":"2(2)","hint1":"2人とも、ABとACの道のりの比は同じだね。","hint2":"あおいさんのAB：ACの時間の比を、たくみ君の9分に当てはめよう。"}],"基本問題3":[{"title":"3(1)","hint1":"兄が600m進んだとき、弟は何m進んだかな。","hint2":"弟の「あと200m」を、進んだ距離と取り違えないで比を作ろう。"},{"title":"3(2)","hint1":"兄が出発してからCに着くまでを、共通の時間にしよう。","hint2":"その間に兄が900m進むとき、弟が進む距離を比で求めよう。900mから引くと先に進んでいた距離になるよ。"}],"基本問題4":[{"title":"4(1)","hint1":"兄が200m走る間に、弟が走った距離を出そう。","hint2":"2人の走った距離の比が、そのまま速さの比になるよ。"},{"title":"4(2)","hint1":"スタートを下げると、兄が走る距離は長くなるね。","hint2":"兄がその距離を走る間の弟の距離を比で出し、200mまでの残りを調べよう。"},{"title":"4(3)","hint1":"まず、同時にゴールする境目を考えよう。","hint2":"弟が200m走る間の兄の距離を比で求めよう。普通の200mとの差が、下げる距離の境目だよ。"}],"基本問題5":[{"title":"5(1)","hint1":"行きと帰りの道のりは同じだね。","hint2":"速さの比を整数の比に直してから逆にしよう。"},{"title":"5(2)","hint1":"外出時間全部が、歩いた時間ではないね。","hint2":"休んだ30分を引き、残りを(1)の比で分けよう。行きの時間を午後2時に足そう。"}],"基本問題6":[{"title":"6(1)","hint1":"2通りの到着時刻は、何分離れているかな。","hint2":"速さの逆比で時間の比を作り、その差に到着時刻の差を対応させよう。時速を使うときは時間の単位をそろえてね。"},{"title":"6(2)","hint1":"求めた道のりを、時速40kmで進む時間を出そう。","hint2":"時速36kmで進む時間と比べ、10分遅れがどれだけ変わるか考えよう。"}],"基礎演習2":[{"title":"2(1)","hint1":"2kmと1.5kmを整数の比に直そう。","hint2":"2つの区間で速さは変わらないので、その比を時間にも使えるよ。"},{"title":"2(2)","hint1":"42分は2つの区間の時間の合計だよ。","hint2":"時間の比の合計と42分を対応させ、ABの時間を求めよう。"}],"基礎演習3":[{"title":"3(1)","hint1":"兄がゴールしたとき、弟が走った距離はいくらかな。","hint2":"200mと、弟が進んだ距離を比べよう。"},{"title":"3(2)","hint1":"弟が200m走る間に、兄はどこまで走れるかな。","hint2":"速さの比で兄の距離を出し、200mからはみ出す分を考えよう。"}],"基礎演習4":[{"title":"4(1)","hint1":"外出した時間から、遊んだ1時間を除こう。","hint2":"残りを80：60の逆比で分け、行きの時間を出発時刻に足そう。"},{"title":"4(2)","hint1":"行きにかかった時間を、(1)から取り出そう。","hint2":"行きの分速と、その時間をかけよう。"}],"練習問題2":[{"title":"2(1)","hint1":"Aがゴールした瞬間と、Bがゴールした瞬間を分けて考えよう。","hint2":"A：BとB：Cの速さの比を別々に作り、Bの数をそろえてつなごう。"},{"title":"2(2)","hint1":"Aが100m走る間のCの距離を、(1)の比で出そう。","hint2":"求めるのは進んだ距離ではなく、ゴールまでの残りだよ。"},{"title":"2(3)","hint1":"100mを走る時間の比は、速さの逆比になるね。","hint2":"Aの15.2秒をもとにB・Cのゴールまでの時間を出し、差を求めよう。"}],"練習問題3":[{"title":"3(1)","hint1":"今日と同じ速さで、20分早く出たら到着もどう変わるかな。","hint2":"今日の到着時刻を20分前へ動かし、始業時刻との関係を考えよう。"},{"title":"3(2)","hint1":"出発をそろえたときの、いつもの到着と(1)の到着の差を出そう。","hint2":"時間の比は速さの逆比。その差に合わせていつもの通学時間を出し、7時50分と15分を使おう。"}],"標準演習1":[{"title":"1 A君","hint1":"Aがゴールした瞬間に3人が進んだ距離を書こう。","hint2":"Cが100m走るときのAの距離を比で出し、100mとの差を取ろう。"},{"title":"1 B君","hint1":"3人の速さの比を、同じ瞬間の距離から作ろう。","hint2":"Cが100m走るときのBの距離を求め、普通のスタートから下げる分を取り出そう。"}],"標準演習2":[{"title":"2(1)","hint1":"到着時刻の差には、5分の休けいも入っているね。","hint2":"到着の差から休けいを除き、歩く時間の比の差に合わせよう。いつもの通学時間を出して始業時刻を求めよう。"},{"title":"2(2)","hint1":"遅れた日のうち、実際に歩いた時間を取り出そう。","hint2":"分速64mにかけるのは、休けいを除いた時間だよ。"}],"例題3・類題3":[{"title":"例題3(1)","hint1":"出会うまでに、兄と弟は全体のどれだけを歩いたかな。","hint2":"兄の割合と残りの割合を比べよう。歩いた時間は同じだよ。"},{"title":"例題3(2)","hint1":"兄は全体の3/5を12分で進んだね。","hint2":"速さは一定だから、道のりの比を使って、全体を進む時間に広げよう。"},{"title":"類題3","hint1":"出会うまでに2人が進む道のりを、速さの比で分けよう。","hint2":"かずま君が進むのは全体の何割分かな。全体を進む24分にも同じ割合をかけよう。"}],"基本問題7":[{"title":"7(1)","hint1":"出会うまでの2人の道のりの和は770mだね。","hint2":"速さの比で770mを分け、学校を出た人の道のりを選ぼう。"},{"title":"7(2)","hint1":"学校から出会う場所までと、家から出会う場所までを出そう。","hint2":"2人が同じ時間に進んだ距離として、そのまま比べよう。"}],"基本問題8":[{"title":"8(1)","hint1":"出会うまでに姉が進むのは、全体のどれだけかな。","hint2":"全体を進む18分を、その割合に縮めよう。"},{"title":"8(2)","hint1":"姉は18分で全体を進む。12分では全体のどれだけ進むかな。","hint2":"残りを妹が同じ12分で進んでいるよ。2つの割合を比べよう。"}],"基礎演習5":[{"title":"5(1)","hint1":"姉が18分で進んだ部分と12分で進んだ部分を、図に分けよう。","hint2":"姉の道のりの比は18：12。妹は後半の部分を18分で歩いたので、同じ18分の距離を比べよう。"},{"title":"5(2)","hint1":"妹の残りの道のりは、姉が最初の18分で進んだ部分だよ。","hint2":"同じ道のりを進む時間は速さの逆比。(1)を使って妹の時間に直そう。"}],"練習問題5":[{"title":"5(1)","hint1":"太郎君は折り返し、次郎君はまだ行きの途中だね。","hint2":"2人の進んだ距離の差は、運動場から出会う場所までの距離の2倍。この差を9：7の差に合わせよう。"},{"title":"5(2)","hint1":"太郎君が18分で進んだ道のりと、往復全体の道のりを比べよう。","hint2":"同じ速さなので、距離の比で時間を広げればよいよ。"}],"練習問題6":[{"title":"6(1)","hint1":"中点からB側に寄ると、Aからの距離は全体の半分より長いね。","hint2":"兄は1/2に1/10を足した分、弟は残りを進んだ。同じ時間なのでその割合を比べよう。"},{"title":"6(2)","hint1":"兄の出会う前と出会った後の距離を比べよう。","hint2":"後の距離を8分で歩くので、距離の比から出会う前の時間を出そう。"},{"title":"6(3)","hint1":"兄がAからBまで進む時間に、弟が進む距離を比で表そう。","hint2":"弟の残り400mが、全体のどれだけに当たるか考えよう。"}],"標準演習5":[{"title":"5(1)","hint1":"中点よりA側なので、兄の道のりは半分より短いね。","hint2":"1/2から1/5を引いた分が兄、残りが弟。2つを比べよう。"},{"title":"5(2)","hint1":"兄は(1)で求めた全体の一部分を24分で進むね。","hint2":"道のりの比を使って、全体を進む時間まで広げよう。"}],"例題4・類題4":[{"title":"例題4(1)","hint1":"追いついた場所まで、妹は何分、姉は何分歩いたかな。","hint2":"2人の道のりは同じ。歩いた時間の比を逆にして速さの比にしよう。"},{"title":"例題4(2)","hint1":"姉が出発するとき、妹は9分ぶん先にいるね。","hint2":"速さを比の数で置き、妹の先行距離を2人の速さの差で割ろう。"},{"title":"類題4","hint1":"2人の速さを比の数で置き、もえさんが8分で進む距離を出そう。","hint2":"その距離が、1分にどれだけずつ縮むかを考えよう。"}],"基本問題9":[{"title":"9(1)","hint1":"速さを比の数で置き、姉が6分で進むABを表そう。","hint2":"ABを2人の速さの差で割れば、追いつく時間になるよ。"},{"title":"9(2)","hint1":"姉が歩いた時間を、2つの時刻から求めよう。","hint2":"同じ道のりなので、時間は速さの逆比。妹の時間を出し、追いついた時刻から戻そう。"}],"基本問題10":[{"title":"10(1)","hint1":"追いつくまでに、母とみほさんが進んだ時間をそれぞれ出そう。","hint2":"同じ道のりを進んだ時間の比を逆にしよう。"},{"title":"10(2)","hint1":"母の自転車の速さを半分にして、走る速さの比を作ろう。","hint2":"みほさんの8分ぶんの先行距離を、走る母とみほさんの速さの差で割ろう。"}],"基礎演習6":[{"title":"6(1)","hint1":"2人とも、家から学校までの同じ道のりを進むね。","hint2":"12分と20分の比を逆にしよう。"},{"title":"6(2)","hint1":"速さを比の数で置き、妹の6分ぶんの先行距離を出そう。","hint2":"その距離を、姉と妹の速さの差で割ろう。"}],"練習問題7":[{"title":"7(1)","hint1":"AとB、AとCがそれぞれ出会うまでの時間を表にしよう。","hint2":"時間の逆比で速さの比を作ってAをそろえよう。C出発時のBの先行距離を、CとBの速さの差で割り、時刻に直そう。"},{"title":"7(2)","hint1":"Bと会うまで、Cと会うまで、Aはそれぞれ何分歩くかな。","hint2":"同じAの速さなので、その時間の比で360mを広げよう。"}],"標準演習3":[{"title":"3(1)","hint1":"うさぎが一本杉に着いた瞬間の、2匹の道のりを書こう。","hint2":"かめが進んだ距離は、600mから150mを引いた長さだよ。"},{"title":"3(2)","hint1":"起きた後のうさぎの速さを、(1)の1.2倍に直そう。","hint2":"うさぎが残り400mを走る間に、かめが進む距離を比で出そう。一本杉からBまでとの差が、先に進んでいた分だよ。"}],"標準演習7":[{"title":"7(1)","hint1":"AとB、AとCについて、追いつくまでの時間をそれぞれ出そう。","hint2":"同じ道のりの時間の逆比で速さの比を作り、Aの数をそろえてつなごう。"},{"title":"7(2)","hint1":"Cが出るとき、Bは4分ぶん先に進んでいるね。","hint2":"比の数で表したBの先行距離を、CとBの速さの差で割ろう。"}],"例題5・類題5":[{"title":"例題5(1)","hint1":"最初の出会いと、両方が折り返した後の出会いまでの道のりを描こう。","hint2":"2人の道のりの和がAB何本分になるか比べよう。速さの和は一定だよ。"},{"title":"例題5(2)","hint1":"ABを速さの比の和で表し、1回目の出会いの位置を書こう。","hint2":"妹が2回目までに進む距離を比で表し、折り返した位置を求めよう。2つの位置の差が600mだよ。"},{"title":"類題5(1)","hint1":"それぞれの出会いまでに2人が進んだ距離の和を、AB何本分かで表そう。","hint2":"距離の和の比が、出発からの時間の比になるよ。"},{"title":"類題5(2)","hint1":"ABを速さの比の和で表し、兄の動きを矢印で描こう。","hint2":"兄の1回目と2回目の位置の差を比で表し、480mに対応させよう。"}],"基本問題11":[{"title":"11(1)","hint1":"2回目は、どちらも折り返した後だね。","hint2":"最初と2回目までの道のりの和を比べよう。最後に分を時間と分へ直そう。"},{"title":"11(2)","hint1":"片道を速さの比の和で置き、2回目までの兄・弟の距離を表そう。","hint2":"2回目の位置がAから6kmになるよう、比の1つ分を決めよう。弟の進んだ全距離を(1)の時間で割ろう。"}],"基礎演習7":[{"title":"7(1)","hint1":"1回目と2回目までの2人の道のりの和を比べよう。","hint2":"どちらも折り返した後なので、図の矢印を足してAB何本分か数えよう。"},{"title":"7(2)","hint1":"ABを速さの比の和で表し、弟が2回目までに進む道のりを出そう。","hint2":"弟の「ABを進んでから戻った分」が450m。比で表した戻りの分を450mに合わせよう。"},{"title":"7(3)","hint1":"最初の12分に弟が進んだ距離を、(2)と速さの比から出そう。","hint2":"その距離を12分で割れば分速になるよ。"}],"練習問題8":[{"title":"8(1)","hint1":"兄がタクシーに乗った場所をCとしよう。兄と弟はCBを同じ速さで乗るね。","hint2":"到着の32分差は、ACを歩く時間と乗る時間の差になる。逆比でACを歩く時間を出し、徒歩の速さを使おう。"},{"title":"8(2)","hint1":"タクシーの動きを、A→B→Cと描こう。この間、兄はA→Cを歩くよ。","hint2":"同じ時間なので、タクシーの距離とACの比は速さの比。AB＋BCを表し、BC＝AB−ACを使ってABを求めよう。"}],"練習問題9":[{"title":"9(1)","hint1":"ABを9つ分として、ACとCBを図に入れよう。","hint2":"ひろと君はA→B→C、そうた君はB→A→C。この2つの全距離を比べよう。"},{"title":"9(2)","hint1":"最初と2回目までの、2人の道のりの和を比べよう。","hint2":"2回目までの21分を、その距離の比で最初までの時間に直そう。"},{"title":"9(3)","hint1":"ひろと君の速さの比から、最初の出会いの位置を出そう。","hint2":"そこからBまでの残りを、最初までの道のりと比べて時間を求めよう。分の端数は60倍して秒に直そう。"}],"標準演習6":[{"title":"6(1)","hint1":"片道を8つ分とし、最初の出会いまでの兄と弟の距離を描こう。","hint2":"今回は2人とも家から出発するよ。1回目までと2回目までの2人の道のりの和を比べ、その時間の倍率で兄の道のりを伸ばそう。折り返しを図で追い、2つの出会う位置の差に700mを当てはめよう。"},{"title":"6(2)","hint1":"2往復する道のりは2人とも同じだね。","hint2":"時間の比を速さの逆比から出し、差に16分を当てはめよう。兄の時間と2往復の距離から分速を出そう。"}],"標準演習8":[{"title":"8(1)","hint1":"太郎君は片道30分、花子さんは往復48分だね。","hint2":"同じ片道にそろえてから、時間の比を逆にしよう。"},{"title":"8(2)","hint1":"太郎君が引き返す瞬間までに、花子さんは何分歩いたかな。","hint2":"比の速さで2人の位置と間隔を表そう。引き返した後は向かい合うので、速さの和で間隔を割ろう。"}],"チャレンジ2":[{"title":"2(1)","hint1":"兄と妹は徒歩も乗車も同じ速さで、移動全体の時間も同じ。歩く距離はどうなるかな。","hint2":"兄の徒歩距離＝妹の徒歩距離として図に入れよう。父が出発して妹を降ろし、引き返して兄に会うまでの全距離と、兄の徒歩距離を速さの比で結ぼう。"},{"title":"2(2)","hint1":"妹の「オートバイの区間」と「歩く区間」を使うと簡単だよ。","hint2":"(1)から2つの距離を出し、それぞれの時間を求めて足そう。時速で出した時間は分に直そう。"}],"チャレンジ3":[{"title":"3(1)","hint1":"太郎と花子の2回目の出会いは、1回目までの時間とどう関係するかな。","hint2":"その18分後が太郎の往復終了。片道を仮の数にして太郎の速さを出そう。太郎＋花子は34分で片道、太郎＋次郎は85分で往復分を進むことを使おう。"},{"title":"3(2)","hint1":"次郎と花子は、反対の端から同時に出るね。","hint2":"(1)の速さの和で片道の仮の数を割り、7時からの時刻に直そう。"}]},"6u-9":{"例題1・類題1":[{"title":"例題1(1)","hint1":"1周を36と45の公倍数の長さとすると、2人の分速を表しやすいよ。","hint2":"1周の仮の長さを、2人の速さの和で割ろう。"},{"title":"例題1(2)","hint1":"Aが出るとき、Bは6分ぶん先にいるね。","hint2":"Bの先行距離を、AとBの速さの差で割ろう。"},{"title":"類題1(1)","hint1":"1周を24と40の公倍数として、2人の速さを出そう。","hint2":"反対方向だから、2人の進んだ距離の和が1周になれば出会うよ。"},{"title":"類題1(2)","hint1":"兄が出る時点で、弟が進んだ距離を仮の長さで表そう。","hint2":"8分ぶんの先行距離を、2人の速さの差で割ろう。"}],"基本問題1":[{"title":"1(1)","hint1":"1周を12と20の公倍数の長さとして、2人の速さを出そう。","hint2":"同方向では、進んだ距離の差が1周になるたびに追い越すよ。"},{"title":"1(2)","hint1":"反対方向では、次の出会いまでの距離の和が1周になるよ。","hint2":"1周を速さの和で割ろう。分の端数は60倍して秒に直そう。"},{"title":"1(3)","hint1":"Aが出る時点で、Bが4分で進んだ距離を出そう。","hint2":"その先行距離を速さの差で割ろう。(1)とは最初の間隔が違うね。"}],"基礎演習1":[{"title":"1(1)","hint1":"1周の道のりは2人とも同じだね。","hint2":"24：32の比を逆にしよう。"},{"title":"1(2)","hint1":"比の速さと姉の1周の時間から、1周の仮の長さを作ろう。","hint2":"同時に同じ場所を出たので、距離の差が1周になる時間を求めよう。"},{"title":"1(3)","hint1":"姉が出るとき、妹は4分ぶん先にいるね。","hint2":"妹の先行距離を2人の速さの差で割ろう。"}],"練習問題1":[{"title":"1(1)","hint1":"1周を仮の長さにして、BとCの分速を出そう。","hint2":"反対方向なので、1周を速さの和で割ろう。"},{"title":"1(2)","hint1":"AとCが同時に出発地点へ戻る最初の時間を求めよう。","hint2":"その時間までに、(1)の間隔が何回入るか数えよう。出発した瞬間は出会いに数えないよ。"}],"標準演習1":[{"title":"1(1)","hint1":"スタートで会うには、両方とも1周の整数倍を歩き終える必要があるよ。","hint2":"30分と45分の共通の倍数のうち、最初のものを探そう。"},{"title":"1(2)","hint1":"この小問の兄36分・弟45分を使い、1周の時間の逆比で速さの比を作ろう。(1)の姉・妹の時間とは別だよ。","hint2":"兄が出るときの弟の10分ぶんの先行距離を、速さの差で割ろう。"}],"例題2・類題2":[{"title":"例題2(1)","hint1":"15分と60分は、どちらも1周の長さに結びつく時間だよ。","hint2":"速さの「和：差」は時間の逆比。和と差から、兄と弟それぞれの速さの比を作ろう。"},{"title":"例題2(2)","hint1":"2人の速さを(1)の比の数で置こう。","hint2":"速さの和と15分から1周の仮の長さを出し、それぞれの速さで割ろう。"},{"title":"例題2(3)","hint1":"スタートで会うには、2人とも整数回の周回を終えている必要があるね。","hint2":"1周の時間の共通の倍数を探し、最初の時刻までに兄が何周するか調べよう。"},{"title":"類題2(1)","hint1":"速さの和で6分、速さの差で30分進むと、どちらも1周だね。","hint2":"6：30の逆比から和と差の比を作り、和差算で2人の速さを分けよう。"},{"title":"類題2(2)","hint1":"速さを比の数で置き、1周の仮の長さを出そう。","hint2":"その長さを姉の速さ、妹の速さでそれぞれ割ろう。"},{"title":"類題2(3)","hint1":"2人が同時に出発地点へ戻る、最初の時間を探そう。","hint2":"1周にかかる時間の共通の倍数を使い、その時間で姉が何周するか考えよう。"}],"基本問題2":[{"title":"2(1)","hint1":"1周を進む速さとして、「和」と「差」を比べよう。","hint2":"6分と24分の逆比が、和と差の比。和差算で兄と弟の速さに分けよう。"},{"title":"2(2)","hint1":"比の速さの和に6分をかけて、1周の仮の長さを出そう。","hint2":"その長さを、弟の比の速さで割ろう。"}],"基礎演習2":[{"title":"2(1)","hint1":"速さの和で12分、速さの差で48分進むと、どちらも1周だね。","hint2":"時間の逆比で和と差の比を出し、和差算で2人の速さに分けよう。"},{"title":"2(2)","hint1":"比の速さの和と12分を使って1周を表そう。","hint2":"その長さをAの比の速さで割ろう。"},{"title":"2(3)","hint1":"AとBがともに整数周になる最初のときを探そう。","hint2":"同じ時間の周回数の比も速さの比になる。最も簡単な整数の比にして考えよう。"}],"練習問題2":[{"title":"2(1)","hint1":"1時間17分を分に直し、出会いと追い越しで共通になる1周に注目しよう。","hint2":"速さの和と差の比は、2つの時間の逆比。和差算でAとBの速さを分けよう。"},{"title":"2(2)","hint1":"比の速さの和と21分から、1周の仮の長さを出そう。","hint2":"それをAの速さで割れば、Aの1周の時間になるよ。"},{"title":"2(3)","hint1":"追い越すまでの時間に、Aの1周の時間が何回入るかな。","hint2":"「何周したか」と「何周目にいるか」は違うよ。余りがあれば、次の周の途中だね。"}],"練習問題3":[{"title":"3(1)","hint1":"最初に追いつくまで、弟は4分長く進んでいるね。","hint2":"兄6分、弟は先行した時間も含めた時間。同じ道のりを進むので逆比を使おう。"},{"title":"3(2)","hint1":"兄は3周、弟は2周なので、今度は道のりが違うね。","hint2":"それぞれの周回数を、それぞれの比の速さで割って時間の比を作ろう。"},{"title":"3(3)","hint1":"兄が3周し弟が2周した時刻は同じでも、歩いた時間には出発のずれがあるよ。","hint2":"(2)の時間の比の差に4分を対応させ、兄の3周の時間から1周へ直そう。"}],"例題3・類題3":[{"title":"例題3(1)","hint1":"兄のA→C→Bと、弟のB→C→Aは同じ道のりだね。","hint2":"その道のりを進む36分と45分の比を逆にしよう。"},{"title":"例題3(2)","hint1":"兄がBからDへ進んだ時間を、60分と36分から出そう。","hint2":"弟が残りのD→Bを進む時間に、逆比で直そう。すでに進んだ60分を足すのを忘れずに。"},{"title":"例題3(3)","hint1":"速さを比の数で置き、A→C→Bの道のりを表そう。","hint2":"最初の出会いまでに2人が進む距離の和は、この弧の長さ。速さの和で割ろう。"},{"title":"類題3(1)","hint1":"兄の30分と弟の45分は、どちらもCを通るAB間だね。","hint2":"同じ道のりなので、時間の比を逆にして速さの比にしよう。"},{"title":"類題3(2)","hint1":"兄がB→Dを進む時間を取り出そう。","hint2":"弟がD→Bを進む時間を逆比で出し、Dで出会うまでの時間に足そう。"},{"title":"類題3(3)","hint1":"兄が30分で進むAB間を、比の速さで表そう。","hint2":"その道のりを2人の速さの和で割ろう。"}],"基本問題3":[{"title":"3(1)","hint1":"Aが出会った後の10分の区間は、Bが出会うまでの8分の区間と同じだよ。","hint2":"この同じ道のりを進む時間の比を逆にしよう。"},{"title":"3(2)","hint1":"Aが1周する時間を、出会う前と後から出そう。","hint2":"1周は同じ道のりだから、(1)の逆比でBの時間に直そう。"}],"基本問題4":[{"title":"4(1)","hint1":"最初の出会いからB地点までを、姉と妹それぞれ何分で進むかな。","hint2":"姉は出会った後、妹は出会う前に進んだ同じ区間。9分と15分を逆比で比べよう。"},{"title":"4(2)","hint1":"最初の出会いからCまで、姉にかかった時間を出そう。","hint2":"その間は妹にとっても同じ経過時間だよ。弧の長さは違っても、出会う時刻は同じだね。"},{"title":"4(3)","hint1":"最初の出会いから次の出会いまでに、2人の距離の和は何周ぶんかな。","hint2":"比の速さの和と(2)で1周を表し、それぞれの速さで割ろう。"}],"基礎演習3":[{"title":"3(1)","hint1":"弧DBを、兄は出会った後、弟は出会う前に進むね。","hint2":"兄8分と弟12分を、同じ道のりの時間として逆比にしよう。"},{"title":"3(2)","hint1":"Dで会ってからCで会うまで、2人に流れた時間は同じだよ。","hint2":"兄のD→Bの時間とB→Cの時間を足そう。"},{"title":"3(3)","hint1":"Dで会ってからCで会うまでの距離の和は1周だね。","hint2":"比の速さの和と(2)の時間から1周を表し、兄の速さで割ろう。"}],"練習問題4":[{"title":"4(1)","hint1":"最初の出会いからQまで、Aは4分、Bは出会う前の6分で進むね。","hint2":"同じ弧を進む時間の逆比で、歩く速さの比を作ろう。"},{"title":"4(2)","hint1":"まずAがQに着くまでの時間を出し、それをBがPに着く時間へ逆比で直そう。","hint2":"2回目に会った出発後の時刻から、BがPを通る時刻を引こう。"},{"title":"4(3)","hint1":"2回目の出会いから、AがPへ戻るまでの時間を調べよう。","hint2":"残りの2つの弧を比の距離で表そう。Bの残り距離をAの残り時間で割った速さと、Bの歩く速さを比べよう。"}],"標準演習2":[{"title":"2(1)","hint1":"15分後のAとCは、同じ方向へ進んだ距離の差が1200mだね。","hint2":"速さの比の差と1200mを対応させよう。同じ15分のAとBの距離の和が1周になるよ。"},{"title":"2(2)","hint1":"15分までのCの距離を、(1)で使った比から出そう。","hint2":"その距離を15分で割れば、Qを通る前の分速だよ。"},{"title":"2(3)","hint1":"A・Bと違って、Cは15分後にはまだQに着いていないね。","hint2":"CがQに着く時刻を先に出そう。3人それぞれのQからの距離を、30分までの残り時間で割って比べよう。"}],"チャレンジ1":[{"title":"1(1)","hint1":"Cで会うまでの距離の和は1800m。CからDで再び会うまでの和は1周だね。","hint2":"距離の和の比が時間の比になる。兄のACとC→B→Dもその時間の比になるので、1440mからACを出し、残りのBCと比べよう。"},{"title":"1(2)","hint1":"最初の4分と、次に会うまでの時間の比を考えよう。","hint2":"1800mと1周2700mを、2人の距離の和として比べよう。求めるのは出発からの合計時間だよ。"},{"title":"1(3)","hint1":"兄が1周する間に弟が進む距離を、速さの比から出そう。","hint2":"弟のB→C→A→Dの道のりを引くと、Dを過ぎた分になるよ。"}],"例題4・類題4":[{"title":"例題4(1)","hint1":"同じ距離を、姉は4つ、妹は5つに分けて進むね。","hint2":"1歩ぶんの長さは、歩数の比を逆にすると比べられるよ。"},{"title":"例題4(2)","hint1":"同じ時間に姉は3歩、妹は2歩進むね。","hint2":"各自の歩幅の比の数に、各自の歩数をかけて比べよう。"},{"title":"例題4(3)","hint1":"姉が3歩進む時間を「1組」としてみよう。","hint2":"1組で縮まる距離を歩幅の比で出そう。妹35歩ぶんの距離を縮める組数を求め、姉の歩数へ直そう。"},{"title":"類題4(1)","hint1":"父10歩と子15歩が同じ距離なので、歩幅の比を先に出そう。","hint2":"歩幅の比の数に、父5歩・子6歩をそれぞれかけよう。"},{"title":"類題4(2)","hint1":"父5歩・子6歩を1組にして、1組で縮む距離を出そう。","hint2":"子45歩ぶんの先行距離が何組でなくなるか求め、父の歩数に直そう。"}],"基本問題5":[{"title":"5(1)","hint1":"同じ距離をAは3歩、Bは5歩で進むね。","hint2":"歩数の比を逆にして、1歩の長さの比を作ろう。"},{"title":"5(2)","hint1":"同じ時間に進む歩数は、Aが2歩、Bが3歩だね。","hint2":"それぞれの歩幅の比の数に、それぞれの歩数をかけよう。"},{"title":"5(3)","hint1":"同じ時間の距離は、(2)の速さと同じ比になるよ。","hint2":"Aの比の数に60mを合わせ、Bの距離を出そう。"}],"基本問題6":[{"title":"6(1)","hint1":"まず、兄3歩と弟5歩から歩幅の比を出そう。","hint2":"同じ時間の兄3歩・弟4歩に、その歩幅をかけて比べよう。"},{"title":"6(2)","hint1":"兄3歩・弟4歩の時間を1組とし、縮む距離を歩幅の比で出そう。","hint2":"弟20歩ぶんの距離を縮める組数を求め、兄の歩数に直そう。"}],"基礎演習4":[{"title":"4(1)","hint1":"同じ距離に必要な歩数は兄4歩・弟5歩だね。","hint2":"歩数の比を逆にして、歩幅の比にしよう。"},{"title":"4(2)","hint1":"同じ時間の歩数は兄4歩・弟3歩だね。","hint2":"歩幅の比の数と歩数を、それぞれかけて比べよう。"},{"title":"4(3)","hint1":"兄4歩・弟3歩の時間を1組にしよう。","hint2":"1組で縮む距離を出し、弟30歩ぶんを縮める組数を求めよう。最後に兄の歩数に直そう。"}],"練習問題5":[{"title":"5(1)","hint1":"出会いの前後の道のりを、どちらもBの歩数で表してみよう。","hint2":"Aが出会うまでに進んだ距離は、Bの960歩ぶん。Bが出会うまでの640歩ぶんと比べよう。"},{"title":"5(2)","hint1":"Bの全歩数からBの歩幅を出せるね。","hint2":"Aの900歩ぶん＝Bの960歩ぶんを使おう。最後はcmで表すよ。"}],"練習問題6":[{"title":"6(1)","hint1":"兄が30歩進む間に、弟は何歩進むかな。","hint2":"弟の先行25歩を足すと、兄30歩と同じ道のりになる。歩幅の比を出してから、同じ時間の3歩・5歩をかけよう。"},{"title":"6(2)","hint1":"兄の出会った後の60歩ぶんは、弟が出会う前に進んだ道のりだよ。","hint2":"(1)の歩幅の比で弟の歩数に直そう。出会うまでの距離を速さの比で分け、AB全体の弟の歩数へ広げよう。"}],"標準演習3":[{"title":"3(1)","hint1":"出会いまでのBの距離は、Aなら何歩ぶんかな。","hint2":"Aの160歩ぶんと80歩ぶんを、同じ時間に進んだ距離として比べよう。"},{"title":"3(2)","hint1":"Aは橋全体を何歩で渡るか、先に出そう。","hint2":"Aの歩幅を求め、A80歩ぶん＝B120歩ぶんからBの歩幅へ直そう。"}],"チャレンジ2":[{"title":"2(1)","hint1":"最初と2回目までに2人が進む道のりの和は、片道何本分かな。","hint2":"その時間の倍率をたつき君の1350歩に使おう。さらに90歩を足すと往復の歩数になるので、最初の出会いまでの距離を比べられるよ。"},{"title":"2(2)","hint1":"最初に出会うまで、たつき君が1350歩なら、あいなさんは何歩かな。","hint2":"あいなさんの歩幅で出会うまでの距離を出そう。(1)の比からたつき君の距離も求め、合わせよう。"}],"例題5・類題5":[{"title":"例題5(1)","hint1":"続く2台の間隔は、バスが15分で進む距離だね。","hint2":"その間隔を、あすかさんと次のバスが12分で合わせて進む図を描こう。あすかさんの12分の距離は、バスの何分ぶんかな。"},{"title":"例題5(2)","hint1":"バスの間隔を、比の速さと15分で表そう。","hint2":"同じ方向では、その間隔をバスと自転車の速さの差で割ろう。"},{"title":"類題5(1)","hint1":"電車どうしの間隔は、電車が20分で進む距離だよ。","hint2":"すれ違うまでの14分に、電車とオートバイが進む距離の和を対応させよう。"},{"title":"類題5(2)","hint1":"電車が20分で進む距離を使おう。","hint2":"同じ方向なので、電車とオートバイの速さの差でその間隔を割ろう。"}],"基本問題7":[{"title":"7(1)","hint1":"家からA駅まで、なお君は12分で歩くね。","hint2":"出会いまでになお君は2分歩いた。残った道のりを、電車はA駅から2分で進んだことに注目しよう。"},{"title":"7(2)","hint1":"A駅で一緒に出た電車は先へ進む。次の電車が出るまでに、なお君は何分歩くかな。","hint2":"次の電車が出る時点の先行距離を速さの差で割り、A駅を出てからの待ち時間も足そう。"}],"基本問題8":[{"title":"8(1)","hint1":"電車どうしの間隔は、電車が15分で進む距離だよ。","hint2":"その間隔を電車と自転車の速さの和で割ろう。時間の単位をそろえてね。"},{"title":"8(2)","hint1":"電車どうしの間隔は(1)と同じだよ。","hint2":"同じ方向では、電車と自転車の速さの差を使おう。"}],"基礎演習5":[{"title":"5(1)","hint1":"バスどうしの間隔は、バスが18分で進む距離だね。","hint2":"その間隔をゆかりさんとバスが15分で合わせて進む。ゆかりさんの15分の距離はバスの何分ぶんかな。"},{"title":"5(2)","hint1":"バスが18分で進む距離を、バスと徒歩の速さの差で割ろう。","hint2":"時速と分の単位をそろえよう。答えの分の端数は60倍して秒に直すよ。"}],"練習問題7":[{"title":"7(1)","hint1":"追い越されてから次に追い越されるまで、電車と車の距離の差は何に等しいかな。","hint2":"電車の20分ぶんの距離＝2つの速さの差×75分。車の75分の距離を、電車の何分ぶんかで表そう。"},{"title":"7(2)","hint1":"電車とバスの速さを3、2と置こう。","hint2":"電車の20分ぶんの間隔を、反対方向に進む2つの速さの和で割ろう。"}],"標準演習4":[{"title":"4(1)","hint1":"電車＋Aの速さと電車＋Bの速さは、出会う時間の逆比になるよ。","hint2":"2つの和の差はB−A。A：B＝3：5の差とそろえ、共通の電車の速さを取り出そう。"},{"title":"4(2)","hint1":"比の速さで、電車どうしの間隔を「電車＋B」と9分から表そう。","hint2":"同じ方向になったら、その間隔を「電車−B」の速さで割ろう。"}],"チャレンジ3":[{"title":"3(1)","hint1":"追い越しでは「電車−人」、すれ違いでは「電車＋人」の速さを使うね。","hint2":"2つの速さの比は16分と14分の逆比。その差は人の速さ2人ぶんだから、分速60mに結びつけよう。最後に時速kmへ直そう。"},{"title":"3(2)","hint1":"電車どうしの距離の間隔を、追い越し・すれ違いのどちらかで求めよう。","hint2":"その距離を電車だけの速さで割ると、発車する時間の間隔になる。分の端数は秒に直そう。"}],"例題6・類題6":[{"title":"例題6(1)","hint1":"多く回転する歯車ほど、歯数は多いかな、少ないかな。","hint2":"15：24：10の逆比を作り、整数の比に直そう。"},{"title":"例題6(2)","hint1":"求めた歯数の比から、AとCだけを取り出そう。","hint2":"Cの比の数を60に合わせ、同じ倍率でAを求めよう。"},{"title":"類題6(1)","hint1":"3つとも、同じ時間に通過する歯の数が等しいよ。","hint2":"36、60、45それぞれの逆数で比を作り、整数にそろえよう。"},{"title":"類題6(2)","hint1":"BとCの歯数の比を取り出そう。","hint2":"Cの比の数に48を対応させて、Bの歯数を求めよう。"}],"基本問題9":[{"title":"9(1)","hint1":"同じ時間にAは5回転、Bは3回転するね。","hint2":"回転数の比を逆にして、歯数の比にしよう。"},{"title":"9(2)","hint1":"BとCの歯数の比も、回転数の逆比で作ろう。","hint2":"A：BとB：Cで、Bの数をそろえてつなごう。"},{"title":"9(3)","hint1":"(2)からAとCの歯数の比を取り出そう。","hint2":"Aの比の数に45を合わせ、Cにも同じ倍率をかけよう。"}],"基礎演習6":[{"title":"6(1)","hint1":"A：BとA：Cの回転数から、歯数の比をそれぞれ作ろう。","hint2":"逆比にした後、共通のAの数をそろえて3つをつなごう。"},{"title":"6(2)","hint1":"歯数の比のうち、AとCに注目しよう。","hint2":"Cの比の数に24を対応させ、Aを求めよう。"},{"title":"6(3)","hint1":"BとCの回転数の比は、歯数の比の逆だね。","hint2":"Bの回転数を15に合わせて、Cの回転数へ広げよう。"}],"練習問題8":[{"title":"8(1)","hint1":"AとBの歯数から、Bの回転数を求めよう。","hint2":"BとCは同じ軸なので、CはBと同じだけ回るよ。"},{"title":"8(2)","hint1":"Aが15回転する間のBの回転数を求め、それをCにも使おう。","hint2":"CとDについて「歯数×回転数が等しい」を使えば、Cの歯数が求められるよ。"}],"標準演習6":[{"title":"6","hint1":"Aが1回転する間、Cを通過する歯の数はいくつかな。","hint2":"BはCと同じ回転数で、歯数は2倍。Bを通過する歯の数を出し、Dの6回転ぶんの歯数と結ぼう。"}],"練習問題9":[{"title":"9(1)","hint1":"2つの通過距離を図にすると、共通の列車140mが見えるよ。","hint2":"時間の差で進む距離は、鉄橋何本分かな。そこから鉄橋だけの通過時間を出し、32秒のうち列車140mぶんの時間を見つけよう。"},{"title":"9(2)","hint1":"各列車の「速さ×時間」の比を作ろう。","hint2":"通過距離の差は、列車の長さの差と同じ。比の差にその長さを当てはめ、急行の通過距離を45秒で割ろう。"}],"標準演習7":[{"title":"7(1)","hint1":"トンネル通過と鉄橋通過の距離の差は、鉄橋何本分かな。","hint2":"時間の差から鉄橋1本ぶんの時間を出そう。9秒の残りが列車120mぶんの時間なので、速さを求めてトンネルへつなごう。"},{"title":"7(2)","hint1":"Bの通過時間を、Aと同じ速さだったときの時間に直そう。","hint2":"同じ速さにそろえた通過時間の差は、列車の長さの差ぶん。速さを出し、Aの27秒の通過距離から列車の長さを引こう。"}]},"6u-10":{"基本問題1":[{"title":"1　直角三角形の中の正方形","hint1":"三角形ABCとFECの対応する角を探そう。","hint2":"FEとEBが同じ長さだよ。FE：ECを相似から求め、BCをその比で分けよう。"}],"基本問題2":[{"title":"2　直角三角形と相似","hint1":"直角と共通の角に印をつけよう。","hint2":"三角形ABDとBCDを比べよう。DA：AB＝DB：BCを使えるね。"}],"基本問題3":[{"title":"3　台形の中の相似","hint1":"Aを通ってCDと平行な線を引こう。EFのうち、ADと同じ長さの部分を分けられるよ。","hint2":"（1）残りの部分はAE：ABに合わせて増える。（2）上下の平行な辺の和と、対応する高さの比を使って面積を比べよう。"}],"基本問題4":[{"title":"4　正六角形の面積","hint1":"中心と頂点を結ぶと、等しい正三角形6個になるよ。","hint2":"図1は左の頂点を同じ高さの位置に移して考えよう。図2は上の頂点から線を引き、3つの三角形に分けて比べよう。"}],"基本問題5":[{"title":"5　三角形の面積と比","hint1":"（1）ADFとBDFは底辺AD・DBで比べよう。ABFとBCFはAE＝ECに注目。","hint2":"（2）BCFとBDFを比べると、底辺CFとFDの比がわかるよ。"}],"基礎演習1":[{"title":"1　三角形の面積と辺の比","hint1":"（1）底辺AE・EC、（2）底辺BD・DCを使って順に面積を分けよう。","hint2":"（3）三角形ABEとDBEは、共通部分を使って比べるとAF：FDと同じ比になるよ。"}],"練習問題1":[{"title":"1　正六角形と相似","hint1":"ABとDCを延ばして交点Jを作ると、JBCとJGHが相似になるよ。","hint2":"（1）大きい三角形から小さい三角形を引く。（2）BIGは正三角形。BCHIと高さをそろえて比べる。（3）BCHIとHDEIは、平行な辺の和を比べよう。"}],"練習問題2":[{"title":"2　正方形の中の長方形と相似","hint1":"（1）BAHとHDGの相似を使おう。（2）求める長方形の半分は三角形FGHだよ。","hint2":"（2）HDGとGCFからCFを求めよう。台形FCDHから三角形HDGとGCFを引き、その面積を2倍しよう。"}],"練習問題3":[{"title":"3　三角形の面積と辺の比","hint1":"（1）ABFとACFは同じ面積。ACFとBCFはAD：DBで比べよう。","hint2":"（2）AF：FHは、ABF＋ACFとBCFの面積比。同様にAG：GHを求め、AHからAFとAGを出して引こう。"}],"標準演習1":[{"title":"1　三角形の中の長方形","hint1":"頂点A側の小さい三角形とABCを比べよう。高さの全体は3cm、底辺の全体は8cmだよ。","hint2":"（1）正方形の縦と横を同じ□にする。（2）AP：ABで小さい三角形の高さと底辺を求め、残りの高さとの積で長方形の面積を出そう。"}],"標準演習2":[{"title":"2　正六角形の面積","hint1":"図と解答に合わせ、Gは辺BCの真ん中として考えよう。本文の「CD」と図の位置が一致していないよ。","hint2":"（1）ABGはABCの半分。（2）CDEGをCDEとCEGに分ける。CEGはBCEの半分だよ。"}],"チャレンジ1":[{"title":"1　正六角形の面積比","hint1":"（1）六角形の右半分からAGIとIFEHを引こう。FEとIHを延ばすと、IFEHの面積を相似で調べられるよ。","hint2":"（2）GCHとGIHの面積比からCJ：JIを、GCIとHCIからGJ：JHを出そう。GCJとIJHの面積比は、この2つの線分比をかけると求められるよ。"}],"チャレンジ2":[{"title":"2　正三角形の面積比","hint1":"（1）GCJを先に求め、底辺GI：GCで分けよう。（2）LGJとIGJはLM：MIで比べられるよ。","hint2":"（3）全体からAFL・BGF・GCJ・ICLを引き、さらにGIMを引こう。GIMはGILを（2）の比で分けて求めよう。"}],"チャレンジ3":[{"title":"3　三角形の辺と面積","hint1":"（1）BDGからDCG、BCGからABGへ、同じ高さの三角形をたどろう。","hint2":"（2）ABDから全体へ。（3）AIF・CEHもBDGと同じように調べよう。全体から、外側の大きい三角形ABG・BCH・CAIを引くと中央が残るね。"}],"基本問題6":[{"title":"6　折り返した角度","hint1":"OA・OC・ACの長さに注目すると、三角形OACはどんな形かな？","hint2":"折り目ADは角OACを2等分するよ。三角形OADの内角の和を使おう。"}],"基本問題7":[{"title":"7　折り返しと相似","hint1":"ABFとDFEの直角以外の角を比べよう。","hint2":"対応する辺からAF：DE＝AB：DF。DFはADからAFを引いて求めよう。"}],"基本問題8":[{"title":"8　太陽光と木の影","hint1":"棒の高さと影の比を使おう。木のてっぺんから、かべの影の高さまでを考えるよ。","hint2":"地面の7.2mに対応する高さを求めてから、かべにうつった高さを足そう。"}],"基本問題9":[{"title":"9　街灯から遠ざかる人","hint1":"街灯の高さと身長の比から、大きい三角形と小さい三角形を比べよう。","hint2":"「街灯から人まで：影の長さ」は「街灯の高さ−身長：身長」。人が歩いた距離を出して時間に直そう。"}],"基本問題10":[{"title":"10　街灯による影と面積","hint1":"（1）街灯の高さと身長は、ACとBCに対応するよ。","hint2":"（2）真上から見た三角形ABDとACEが相似だね。大きい三角形から小さい三角形を引くか、影の四角形を台形として求めよう。"}],"基礎演習2":[{"title":"2　正五角形の線対称","hint1":"（1）頂点と向かいの辺の真ん中を結んでみよう。","hint2":"（2）（3）折り目の上の点は動かないね。辺の両端がそれぞれどこへ移るか調べよう。"}],"基礎演習3":[{"title":"3　太陽光と影の比","hint1":"（1）棒の長さも影もcmに直して比を作ろう。","hint2":"（2）（3）どちらも「高さ：影」は同じ。わかっている方の長さから、もう一方を求めよう。"}],"練習問題4":[{"title":"4　折り返しと辺の長さ","hint1":"（1）GABとGFHの相似を探そう。ABとFHの比からBGが出せるよ。","hint2":"（2）BF＝BCを使ってGFを出し、相似からAGへ。（3）ADからAGとGHを引いてDHを出し、DHEとGFHを比べよう。"}],"練習問題5":[{"title":"5　街灯と影の速さ","hint1":"（1）同じ時間に進んだ距離の比は速さの比。街灯からの距離の比と高さの比を対応させよう。","hint2":"（2）3秒後、影の長さは人が3秒で歩いた距離だね。相似で街灯までの残りの距離を求め、歩く速さで割ろう。"}],"練習問題6":[{"title":"6　かべにうつる影","hint1":"かべの長方形から、高さと地面の影の比を求めよう。","hint2":"（1）三角形の高さに対応する影を求める。（2）かべまでの30cmで光が何cm下がるかを出そう。かべにうつる小さい三角形は、元の三角形と相似だよ。"}],"練習問題7":[{"title":"7　立体がつくる影","hint1":"（1）上面の正方形が地面で何倍になるかを、横から見た三角形で考えよう。","hint2":"（1）大きな影から底面を引く。（2）影と底面を合わせた面積を上面と比べ、長さの比に戻そう。光源から上面までと地面までの差は立体の高さだね。"}],"標準演習3":[{"title":"3　街灯と人の影","hint1":"街灯と人の身長から、大きい三角形と小さい三角形の比を求めよう。","hint2":"（1）全体のBCからECの分を引いてBEの比にする。（2）（3）は同じBE：ECを使おう。"}],"チャレンジ4":[{"title":"4　折り返しと面積","hint1":"三角形BCEとBFEは同じ面積だよ。元の正方形はアとイ何個分になるかな？","hint2":"正方形全体からイの面積を求めよう。BF＝BCを底辺にすれば、高さEFが出せるね。"}],"チャレンジ5":[{"title":"5　2人の影が重なる時間","hint1":"（1）Bが出発するまでのAの先行距離を考えよう。（2）影の先端が重なった瞬間の2人の位置を図にしよう。","hint2":"（2）先端から2人までの距離は身長の比。（3）「Bの影の先端がAの足元に来る時」と「Bの足元がAの影の先端に来る時」を別々に求め、時間の差を取ろう。"}],"チャレンジ6":[{"title":"6　立方体がつくる影","hint1":"豆電球と上面の頂点を結び、アの面や地面まで延ばそう。横から見た三角形で位置を求められるよ。","hint2":"（1）IJKから光が当たる小三角形を引く。（2）上面ACDの影と、高さ3cmの面の影を重ねて描こう。底面を除いた部分を三角形に分けよう。"}],"基本問題11":[{"title":"11　速さ・時間・道のりの比","hint1":"（1）同じ道のりにかかる時間を逆比にしよう。","hint2":"（2）それぞれの速さの比に、それぞれが進む時間をかけて比べよう。"}],"基本問題12":[{"title":"12　かけっこのゴール差","hint1":"Aがゴールした瞬間の、2人が進んだ距離を比べよう。","hint2":"100mにかかる時間は速さの逆比。Aの時間からBの時間を求め、差を取ろう。"}],"基本問題13":[{"title":"13　速さと時間の比","hint1":"（1）出会いまでの2人の距離を比べよう。（2）先に出た4分も加えて考えよう。","hint2":"（2）同じ場所までにかかった2人の時間を出し、逆比にしよう。答える人の順序にも注意。"}],"基礎演習4":[{"title":"4　速さの変化と道のり","hint1":"ABとBCの道のりを②、③として、かかる時間の比を作ろう。","hint2":"（1）14分をその時間比で分ける。（2）時間に各区間の速さをかけ、距離を足そう。"}],"基礎演習5":[{"title":"5　かけっこの差","hint1":"Aが200m進む間に、Bは何m進んでいるかな？","hint2":"次にBが200m進む間のAの距離を比で求めよう。200mを超える分が、後ろに下がる距離だよ。"}],"練習問題8":[{"title":"8　兄弟のかけっこ","hint1":"（1）同時に進んだ距離を比べる。（2）2回目は走る距離が違うので、それぞれ「距離÷速さの比」で時間を表そう。","hint2":"（2）時間の差が0.45秒になるように比の1を求める。（3）弟が100m走る間に兄が走る距離を求め、100mとの差を取ろう。"}],"練習問題9":[{"title":"9　家と駅の往復","hint1":"2回目に出会うまでの合計距離は、1回目までの3倍だよ。","hint2":"（1）出発から2回目までの時間に速さの差をかける。（2）兄と弟それぞれの道すじを線分図にし、距離の差を使って家から駅までを求めよう。"}],"標準演習4":[{"title":"4　時間の差と追いつき","hint1":"（1）妹が先に歩いた4分を、妹の時間に足して比べよう。","hint2":"（2）妹が6分で進む距離を比の数で表し、2人の速さの差で割ろう。"}],"標準演習5":[{"title":"5　速さと到着時刻","hint1":"ゆっくり歩いた日は、早く出た分と到着が遅くなった分だけ長く歩いているよ。","hint2":"速さの逆比で時間比を作り、時間差から普段の時間を出そう。（1）は普段の到着と始業の差、（2）はその日の速さ×時間を使おう。"}],"チャレンジ7":[{"title":"7　3人のかけっこ","hint1":"（1）6分間のBの距離から速さを出そう。（2）1分45秒の時点でA・B・Cを順に並べて位置を確かめよう。","hint2":"（3）速さの差で90m離れるまでの時間を出す。その時の残り距離を1.4倍の速さで割り、Bのゴール時刻から走った時間を引こう。"}],"チャレンジ8":[{"title":"8　橋を渡る速さと時間","hint1":"（1）橋を12等分して、最初の日の2人の距離を数えよう。（2）翌日は真ん中で出会うので2人の速さが等しいね。","hint2":"（2）兄の減速9mを比の差に当てる。（3）両日の速さの和を比べ、出会うまでの時間の差12秒を使って橋の長さを求めよう。"}],"チャレンジ9":[{"title":"9　山道の上りと下り","hint1":"まず2人の所要時間から休けい1時間を除こう。同じ区間の上りと下りの時間は3：2だよ。","hint2":"2人の歩行時間の差は、長い側と短い側の「上り時間の差」の3分の1。そこから山頂到着時刻の差を出し、休けい時間との重なりを求めよう。"}],"基本問題14":[{"title":"14　往復して出会う旅人","hint1":"（1）1回目と2回目の出会いまでに、2人が合わせて進む道のりを線分図にしよう。","hint2":"（2）全体を速さの比の和で区切り、2回目の位置を折り返して図に戻そう。出会った2地点の差が360mだよ。"}],"基本問題15":[{"title":"15　周回する兄と弟","hint1":"1周を1として、2人の1分分を表そう。","hint2":"（1）は速さの和。（2）は弟が先に進んだ10分分を、速さの差で割ろう。"}],"基本問題16":[{"title":"16　歩数と歩はば","hint1":"（1）同じ時間の歩数の比を使おう。（2）Aが1分に進む距離を出そう。","hint2":"Aの1分の距離を歩数で割ると歩はばになるよ。同じ距離に必要な歩数は、歩はばの逆比だね。"}],"基本問題17":[{"title":"17　等間隔に発車する電車","hint1":"電車と電車の間隔は「電車の速さ×12分」。自転車は、その間隔を電車と近づく速さで10分かけて進むよ。","hint2":"（1）電車の12分分＝電車と自転車の10分分として比べる。（2）同じ間隔を、電車と自転車の速さの差で割ろう。"}],"基本問題18":[{"title":"18　歯車の回転数","hint1":"（1）同じ1分間の回転数にそろえて比べよう。","hint2":"（2）かみ合う歯の数は同じ。歯が多いほど回転数は少なくなるよ。"}],"基礎演習6":[{"title":"6　池の周りの出会い・追いつき","hint1":"1周を1として、2人の速さを書こう。","hint2":"（1）速さの差で1周分を縮める。（2）弟が6分で進んだ分を1周から引き、残りを速さの和で割ろう。"}],"基礎演習7":[{"title":"7　歩数と歩はば","hint1":"（1）同じ距離の歩数から歩はばの比を出し、同じ時間の歩数の比をかけよう。","hint2":"（2）姉が3歩、妹が2歩進む間に縮まる距離を、妹の歩はばで表そう。先行した30歩分を縮める組数を求めよう。"}],"基礎演習8":[{"title":"8　等間隔に発車する電車","hint1":"電車の間隔を、電車の15分分で表そう。","hint2":"（1）その間隔を「電車−人」の速さで割る。（2）同じ間隔を8分で進むのは「電車＋バス」。電車の速さを比の数で置いて考えよう。"}],"練習問題10":[{"title":"10　周回する2人","hint1":"（1）Bの4分分がAの3分分に当たるよ。（2）2回目の出会いでは、合計距離が最初より1周多いね。","hint2":"2回目に出会うまでのAの距離に384mを足すと1周。これを2人の合計距離の式と比べて時間を出し、（3）の1周へ進もう。"}],"練習問題11":[{"title":"11　出会いと歩はば","hint1":"兄の行き1800歩と、引き返した200歩の時間を比にしよう。弟は出会う前後の距離を比べよう。","hint2":"兄が家を出てからの4分を、出会う前と後に分けよう。弟の時間比と合わせて兄の最初の時間を出す。（2）は同じ時間に進む距離から歩はばを求めよう。"}],"標準演習6":[{"title":"6　池を周回する3人","hint1":"BとCの速さを④、③として、20分で2人の間にできる差を表そう。","hint2":"その差を次の4分間にAとCで縮めるよ。Aの速さが出たら、A＋Bの20分分が1周になることを使おう。"}],"標準演習7":[{"title":"7　出会いと歩数","hint1":"（1）同じ距離の歩数から歩はばの比を出し、同じ時間の歩数をかけよう。","hint2":"（2）全体420歩分を速さの比で分けよう。妹が歩いた距離を、妹の歩はばの単位へ直そう。"}],"チャレンジ10":[{"title":"10　池を周回する3人の速さ","hint1":"B：Cは、同じ距離の時間を逆比にして求めよう。","hint2":"B＋Cの2分分と、A−Bの15分分が、同じ1周だよ。BとCを比の数に置いてAを求めよう。"}],"チャレンジ11":[{"title":"11　電車とトンネル","hint1":"Aの速さを④、Bを⑤とすると、通過中の距離はそれぞれ何になるかな？","hint2":"Aの50秒分から100mを引くとP。これを2倍した長さは、Bの74秒分から80mを引いたQと同じだよ。"}],"チャレンジ12":[{"title":"12　兄弟の周回と歩数","hint1":"1周は兄の何歩分かな？ 追いついたとき、弟の距離は兄の距離より1周短いよ。","hint2":"（1）同じ時間の距離を比べる。（2）最初の出会いでは、弟の総距離は兄の200歩分。そこから先行50歩分を除いた距離と兄280歩分を比べ、歩はばの比を求めよう。"}],"チャレンジ13":[{"title":"13　バスとの出会いと追いこし","hint1":"同じ間隔を縮める時間は、追いこし9分とすれ違い6分45秒だよ。","hint2":"時間を逆比にすると「バス−太郎」と「バス＋太郎」の比になる。その差は太郎の速さ2人分だね。"}]},"6u-11":{"例題1・類題1":[{"title":"例題1 1　上り・下り","hint1":"流れは船を助けるかな、じゃまするかな。上りと下りの速さを別々に書こう。","hint2":"時間を求めるときは、進む向きに合う速さで道のりを割ろう。"},{"title":"類題1 1　上り・下り","hint1":"静水時の速さに、流れを足す場合と引く場合を書こう。","hint2":"下る時間は、道のり÷下る速さ。時間の小数部分は60倍して分に直そう。"}],"基本問題1":[{"title":"1　上る距離・下る時間","hint1":"3時間45分を時間の単位に直し、上る速さをかけよう。","hint2":"帰りは同じ距離を、下る速さで割るよ。"}],"基本問題2":[{"title":"2　往復時間と流れ","hint1":"往復それぞれの速さを、60kmと各時間から出そう。","hint2":"下り−上りには流れが2つ分あるよ。"}],"基礎演習1":[{"title":"1　上りと下り","hint1":"静水時から流れを引けば上り、足せば下りだよ。","hint2":"同じ960mを、それぞれの速さで割ろう。分速なら答えの時間は分になるよ。"}],"例題2・類題2":[{"title":"例題2 2　往復のグラフ","hint1":"（1）（2）行きと帰りの時間を読み、上りと下りの速さを求めよう。平均が静水時、差の半分が流れだよ。","hint2":"（3）向かい合うときは速さの和。（4）折り返した時点の2そうの間隔を求め、下る速さの差で割ろう。「折り返してから」の時間だよ。"},{"title":"類題2 2　往復と出会い","hint1":"（1）同じ道のりを行きと帰りの時間でそれぞれ割ろう。2つの速さの平均が静水時だよ。","hint2":"（2）一方は上り、もう一方は下り。2そうが1時間に近づく距離を求めてから、全体の距離を割ろう。"}],"基本問題3":[{"title":"3　2そうの出会い","hint1":"Pの上る速さを距離と時間から出す。静水時との差が流れだよ。","hint2":"Qの下る速さを作ろう。Qの到着は距離÷Qの速さ、出会いは距離÷2そうの速さの和だよ。"}],"基本問題4":[{"title":"4　船といかだ","hint1":"グラフの上り・下りの時間から2つの速さを求め、静水時と流れを出そう。","hint2":"いかだと上る船が近づく速さは2つの速さの和。出会うまでの時間×流れが、いかだの進んだ距離だよ。"}],"基礎演習2":[{"title":"2　グラフと追いつき","hint1":"遅い方が上り。各区間の時間から速さを出し、平均と差の半分を求めよう。","hint2":"出会いは速さの和。追いつきは船が折り返した時点の間隔÷速さの差。「折り返してから」何時間かを答えよう。"}],"練習問題1":[{"title":"1　船Pと船Qのグラフ","hint1":"Pの往復から静水時と流れを求めよう。","hint2":"出会った時刻は、Pの上る全時間から出会い後の時間を引く。Qの全所要時間も求めて、下る速さから流れを引こう。"}],"練習問題2":[{"title":"2　逆向きの船","hint1":"一方は流れを足し、他方は引く。2そうの速さを足すと、流れはどうなるかな。","hint2":"先に出会う時間を求める。出会う場所までの距離÷時間で、一方の実際の速さを出そう。"}],"練習問題3":[{"title":"3　2度目の出会い","hint1":"1回目の出会いは静水時の速さ2つ分で近づく。片方が端まで着く時間から下りの速さも求めよう。","hint2":"遅い方が折り返した瞬間、もう一方はどこにいるかな。そのときの間隔÷速さの和を、折り返した時刻に足そう。"}],"標準演習3":[{"title":"3　2そうの往復グラフ","hint1":"Aの往復から流れを出し、Bの下りと上りの速さを作ろう。","hint2":"2回目はAが折り返した時点のBの位置を調べる。間隔÷近づく速さで求めた時間に、Aの下る速さをかけるとQからの距離になるよ。"}],"例題3・類題3":[{"title":"例題3 3　流れが変わる往復","hint1":"（1）往復時間の逆比で上り・下りの速さを表そう。その平均が静水時の速さだよ。","hint2":"（2）上りと下りの速さの差は、行きの流れ＋帰りの流れ。流れが変わるので、差を単純に2で割らないでね。"},{"title":"類題3 3　流れが変わる往復","hint1":"（1）上りと下りの速さを比で表し、平均が静水時の速さになることを使おう。","hint2":"（2）先に各方向の実際の速さを求める。その差を、行きと帰りの流れの比に分けてね。"}],"基本問題5":[{"title":"5　往復時間の比","hint1":"下りと上りの時間の逆比を作ろう。","hint2":"比の差が流れ2つ分。比の1あたりを求め、静水時は平均、距離は速さ×時間で出そう。"}],"基本問題6":[{"title":"6　帰りの流れが変わる","hint1":"まず48kmを各時間で割り、下りと上りの速さを求めよう。","hint2":"速さの差は行きの流れ＋帰りの流れ。「帰りは行きの2/3」を使って分けよう。"}],"基礎演習3":[{"title":"3　流れが弱くなる","hint1":"往復時間の逆比で速さを表し、その差を流れ2つ分に当てはめよう。","hint2":"距離と静水時の速さはそのまま。変わった流れで上る速さを作り直そう。"}],"練習問題6":[{"title":"6　往復の比と距離","hint1":"上り：下りの比の差が流れ2つ分に当たるよ。","hint2":"往復の合計時間を速さの逆比に分け、一方の速さ×時間で距離を出そう。"}],"練習問題7":[{"title":"7　兄弟のボート","hint1":"同じ道のりを進む時間の逆比から、兄の下り・兄の上り・弟の上りを共通の比で表そう。","hint2":"兄の上り下りの差から流れを出す。各人の静水時を求め、弟の下りや2人が近づく速さを作ろう。"}],"標準演習1":[{"title":"1　静水時の速さも変わる","hint1":"行き帰りの静水時の速さを5：2、実際の上り下りを時間の逆比で表そう。","hint2":"上りには流れを足すと静水時、下りから流れを引くと静水時になる。同じ流れの大きさを使って2つの比を合わせよう。"}],"標準演習4":[{"title":"4　同じ川を進む2そうの船","hint1":"PとQそれぞれについて、上り下りの比から静水時と流れの比を出そう。","hint2":"2そうに共通なのは川の流れの速さ。その比の数をそろえて、Pの下りとQの上りを同じ単位の比にする。速さの和を距離÷出会う時間と結びつけよう。"}],"例題4・類題4":[{"title":"例題4 4　故障して流される","hint1":"故障しなかった場合の上る時間を出し、実際の時間との差を求めよう。","hint2":"余分な時間は「流された時間＋その距離を上り直す時間」。2つの時間は流れの速さと上る速さの逆比になるよ。"},{"title":"類題4 4　故障による遅れ","hint1":"まず、故障しないときの上る時間を求めよう。実際との差が余分な時間だよ。","hint2":"余分な時間を「流される」「上り直す」に分ける。同じ距離なので時間の比は速さの逆比だよ。"}],"基本問題7":[{"title":"7　故障してから上り直す","hint1":"往復の速さから流れを求めよう。故障中は流れの速さで下るよ。","hint2":"全時間は通常の上る時間＋故障時間＋流された距離を上り直す時間だよ。"}],"基本問題8":[{"title":"8　流された時間","hint1":"故障しなければ何分で上れるかな。実際との差を求めよう。","hint2":"その差を、流される時間と上り直す時間に分ける。2つの時間の比は流れ：上りの逆比だよ。"}],"基礎演習4":[{"title":"4　故障の時間","hint1":"通常の上る時間を先に求めよう。","hint2":"遅れ35分は、流された時間と戻る時間の合計。2つの時間を速さの逆比に分けよう。"}],"練習問題4":[{"title":"4　流されながら下る","hint1":"通常の往復時間から静水時と流れを求めよう。","hint2":"全時間ずっと流されたと仮定する。足りない距離を、エンジンを使うと1時間あたり増える距離で割ろう。"}],"練習問題5":[{"title":"5　途中でエンジンを止める","hint1":"まず通常の出会いを、2そうの速さの和で考えよう。","hint2":"（2）10分後の間隔を出す。その後は2そうとも下流向きなので、下る船と流される船の速さの差で間隔を割ろう。"}],"標準演習2":[{"title":"2　故障して遅れる","hint1":"上りの実際の速さを出し、静水時との差を流れにしよう。","hint2":"通常の上る時間に、故障30分と、その間に流された距離を上り直す時間を足そう。"}],"標準演習5":[{"title":"5　流される区間のグラフ","hint1":"ACを上る時間と、同じ距離を流される時間を比べよう。","hint2":"上り＋流れが静水時。そのあとCB往復の時間を上り下りの逆比に分け、ACを上った時間を足そう。"}],"チャレンジ1":[{"title":"1　浮き輪と往復する船","hint1":"通常の往復時間の逆比から、静水時と流れの速さを求めよう。","hint2":"船がCから浮き輪との出会いの場所まで進んだ距離を、浮き輪は流れの速さでCまで戻る。その時間から船の往復全時間を求め、上り下りに分けよう。"}],"例題5・類題5":[{"title":"例題5 5　エスカレーター","hint1":"立ったままと歩いたときの時間から、「機械」と「機械＋歩く」の速さの比を作ろう。","hint2":"比の差が歩く速さだよ。機械の速さと全段数が分かったら、（2）は新しい歩く速さを機械に足そう。"},{"title":"類題5 5　動く歩道","hint1":"立ったままと歩く場合の時間の逆比を作り、その差を毎秒の歩数と結びつけよう。","hint2":"（1）止まった歩道の長さを歩数で表す。（2）新しい歩く速さに機械の速さを足し、全体の長さを割ろう。"}],"基本問題9":[{"title":"9　階段の全段数","hint1":"立ったままと毎秒1段歩く場合の速さの比を、時間から求めよう。","hint2":"比の差が毎秒1段。全段数を出したら、毎秒2段歩く場合は機械の速さに2を足そう。"}],"基礎演習5":[{"title":"5　歩く速さと機械","hint1":"「機械＋歩く」と「機械」の速さを時間の逆比にしよう。","hint2":"比の差が毎秒3段。機械の速さが分かったら、立って乗る時間をかけて全段数を出そう。"}],"練習問題8":[{"title":"8　歩く速さを変える","hint1":"立つ場合と歩く場合の速さの比を作り、差を歩く速さとしよう。","hint2":"1.5倍するのは歩く速さだけ。機械の速さを足し直して、同じ長さを割ろう。"}],"練習問題9":[{"title":"9　階段上で出会う","hint1":"全段数からAが歩いた段数を引くと、機械が運んだ段数になるよ。","hint2":"Aは「機械＋歩く」、Bは機械の速さ。出会うまでにAが進む割合を速さの比で求めよう。"}],"標準演習6":[{"title":"6　速さを上げる歩道","hint1":"立つ場合と歩く場合の時間から、歩く速さ：機械の速さを出そう。","hint2":"目標時間から必要な「機械＋歩く」の速さを求める。機械の分を引いてから、もとの歩く速さと比べよう。"}],"チャレンジ2":[{"title":"2　歩幅と歩数","hint1":"歩幅だけでは速さを比べられないよ。同じ時間に進む長さを2人分出そう。","hint2":"止まった歩道での歩数−動く歩道で歩いた歩数が、機械が運んだ距離に当たる。兄・弟・機械の速さを同じ比にそろえ、到着時間の差を使おう。"}]},"6u-12":{"例題1・類題1":[{"title":"例題1 1　三角形の回転","hint1":"動く頂点と回転の中心を結ぼう。その長さが弧の半径。回転角も書き込もう。","hint2":"辺や図形が通る部分は、外側のおうぎ形・内側のおうぎ形・もとの三角形に分ける。等しい三角形を移すと、足す部分と引く部分がそろうよ。"},{"title":"類題1 1　三角形の回転","hint1":"動く頂点と回転の中心を結ぼう。その長さが弧の半径。回転角も書き込もう。","hint2":"辺や図形が通る部分は、外側のおうぎ形・内側のおうぎ形・もとの三角形に分ける。等しい三角形を移すと、足す部分と引く部分がそろうよ。"}],"基本問題1":[{"title":"1　三角形の回転","hint1":"頂点の道すじは、中心から頂点までの長さを半径とする弧だよ。","hint2":"図形全体が通った部分と、1本の辺が通った部分は違う。前者はもとの三角形も含め、後者は内側のおうぎ形を引く形に整理しよう。"}],"基本問題2":[{"title":"2　周りの長さと面積","hint1":"周りを指で1周なぞり、2本の弧と直線部分を色分けしよう。","hint2":"2本の弧は半径が違うが回転角は同じ。面積は外側と内側のおうぎ形の差として考えよう。"}],"基礎演習1":[{"title":"1　三角形の回転","hint1":"頂点が描く弧と、中心から頂点までの辺が通るおうぎ形を区別しよう。","hint2":"三角形全体なら、もとの三角形を足す。中心につながっていない辺なら、内側に残る部分を引く形にしよう。"}],"基礎演習2":[{"title":"2　通った範囲の面積","hint1":"回転前と回転後の三角形は同じ面積だよ。","hint2":"はみ出した三角形を、同じ形の欠けた部分へ移してみよう。1つのおうぎ形として面積を求められるよ。"}],"練習問題1":[{"title":"1　回転角と通過面積","hint1":"回転角を含む三角形で、外角と内角の関係を使おう。","hint2":"図形が新しく通った部分は、同じ面積の三角形を移すとおうぎ形に整理できるよ。"}],"練習問題2":[{"title":"2　直角二等辺三角形","hint1":"直角二等辺三角形の残りの角を使って、回った角を求めよう。","hint2":"図形の境界を描き、外側のおうぎ形から内側のおうぎ形を引こう。2つの角度はそれぞれ確かめてね。"}],"練習問題4":[{"title":"4　三角形の通過範囲","hint1":"1点の周りは360度。図の直角や示された角を使って回転角を探そう。","hint2":"三角形とおうぎ形に分けて面積を足そう。どちらも重複せずに数えているか確認してね。"}],"標準演習1":[{"title":"1　周りの長さから角度","hint1":"周りの長さから2本の直線部分を引き、弧だけの合計を出そう。","hint2":"2本の弧は回転角が同じ。半径2つの和で作った円周の、何分のいくつかを求めよう。"}],"例題2・類題2":[{"title":"例題2 2　長方形の回転","hint1":"回る前と後の同じ辺に注目しよう。回転角は図に書かれた角そのものとは限らないよ。","hint2":"頂点の道すじは中心からその頂点までを半径とする弧。辺が通る面積は、同じ角度のおうぎ形の差になるよう等しい三角形を移そう。"},{"title":"類題2 2　長方形の回転","hint1":"回る前と後の同じ辺に注目しよう。回転角は図に書かれた角そのものとは限らないよ。","hint2":"頂点の道すじは中心からその頂点までを半径とする弧。辺が通る面積は、同じ角度のおうぎ形の差になるよう等しい三角形を移そう。"}],"基本問題3":[{"title":"3　長方形の頂点と辺","hint1":"各小問で動く頂点・辺が違うよ。中心からの距離を、その都度確認しよう。","hint2":"図形全体が通る場合はもとの図形も足す。辺が通る場合は、両端の弧と辺で囲まれる部分を描き、三角形を移しておうぎ形の差にしよう。"}],"基本問題4":[{"title":"4　回転角を求める","hint1":"まず図の三角形の残りの角を180度から求めよう。","hint2":"その角と示された角を使って回転角を出す。長さは弧、面積は半径の異なるおうぎ形の差だよ。"}],"基礎演習3":[{"title":"3　回転角と面積","hint1":"直角から図の角を引いて回転角を求めよう。","hint2":"頂点の道すじには対角線を半径として使う。図形全体の通過面積は、もとの長方形とおうぎ形に分けよう。"}],"練習問題3":[{"title":"3　回転でできるすき間","hint1":"すき間を含む大きなおうぎ形を描こう。","hint2":"そこから2つの直角三角形を引く。片方の辺は長方形の2辺の差から出せるよ。"}],"標準演習2":[{"title":"2　長方形とすき間","hint1":"示された弧の長さを、その半径の円周で割ろう。","hint2":"面積は対角線を半径にするおうぎ形から、長方形の半分に当たる三角形を引こう。"}],"標準演習3":[{"title":"3　正方形の辺の通過","hint1":"回転の中心につながる辺と、つながらない辺では通る形が違うよ。","hint2":"後者はおうぎ形の差に整理する。対角線×対角線は正方形の面積の2倍だよ。"}],"例題3・類題3":[{"title":"例題3 3　長方形の転がり","hint1":"床に接する頂点を回転の中心として、1回ずつ図を描こう。追う頂点自身が中心のときは動かないよ。","hint2":"半径が辺になる弧と対角線になる弧を足そう。囲まれた面積には、おうぎ形のほかに三角形や長方形が入ることがあるよ。"},{"title":"類題3 3　長方形の転がり","hint1":"床に接する頂点を回転の中心として、1回ずつ図を描こう。追う頂点自身が中心のときは動かないよ。","hint2":"半径が辺になる弧と対角線になる弧を足そう。囲まれた面積には、おうぎ形のほかに三角形や長方形が入ることがあるよ。"}],"基本問題5":[{"title":"5　転がる長方形","hint1":"1回ずつ転がした図に、追う頂点の名前を書こう。","hint2":"辺・対角線を半径とする弧を足す。面積はおうぎ形に加え、その間の三角形も数えよう。"}],"基本問題8":[{"title":"8　正方形と段差","hint1":"角で大きく回るところと、床で回るところを分けよう。","hint2":"弧は各回転角で求める。面積はおうぎ形を足して、図の中で含まれない正方形の部分を引こう。"}],"基礎演習4":[{"title":"4　最後の頂点","hint1":"最後の図から、1回ずつ逆に転がしてみよう。","hint2":"接する頂点は動かない。4つの頂点名を残しながら、最初の図と対応させよう。"}],"基礎演習5":[{"title":"5　長方形の道すじ","hint1":"追う頂点が中心からどれだけ離れているか、各回に書こう。","hint2":"弧を足したあと、面積はおうぎ形とその間の三角形に分ける。長さの式と面積の式を混ぜないでね。"}],"練習問題7":[{"title":"7　長方形の内側","hint1":"内側の各位置に頂点名を書き、頂点が描く弧だけをつなごう。","hint2":"囲まれた部分は、おうぎ形から直角二等辺三角形を引いた形を組み合わせられるよ。"}],"練習問題8":[{"title":"8　段差を越える長方形","hint1":"（1）（2）で追う頂点が違う。別の色で各回の弧を描こう。","hint2":"辺を半径にする回と、対角線を半径にする回がある。半回転する部分も見落とさないでね。"}],"練習問題9":[{"title":"9　三角形の山を越える","hint1":"山の両側を越える図を描き、同じ半径の弧に同じ色をつけよう。","hint2":"山の頂角から残りの角の合計を出す。個々の角が分からなくても、同じ半径の弧の角度の合計が分かれば計算できるよ。"}],"標準演習6":[{"title":"6　長方形の中心の道すじ","hint1":"長方形の中心から頂点までは、対角線の半分だよ。","hint2":"弧をつなぐと四分円が並ぶ。囲まれた面積は外側の正方形から、その四分円を引こう。"}],"チャレンジ1":[{"title":"1　正方形の対角線の通過","hint1":"両端の弧だけでは通過範囲が決まらないよ。回転の中心から対角線に垂線を下ろそう。","hint2":"垂線の足が描く小さい弧より内側は通らない。大きいおうぎ形と間の正方形を足し、その小さいおうぎ形を引こう。"}],"例題4・類題4":[{"title":"例題4 4　段差を転がる三角形","hint1":"1回転がるたびにA・B・Cを書こう。段差の角に接するときは、その点を中心に回るよ。","hint2":"同じ半径の弧は回転角をまとめよう。段差では平らな床と同じ角度にはならないので、周りの角から求めよう。"},{"title":"類題4 4　段差を転がる三角形","hint1":"1回転がるたびにA・B・Cを書こう。段差の角に接するときは、その点を中心に回るよ。","hint2":"同じ半径の弧は回転角をまとめよう。段差では平らな床と同じ角度にはならないので、周りの角から求めよう。"}],"基本問題6":[{"title":"6　正三角形の道すじ","hint1":"各位置に頂点名を書き、追う頂点が中心になる回を見つけよう。","hint2":"動く回だけ、1辺を半径とする弧を描いて足そう。回転角は180度から三角形の内角を引くよ。"}],"基本問題7":[{"title":"7　三角形と段差","hint1":"段差の手前・角・通過後で回転を分けて描こう。","hint2":"半径が同じなら、回転角を先に全部足してから弧の長さを計算できるよ。"}],"基本問題9":[{"title":"9　折れ線上の頂点","hint1":"転がした図すべてにA・B・Cを書こう。","hint2":"目的の位置の頂点が分かったら、指定された頂点が動く回の弧だけ足そう。"}],"基礎演習6":[{"title":"6　段差の正三角形","hint1":"（1）各位置に頂点名を書いて重なる点を確かめよう。","hint2":"（2）（3）は別々の頂点を追う。段差の角を回る大きな角と、床を回る角を区別して足そう。"}],"練習問題5":[{"title":"5　直角二等辺三角形の転がり","hint1":"追う頂点の弧を順につなごう。","hint2":"面積には対角線×対角線が必要。対角線そのものを求めなくても、正方形の面積との関係からその積を出せるよ。"}],"練習問題6":[{"title":"6　五角形の周り","hint1":"五角形の内角と三角形の内角を、接点の周り360度から引こう。","hint2":"同じ辺が下にくる周期と、五角形の同じ辺に戻る周期をそろえる。追う点が回転の中心になる回は弧を足さないよ。"}],"標準演習4":[{"title":"4　六角形の周り","hint1":"転がる図形と六角形の内角から、1回の回転角を求めよう。","hint2":"（1）（2）は半径も回転する回数も異なる。追う点が中心になるときは0として、弧の角度を足そう。"}],"標準演習5":[{"title":"5　五角形の内側","hint1":"内側では、五角形の内角から三角形の内角を引いた角だけ回るよ。","hint2":"1回ずつ頂点名を書いて動く回を数え、その回数分の弧を足そう。"}],"チャレンジ2":[{"title":"2　くぼみを越える三角形","hint1":"段差を降りるところ、底を転がるところ、最後に上がるところを順に描こう。","hint2":"追う点から中心までが1辺の長さになる弧をまとめる。最後の段差では半径が変わるので、その弧を別に足そう。"}],"チャレンジ3":[{"title":"3　六角形の辺の通過","hint1":"辺ABを1回ずつ追い、3つの通過部分を色分けしよう。","hint2":"3つを回転して集めると、おうぎ形に足りない四角形と、はみ出す同じ面積の四角形が見つかるよ。"}]},"6u-13":{"例題1・類題1":[{"title":"例題1 1　半円の回転","hint1":"半円の直径の端を中心に回すと、反対側の端は直径を半径とする弧を描くよ。","hint2":"周りの長さには、最初と最後の半円の弧も入る。面積は同じ半円の部分を移しておうぎ形に整理しよう。"},{"title":"類題1 1　半円の回転","hint1":"半円の直径の端を中心に回すと、反対側の端は直径を半径とする弧を描くよ。","hint2":"周りの長さには、最初と最後の半円の弧も入る。面積は同じ半円の部分を移しておうぎ形に整理しよう。"}],"基本問題1":[{"title":"1　半円の回転","hint1":"外周を1周なぞって、もとの半円の弧と端が動いた弧を分けよう。","hint2":"新しく通った面積は、同じ面積の半円部分を移しておうぎ形にまとめよう。"}],"基本問題2":[{"title":"2　半円の弧が通る範囲","hint1":"回転の中心から動く端までの長さを半径として、弧を描こう。","hint2":"通った範囲を塗り、等しい半円部分を移すと1つのおうぎ形に整理できるよ。"}],"基礎演習1":[{"title":"1　半円の回転","hint1":"半円2つの弧と、端が描いた弧を別々に数えよう。","hint2":"新しい面積は、半円の同じ部分を移すとおうぎ形として求められるよ。"}],"練習問題1":[{"title":"1　離れた点を中心に回す","hint1":"回転の中心から円の中心まで、さらに円の近い端・遠い端までの長さを書こう。","hint2":"外周は内外の弧と両端の半円。面積は2つのおうぎ形の差と、両端の半円に分けよう。"}],"練習問題2":[{"title":"2　半円の重なり","hint1":"周りの直線と弧を区別しよう。面積では交点と円の中心を結ぼう。","hint2":"二等辺三角形の角を求めると、30度を含む直角三角形を見つけられる。必要な高さを出し、おうぎ形から三角形を引こう。"}],"標準演習1":[{"title":"1　離れた中心の周り","hint1":"中心から円の近い端・遠い端までの距離を半径として書こう。","hint2":"周りは内外の弧と両端の半円。面積はおうぎ形の差に、両端の半円を足そう。"}],"例題2・類題2":[{"title":"例題2 2　長方形の内側・外側","hint1":"中心は辺から半径だけ離れている。内側と外側で、角の曲がり方を別々に描こう。","hint2":"外側は直線と角を中心にした弧。内側は各辺から半径ずつ離れた長方形になる。面積では円の端まで広げよう。"},{"title":"類題2 2　長方形の内側・外側","hint1":"中心は辺から半径だけ離れている。内側と外側で、角の曲がり方を別々に描こう。","hint2":"外側は直線と角を中心にした弧。内側は各辺から半径ずつ離れた長方形になる。面積では円の端まで広げよう。"}],"基本問題3":[{"title":"3　直線上の円","hint1":"1回転で進む距離は円周の長さだよ。","hint2":"通過範囲は、幅が直径の長方形と、最初・最後の半円2つ分に分けよう。"}],"基本問題4":[{"title":"4　長方形の内外","hint1":"外側は4本の直線と4つの弧。内側の中心線は、各辺から半径離れた長方形だよ。","hint2":"内側の通過面積は、もとの長方形から中央の通らない長方形と、角の小さなすき間を引こう。"}],"基礎演習2":[{"title":"2　長方形の内外","hint1":"外側の中心線を描き、角の弧4つで円1つ分になることを使おう。","hint2":"内側の面積は、全体から中央の長方形と四隅の小さなすき間を引こう。"}],"練習問題5":[{"title":"5　三角形の周り","hint1":"頂点を回る3つの弧の角度を足すと1周分になるよ。","hint2":"中心線は三角形の周り＋小円1周。面積は辺に沿う直径幅の帯と、角にできるおうぎ形を足そう。"}],"標準演習2":[{"title":"2　三角形の周り","hint1":"円の中心を頂点と結び、角のところで何度回るかを求めよう。","hint2":"3つの弧をまとめる。面積では直径を幅とする3つの長方形と、角のおうぎ形を足そう。"}],"例題3・類題3":[{"title":"例題3 3　段差を転がる円","hint1":"段差に接する円を何個か描き、中心をつなごう。出っぱった角では弧、へこんだ角では直線が短くなるよ。","hint2":"通過面積は長方形とおうぎ形に分ける。へこんだ角の小さな通らない部分を引くのを忘れずに。"},{"title":"類題3 3　段差を転がる円","hint1":"段差に接する円を何個か描き、中心をつなごう。出っぱった角では弧、へこんだ角では直線が短くなるよ。","hint2":"通過面積は長方形とおうぎ形に分ける。へこんだ角の小さな通らない部分を引くのを忘れずに。"}],"基本問題5":[{"title":"5　折れ線に沿う円","hint1":"出っぱる角は中心が弧を描き、へこむ角では中心の直線が短くなるよ。","hint2":"面積は直径幅の帯と弧の部分を足し、へこんだ角の通らない部分を引こう。"}],"基本問題6":[{"title":"6　くぼみのある形","hint1":"外側と内側について、中心の通る線をそれぞれ描こう。辺の長さをそのまま使えない箇所に印をつけよう。","hint2":"面積は帯とおうぎ形に分ける。重複したところや円が入れないすき間を、図で確認して引こう。"}],"基礎演習3":[{"title":"3　段差の通過","hint1":"中心をたどり、元の線より短くなる直線に印をつけよう。","hint2":"面積は直径幅の長方形とおうぎ形を足す。内側の角の小さなすき間を除こう。"}],"基礎演習4":[{"title":"4　L字形の周り","hint1":"Pの中心を辺から半径離して描こう。L字のへこんだ角は、出っぱった角と曲がり方が違うよ。","hint2":"Qが通る面積はL字全体から通らない部分を引く。各角に残るすき間を同じ形ごとに数えよう。"}],"練習問題4":[{"title":"4　折れ線の通過範囲","hint1":"中心の直線と弧を別々に求めよう。","hint2":"通過面積では帯を足し、重なりやすき間を補正する。中心線の長さに直径をかけるだけで済ませないでね。"}],"練習問題6":[{"title":"6　斜めの折れ線","hint1":"斜めの部分の両端の回転角は、合計で求められないかな。","hint2":"面積を直径幅の帯とおうぎ形に分け、へこんだ角のすき間を引こう。帯の長さは中心線の直線部分とは限らないよ。"}],"標準演習4":[{"title":"4　折れ線の面積","hint1":"同じ形が4つあることに注目し、4分の1だけ描こう。","hint2":"その部分を帯とおうぎ形に分け、へこんだ角のすき間を引いてから4倍しよう。"}],"標準演習5":[{"title":"5　段差とくぼみ","hint1":"円が角に接する瞬間を描き、中心の道すじを弧と直線に分けよう。","hint2":"両方の角から中心までが半径なら、正三角形ができないかな。角度が分かれば短い弧も求められるよ。"}],"チャレンジ1":[{"title":"1　十字形の内側","hint1":"十字形を4等分して考えよう。円の中心は、壁から半径以上離れていなければならないよ。","hint2":"小さい円は直線と弧をつなぐ。大きい円は両側の角に同時に接する位置を描き、正三角形から弧の角を求めよう。"}],"例題4・類題4":[{"title":"例題4 4　おうぎ形の周り","hint1":"曲線の外側では、もとの半径に円の半径を足した距離を中心が進むよ。","hint2":"面積の外側の半径は、もとの半径＋円の直径。直線部分の帯と、角を回るおうぎ形も足そう。"},{"title":"類題4 4　おうぎ形の周り","hint1":"曲線の外側では、もとの半径に円の半径を足した距離を中心が進むよ。","hint2":"面積の外側の半径は、もとの半径＋円の直径。直線部分の帯と、角を回るおうぎ形も足そう。"}],"基本問題7":[{"title":"7　四分円の周り","hint1":"中心の道すじは、2本の直線・角を回る弧・大きな弧に分かれるよ。","hint2":"面積は直線の帯と角のおうぎ形、大きいおうぎ形の差に分けよう。中心線の半径と外側の半径は違うよ。"}],"基本問題8":[{"title":"8　欠けた円の周り","hint1":"大きな弧・端の角・内側の直線を順に描こう。","hint2":"面積は外側と内側のおうぎ形の差に、残りの部分を足す。へこんだ角の小さなすき間も引こう。"}],"基礎演習5":[{"title":"5　おうぎ形の周り","hint1":"角を回る小さい弧と、もとのおうぎ形に沿う大きい弧を分けよう。","hint2":"通過面積の幅は円の直径。大きな弧の外側の半径には直径を足し、内側のおうぎ形を引こう。"}],"練習問題3":[{"title":"3　直線と半円","hint1":"曲線では半径を足すか引くか、円がどちら側にあるかを確認しよう。","hint2":"面積は外側の大きな範囲から内側の通らない範囲を引く。直線の帯・半円・角のすき間に分けて数えよう。"}],"標準演習3":[{"title":"3　半円の周り","hint1":"半円に沿う部分の中心線の半径は、2つの半径の和だよ。","hint2":"面積は大きな半円から元の半円を引き、直線の帯と両端の角の部分を足そう。"}],"例題5・類題5":[{"title":"例題5 5　移動と回転数","hint1":"（1）直線上では1回転で円周の長さだけ進む。円周×回転数で移動距離を求めよう。（2）は円の外側を回る場合だよ。","hint2":"外側を1周なら、大きな円の円周÷小さな円の円周に1回を足す。中心の道すじ÷小さな円周でも確かめられるよ。"},{"title":"類題5 5　移動と回転数","hint1":"（1）直線上では1回転で円周の長さだけ進む。円周×回転数で移動距離を求めよう。（2）は円の外側を回る場合だよ。","hint2":"外側を1周なら、大きな円の円周÷小さな円の円周に1回を足す。中心の道すじ÷小さな円周でも確かめられるよ。"}],"基本問題9":[{"title":"9　円の内外と回転数","hint1":"外側の中心間は半径の和、内側は半径の差だよ。","hint2":"円自身の回転数は、大円周÷小円周をもとに外側は1回足し、内側は1回引く。通過面積は円の外端と内端の円の差だよ。"}],"基礎演習6":[{"title":"6　円の周りと回転","hint1":"中心の道すじの半径は、接する2円の半径の和だよ。","hint2":"外側を1周すると、接する弧の分に加えて向きが1周分変わる。回転数にもその分を足そう。"}],"練習問題7":[{"title":"7　回転後の文字","hint1":"直線区間は進んだ距離÷円周で回転数を求めよう。","hint2":"円の外側を回る区間では、接する弧による回転に中心の向きの変化を加える。1回転の整数部分を除き、残りで文字の向きを追おう。"}],"練習問題8":[{"title":"8　並んだ円の周り","hint1":"中心が通る弧を1つずつ描き、同じ半径の角度をまとめよう。","hint2":"それぞれの円の外側で、接する弧の分と中心の向きの変化の分を足す。図形を1周したから必ず「＋1」とは限らないよ。"}],"標準演習6":[{"title":"6　組み合わせた円の周り","hint1":"中心が通る各弧の半径と角度を書いて足そう。","hint2":"接する円と転がる円の大きさを比べ、各区間の回転数を求めて合計する。中心が回った角度も回転数に反映しよう。"}],"チャレンジ2":[{"title":"2　曲線と矢印の向き","hint1":"直線・外側の角・内側の弧に区切り、中心線の半径をそれぞれ書こう。","hint2":"矢印はPからQまでの回転だけ考える。接した弧の長さ÷円周から、内側を回る中心角に相当する回転数を引き、Pでの向きから追おう。"}]},"6u-14":{"例題1・類題1":[{"title":"例題1 1　平行移動で通る範囲","hint1":"辺が通る範囲と、図形全体が通る範囲を別々に塗ろう。","hint2":"平行移動では同じ形の部分を移せる。帯の面積に、必要ならもとの図形の面積を足そう。"},{"title":"類題1 1　平行移動で通る範囲","hint1":"辺が通る範囲と、図形全体が通る範囲を別々に塗ろう。","hint2":"平行移動では同じ形の部分を移せる。帯の面積に、必要ならもとの図形の面積を足そう。"}],"基本問題1":[{"title":"1　三角形の平行移動","hint1":"最初と最後の対応する頂点を結び、動いた距離を求めよう。","hint2":"辺が通る平行四辺形の面積を求める。三角形全体の通過範囲には元の三角形も足そう。"}],"基本問題2":[{"title":"2　四分円の平行移動","hint1":"弧が通った部分の両端には同じ曲線がある。片方を移して長方形にしよう。","hint2":"全体の面積から元の四分円の面積を引く。残る長方形の面積÷高さが移動距離だよ。"}],"基礎演習1":[{"title":"1　四分円の平行移動","hint1":"対応する頂点の移動距離を求めよう。","hint2":"弧の通過部分を長方形に直して面積を求め、全体なら元の四分円も足そう。"}],"練習問題1":[{"title":"1　おうぎ形の平行移動","hint1":"全体の増えた面積は、進む向きに垂直な幅×移動距離で考えよう。","hint2":"指定された部分の面積は、長方形とおうぎ形に分けられないかな。図形全体の通過範囲と取り違えないでね。"}],"標準演習3":[{"title":"3　三角形の辺が通る面積","hint1":"辺が通った範囲を平行四辺形に分けよう。底辺をそろえると面積を足しやすいよ。","hint2":"指定面積÷共通の底辺で高さの合計を出す。そこから動く点の位置を相似で求め、道のりを速さで割ろう。"}],"例題2・類題2":[{"title":"例題2 2　重なりの形","hint1":"重なる形が変わる瞬間ごとに小さな図を描こう。","hint2":"各形が始まる位置と終わる位置の差を速さで割る。指定時刻の面積は、速さ×時間だけ動かしてから求めよう。"},{"title":"類題2 2　重なりの形","hint1":"重なる形が変わる瞬間ごとに小さな図を描こう。","hint2":"各形が始まる位置と終わる位置の差を速さで割る。指定時刻の面積は、速さ×時間だけ動かしてから求めよう。"}],"基本問題3":[{"title":"3　三角形と長方形","hint1":"指定時刻までに動いた距離を書き、重なった形だけを塗ろう。","hint2":"重なりが台形なら、大きい直角二等辺三角形から小さいものを引いても求められるよ。"}],"基本問題4":[{"title":"4　同じ面積の時刻","hint1":"まず指定時刻の図を描いて重なりの面積を求めよう。","hint2":"同じ面積になる重なりを、入るときと出るときに描く。そのときの移動距離を速さで割ろう。"}],"基礎演習2":[{"title":"2　三角形と正方形","hint1":"頂点が相手の辺を通るたびに、重なりの形を描こう。","hint2":"重なり始めと終わりの時刻を出し、差を取る。指定時刻の面積は、その時点の図から求めよう。"}],"練習問題2":[{"title":"2　台形と長方形","hint1":"重なり始め、全体が入る、出始め、重なり終わる位置を描こう。","hint2":"途中の面積は斜辺で切られた台形などになる。元の三角形との相似で高さや辺の長さを求めよう。"}],"練習問題3":[{"title":"3　2つの三角形","hint1":"交点から底辺へ垂線を下ろすと、2つの相似な三角形が見つかるよ。","hint2":"共通の高さを基準に底辺2つの比をそろえる。後半は大きい三角形から重ならない小さい三角形を引こう。"}],"練習問題4":[{"title":"4　面積が半分になる時刻","hint1":"指定時刻の移動距離を求め、三角形の斜辺で切られた部分の長さを相似で出そう。","hint2":"半分の面積になる図を、入るときと出るときに1つずつ描く。長方形と三角形に分けると必要な移動距離を求められるよ。"}],"標準演習1":[{"title":"1　向かい合う三角形","hint1":"片方を止め、もう片方が2つの速さの和で進むと考えよう。","hint2":"重なる時間は始まりと終わりの差。途中の重なりは、交点から底辺に垂線を下ろし、相似から高さを出そう。"}],"チャレンジ1":[{"title":"1　直角三角形と長方形","hint1":"頂点が長方形の角を通る瞬間を描き、相似から必要な横の長さを求めよう。","hint2":"全体が重なる時間は入り切る時刻と出始める時刻の差。面積が半分になるときは、三角形の斜辺が長方形の中心を通ることを使おう。"}],"例題3・類題3":[{"title":"例題3 3　重なりのグラフ","hint1":"グラフが折れる時刻に、どの辺とどの辺がそろうか描こう。","hint2":"速さ×時間で横の長さ、面積÷横の長さで縦の長さを求める。同じ面積は入り始めと出ていくときの2回を探そう。"},{"title":"類題3 3　重なりのグラフ","hint1":"グラフが折れる時刻に、どの辺とどの辺がそろうか描こう。","hint2":"速さ×時間で横の長さ、面積÷横の長さで縦の長さを求める。同じ面積は入り始めと出ていくときの2回を探そう。"}],"基本問題5":[{"title":"5　グラフと辺の長さ","hint1":"面積が増え終わる瞬間には、どの横の辺を通り切ったかな。","hint2":"そのときの距離から横の長さを出し、最大面積から縦を求める。次の折れ目も対応する辺で考えよう。"}],"基本問題6":[{"title":"6　2つの正方形","hint1":"小さい正方形が入り切るまでの距離から、その1辺を求めよう。","hint2":"重なりがなくなるまでの距離は2つの1辺の和。大きい方の1辺を求めると、出始める時刻も分かるよ。"}],"基礎演習3":[{"title":"3　面積グラフと長方形","hint1":"最初の折れ目は正方形が入り切った瞬間。移動距離が正方形の1辺になるよ。","hint2":"最大面積÷その1辺で長方形の縦を求める。次の折れ目までの移動距離から横も求めよう。"}],"基礎演習4":[{"title":"4　速さと重なり","hint1":"グラフの折れ目が図のどの位置かを確かめ、速さを出そう。","hint2":"面積から必要な重なり幅を出す。入るときと出るとき、それぞれの移動距離を速さで割ろう。"}],"練習問題5":[{"title":"5　段差の図形とグラフ","hint1":"重なりがなくなるまでの距離から速さを出そう。各折れ目を頂点の位置と結びつけよう。","hint2":"同じ傾きの区間は、面積が毎秒同じだけ増減する。求める面積の水平線が交わる区間をすべて調べよう。"}],"標準演習2":[{"title":"2　L字形とグラフ","hint1":"グラフの折れ目ごとに図を描き、進んだ距離を辺の長さに対応させよう。","hint2":"後半も辺がそろう瞬間の時刻と面積を求めて点を打つ。面積が一定の区間と、減り方が変わる区間を分けて結ぼう。"}],"例題4・類題4":[{"title":"例題4 4　おうぎ形の転がり","hint1":"弧の部分を転がる間、中心は水平に進む。その距離は転がった弧の長さだよ。","hint2":"角を中心に回る間、中心は弧を描く。中心線は直線＋弧、通過面積は長方形＋おうぎ形に分けよう。"},{"title":"類題4 4　おうぎ形の転がり","hint1":"弧の部分を転がる間、中心は水平に進む。その距離は転がった弧の長さだよ。","hint2":"角を中心に回る間、中心は弧を描く。中心線は直線＋弧、通過面積は長方形＋おうぎ形に分けよう。"}],"基本問題7":[{"title":"7　四分円の転がり","hint1":"弧が床を転がる間の移動距離は、その弧の長さだよ。","hint2":"中心の道すじは回転する弧を追う。全体の面積は両端のおうぎ形と、弧に沿って進んだ間の長方形に分けよう。"}],"基本問題8":[{"title":"8　中心の道すじ","hint1":"中心は最初と最後に角を中心として回り、途中で水平に進むよ。","hint2":"直線の長さは元のおうぎ形の弧の長さ。面積は両端の四分円と途中の長方形を足そう。"}],"基本問題9":[{"title":"9　大きな中心角のおうぎ形","hint1":"途中の直線部分は、転がった弧の長さと同じだよ。","hint2":"最初と最後の中心の弧は、元のおうぎ形の中心角とは違う。接する辺と床から回転角を確かめよう。"}],"基礎演習5":[{"title":"5　半円の転がり","hint1":"弧が転がる間、中心が水平に進む長さを半円周から求めよう。","hint2":"中心の軌跡には両端の回転も加える。面積は途中の長方形と両端の四分円だよ。"}],"基礎演習6":[{"title":"6　おうぎ形の通過範囲","hint1":"中心の軌跡・弧の通過範囲・図形全体の通過範囲を別々に描こう。","hint2":"弧の通過範囲は同じ部分を移しておうぎ形へ。全体は途中の長方形と両端のおうぎ形に分けよう。"}],"練習問題6":[{"title":"6　150度のおうぎ形","hint1":"床に接する弧の長さを先に求めよう。図のxには半径の長さも含まれているよ。","hint2":"中心の軌跡は両端の弧＋途中の直線。面積は両端の四分円＋途中の長方形に分けよう。"}],"標準演習4":[{"title":"4　四分円の転がり","hint1":"図のxは、半径と、弧が床を転がって進む距離の和だよ。","hint2":"中心の道すじには両端の弧を加える。面積は直径ではなくおうぎ形の半径を高さとする長方形と、両端の四分円に分けよう。"}],"チャレンジ2":[{"title":"2　斜めの段差を越える","hint1":"角で回転するときは中心が弧を描き、弧が面に沿って転がるときは中心が直線を進むよ。","hint2":"同じ半径の弧の回転角をまとめよう。直線部分の長さは、床や斜面に接して転がった弧の長さから求めて足そう。"}]},"6u-15":{"基本問題1":[{"title":"1　船の上り・下りの速さ","hint1":"（1）グラフから行きと帰りにかかった時間を別々に読もう。速い方が下りだよ。","hint2":"（2）下り−上りは流れ2つ分。（3）高速船はBから上るので静水時の速さから流れを引く。2そうの速さの和で距離を割ろう。"}],"基本問題2":[{"title":"2　川の流れと距離","hint1":"（1）同じ距離なので上りと下りの速さは時間の逆比だよ。","hint2":"比の数の平均が静水時の速さに当たるよ。流れを出したら、（2）は上りの速さ×25分。最後にkmへ直そう。"}],"基本問題3":[{"title":"3　船の故障と往復","hint1":"（1）下りの速さから流れを求め、上りの速さを出そう。","hint2":"（2）8分間に流された距離を上り直す時間が必要だよ。通常の往復時間に、故障8分と上り直す時間を足そう。"}],"基本問題4":[{"title":"4　エスカレーター","hint1":"（1）「機械だけ」と「機械＋歩く」の速さを時間の逆比で表そう。","hint2":"その差が歩く速さ。（2）毎秒3段を使って機械の速さも段で表し、全体の段数を求めよう。"}],"基礎演習1":[{"title":"1　上り・下りと所要時間","hint1":"（1）60kmを、それぞれにかかった時間で割ろう。","hint2":"（2）は上流へ向かうので上りの速さを使うよ。時間の小数部分は60倍して分へ直そう。"}],"基礎演習2":[{"title":"2　船とボートの出会い","hint1":"（1）帰りの時間は15時間そのものではないね。（2）上りと下りの平均と、差の半分を使おう。","hint2":"（3）船がBで折り返す時、ボートが進んだ距離を求めよう。残りの間隔を向かい合う速さで割り、折り返す前の時間を足そう。"}],"練習問題1":[{"title":"1　船の静水時の速さの変化","hint1":"（1）15分前後それぞれの速さを出そう。流れは同じだから、速さの増えた分は静水時の増えた分だよ。","hint2":"静水時の速さの差を、1.5−1に当てて元の静水時の速さを求めよう。（2）は元の静水時の速さに流れを足して下りを求めよう。"}],"練習問題2":[{"title":"2　船の出会いと故障","hint1":"（1）全体を20・24・15の公倍数にして、Pの下り、Qの下り、Qの上りを順に出そう。","hint2":"（2）普通なら上りに何分かかるかな？ 余分な時間は「流された時間＋元の位置に戻る時間」。その2つを流れと上りの速さの逆比で分けよう。"}],"練習問題3":[{"title":"3　動く歩道","hint1":"（1）40秒と120秒から「歩く＋歩道」と「歩道」の速さを比べよう。","hint2":"差が歩く速さだよ。（2）歩道の速さと全体の距離を出し、自分で歩く速さだけで割ろう。"}],"標準演習1":[{"title":"1　川を往復する兄弟","hint1":"（1）弟の上りと下りから流れを出そう。8分後の出会いで、兄の下りの速さも求められるよ。","hint2":"（2）兄がAで折り返す時刻と上りの速さを出そう。24分後の2人の間隔を求め、近づく速さで割って24分に足そう。"}],"標準演習2":[{"title":"2　エスカレーターと歩く速さ","hint1":"（1）機械だけと歩いた場合の速さを、時間の逆比で表そう。差が毎秒2段だよ。","hint2":"機械の速さを求めて全段数へ。（2）は機械の速さに毎秒1段を足し、全段数を割ろう。"}],"チャレンジ1":[{"title":"1　船の故障と流される距離","hint1":"（1）40分を時間に直して上りの速さを求めよう。（2）流された15分と、その後の下りを分けよう。","hint2":"（3）帰りの時間を取り出し、全部エンジンを動かした場合の距離と比べよう。距離の差を「下りの速さ−流れ」で割ると、止めた時間が出せるよ。最後に、その時間×流れの速さで、流された距離へ戻そう。"}],"チャレンジ2":[{"title":"2　エスカレーターに乗る2人","hint1":"（1）追いこしまでの時間を2人分書こう。りなの進む速さには機械の速さも含むよ。","hint2":"（2）残り9mの時間比と3秒の差を使い、速さと全長を出す。（3）りなの歩く速さだけを1.5倍し、機械の速さを足そう。2人の所要時間の差が出発を遅らせる時間だよ。"}],"基本問題5":[{"title":"5　図形の回転移動","hint1":"AはCから何cm離れたまま動くかな？ 回る角度も図に書こう。","hint2":"（1）は円周のうち回った割合、（2）は円の面積のうち同じ割合だよ。"}],"基本問題6":[{"title":"6　長方形の転がり移動","hint1":"転がるたびに、床に接する頂点を中心としてBの弧を描こう。B自身が中心のときは動かないよ。","hint2":"（1）半径が辺・対角線になる弧を足す。（2）おうぎ形だけでなく、弧の下に入る長方形も忘れず足そう。"}],"基本問題7":[{"title":"7　正三角形の転がり移動","hint1":"（1）転がるたびにA・B・Cを書き込もう。段差の角では回る角度が変わるよ。","hint2":"（2）Bが中心の場面を除き、Bが描く弧の中心角を足そう。半径はどれも正三角形の辺だね。"}],"基礎演習3":[{"title":"3　回転移動の長さと面積","hint1":"（1）Aが描く弧はCが中心だよ。（2）ABの両端が描く弧を描こう。","hint2":"（2）初めと終わりの三角形は同じ面積。大きいおうぎ形から小さいおうぎ形を引く形に整理しよう。"}],"基礎演習4":[{"title":"4　正三角形の回転移動","hint1":"（1）1辺分ずつ転がし、頂点名を順に書こう。","hint2":"（2）Bが支点のときは動かないよ。折れ曲がりの角も確かめ、Bの弧の中心角を足そう。"}],"練習問題4":[{"title":"4　直角三角形の回転","hint1":"矢印の向きに回すので、小さい方の角度だけを使わないようにしよう。","hint2":"（1）Aの弧の半径はAC。（2）AとBが描くおうぎ形の差で求められるよ。初めと終わりの三角形の面積は打ち消し合うね。"}],"練習問題5":[{"title":"5　正六角形の周りの転がり","hint1":"各辺の途中と六角形の角とで、回転角が違うよ。Pが支点になる場面も描こう。","hint2":"六角形の半周で、頂点の並びがどうなるか確かめよう。Pが実際に動く弧の中心角だけを合計し、半径3cmの円周に当てはめよう。"}],"標準演習3":[{"title":"3　三角形の回転移動","hint1":"（1）最初はAが支点、次はBが支点だよ。Bが実際に描く弧を選ぼう。","hint2":"（2）2つの半径9cmの弧の交点を結ぶと正三角形が見つかるよ。重なりを1回だけ数えるよう、おうぎ形2つと正三角形に分けよう。"}],"チャレンジ3":[{"title":"3　正三角形が通る図形","hint1":"半径と三角形の辺が等しいね。中心から円周へ線を引き、転がった後の三角形を順に描こう。","hint2":"（1）通った範囲を同じ正三角形に分ける。（2）Bが支点のときの移動は0。Bが動く弧だけを合計し、最後に四捨五入しよう。"}],"チャレンジ4":[{"title":"4　正方形の回転移動","hint1":"（1）PRが回る中心はR。PR×PRは、正方形の面積から求められるよ。","hint2":"（2）対角線の交点Oを描き、半円からOの弧に沿う四分円と三角形2個を引こう。（3）角を回る半円部分と、辺の途中を動く部分を4組に整理しよう。"}],"チャレンジ5":[{"title":"5　三角形の回転と通過面積","hint1":"（1）OABCは平行な2辺と等しい脚をもつ台形。対角線の長さを比べよう。","hint2":"（2）外側の円の半径はOから最も遠い頂点まで。内側はOから辺ACまでの最短距離だよ。大きい円から小さい円を引こう。"}],"基本問題8":[{"title":"8　円が正方形の周りを転がる","hint1":"（1）辺に沿う直線と、角を回る弧に分けよう。中心は辺から半径だけ離れるよ。","hint2":"（2）辺に沿う幅4cmの長方形と、角の四分円を合わせよう。角の外側の半径は、動く円の直径だよ。"}],"基本問題9":[{"title":"9　円が段差に沿って転がる","hint1":"（1）へこんだ角と出っ張った角を区別し、中心が通る線を描こう。","hint2":"（2）最初と最後の半円、直線部分の長方形、角の曲線部分を足そう。へこんだ角で2度数えた部分を引いてね。"}],"基本問題10":[{"title":"10　円の内側・外側の転がり","hint1":"（1）（3）円の中心の通り道の半径は、外側なら半径の和、内側なら差だよ。","hint2":"（2）（4）この1周では「中心の通り道の長さ÷動く円の円周」で回転数を求められるよ。"}],"基礎演習5":[{"title":"5　半円の回転移動","hint1":"（1）半円の弧2本と、Aが描いた弧に分けよう。","hint2":"（2）回転前後の半円の面積は同じだね。足す半円と引く半円を消すと、どのおうぎ形が残るかな？"}],"練習問題6":[{"title":"6　円の移動と通過範囲","hint1":"（1）大きな弧では半径8cmに小円の半径を足そう。出っ張った角とへこんだ角も分けて描こう。","hint2":"（2）幅2cmの長方形、角の四分円、大きな円弧に沿う帯を足そう。へこんだ角に残る、円が通らない小さなすき間を引こう。"}],"練習問題7":[{"title":"7　円が円の周りを転がる","hint1":"同じ半径の円の中心を3つ結ぶと正三角形になるね。これでOが上の円の周りを動く角度が出せるよ。","hint2":"（1）中心の弧の長さを求める。（2）大小のおうぎ形の差に両端の半円を足す。（3）中心の移動距離を動く円の円周で割ろう。"}],"標準演習4":[{"title":"4　円の通らない部分","hint1":"（1）かどやくぼみに円を置いてみよう。「正方形−四分円」のすき間を探せるよ。","hint2":"外側の角の小さいすき間と、くぼみ近くの大きいすき間を別々に数える。（2）図形全体の面積から（1）を引こう。"}],"チャレンジ6":[{"title":"6　円周上を動く円と角度","hint1":"（1）8秒間で大きな円に接した弧は、それぞれ小円1周分だよ。円Aの何度分か求めよう。","hint2":"最初のAB・ACの向きから、それぞれの回転方向に角度を進めよう。（2）8秒分の角度を30秒分に直し、360度の整数倍を除いて位置を描こう。"}],"チャレンジ7":[{"title":"7　2つの円の重なり","hint1":"（1）1回転で中心が進む距離は円周。中心間が半径分になるまで、何cm進むかな？","hint2":"（2）2つの中心と交点を結ぶと正三角形になるよ。重なりを「おうぎ形−三角形」2つに分け、最後に四捨五入しよう。"}],"チャレンジ8":[{"title":"8　円の中心と回転の向き","hint1":"（1）AB側は大きな円の内側、BC側は外側。中心の通り道の半径を引き算・足し算で求めよう。","hint2":"（2）各区間で「中心の通り道の長さ÷小円の円周」から回転数を求めよう。どちらの区間も時計回りに転がるよ。1回転では向きが元に戻ることを使い、最初の左向きから順に追おう。"}],"基本問題11":[{"title":"11　平行移動して通る範囲","hint1":"（1）同じ点Oの移動前後を比べよう。（2）左右の曲線部分を移し替えると長方形になるよ。","hint2":"（2）は移動距離×高さ。（3）はそれに、最初にあった四分円の面積を足そう。"}],"基本問題12":[{"title":"12　図形の重なり方","hint1":"（1）三角形の頂点が長方形の辺を通る瞬間ごとに図を描こう。","hint2":"（2）「重なり始め」を0秒にして8cm進めよう。高さ6cmで三角形を切った位置を相似で求め、重なった台形の上下の辺を出そう。"}],"基本問題13":[{"title":"13　おうぎ形の転がり移動","hint1":"Oは「持ち上がる弧→水平な線→下がる弧」と動くよ。","hint2":"水平な線の長さは、おうぎ形の弧の長さと同じ。（1）は弧と直線、（2）は四分円2つと長方形を足そう。"}],"基礎演習6":[{"title":"6　平行移動で通る面積","hint1":"（1）曲線にはさまれた部分を左右に移し替えよう。","hint2":"移動した14cmと高さ8cmの長方形として求められるよ。（2）は最初の四分円も合わせよう。"}],"基礎演習7":[{"title":"7　おうぎ形の転がり","hint1":"Oの動きを「四分円の弧・直線・四分円の弧」に分けよう。","hint2":"直線部分は135度のおうぎ形の弧の長さ。（1）は3部分の長さ、（2）は四分円2個と長方形の面積を足そう。"}],"練習問題8":[{"title":"8　長方形の重なりとグラフ","hint1":"（1）最初から最後までの移動距離は、2つの図形の横幅の和。3秒の折れ目は段差の位置だよ。","hint2":"（2）面積60の横線がグラフと交わる区間を2つ探そう。それぞれ1秒で何cm²増減するかを出し、区間の始まりからの時間を足そう。"}],"練習問題9":[{"title":"9　三角形の重なり","hint1":"（1）長方形の右上・左上が斜めの辺を通る位置を描こう。（2）9秒後の位置を描き、長方形から欠ける三角形を引こう。","hint2":"（3）最初は小さい相似な三角形が重なるよ。面積比4：25を長さの比に戻し、重なるまでのすき間も移動距離に足そう。"}],"練習問題10":[{"title":"10　平行移動と面積","hint1":"（1）PはQと同じ形・長さの道すじを、8cm上で動くよ。","hint2":"（2）斜めの帯を縦に切って移し替えると、横がAB、縦が棒の長さの長方形になるよ。"}],"練習問題11":[{"title":"11　おうぎ形の転がり","hint1":"中心がCを回る場面と、弧がCDに接して進む場面を分けよう。","hint2":"Cの周りの半円の弧、水平な移動、最後の四分円の弧を足そう。水平な移動距離は、転がる四分円の弧の長さと同じだよ。"}],"標準演習5":[{"title":"5　重なる面積のグラフ","hint1":"（1）18〜27秒は、横幅6cmから抜けていく時間だよ。","hint2":"（2）3秒で進む距離がウ。最初の重なり12cm²を使ってイを求める。18秒後の60cm²は幅6cmとアで作る長方形だよ。"}],"標準演習6":[{"title":"6　おうぎ形の転がり","hint1":"中心Oは、Bの周りで回った後、縦に動き、最後にもう一度回るよ。","hint2":"（1）直線部分の長さは元のおうぎ形の弧と同じ。（2）角を回る部分と最後の四分円、縦に動く長方形に分けて足そう。"}],"チャレンジ9":[{"title":"9　図形の重なりの最大値","hint1":"（1）27cm進めた図を描こう。（2）縦の辺が重なる瞬間ごとに面積を調べよう。","hint2":"（3）最大の前と後で別々に考える。74cm²をはさむ2つの位置を見つけ、その区間で1秒に何cm²変わるかを使おう。"}],"チャレンジ10":[{"title":"10　おうぎ形の転がりと面積","hint1":"（1）おうぎ形Aの弧の長さは、半円Bの弧の長さと等しいよ。","hint2":"（2）外側の通過範囲はBと同じ中心の大きな半円になる。半径を求め、中央の半円Bの面積を引こう。"}],"チャレンジ11":[{"title":"11　円板の移動と通過面積","hint1":"円弧が床に接する間はOが水平に動き、欠けた部分に来ると端を支点に回るよ。","hint2":"（1）水平部分と半径10cmの弧2つに分ける。（2）水平部分の下の長方形に、おうぎ形2つと中央の三角形を足そう。"}]},"6u-16":{"例題1・類題1":[{"title":"例題1 1　長方形上の2点","hint1":"速さ×時間で進んだ道のりを求め、通り過ぎた辺の長さを引いて位置を書こう。","hint2":"面積は全体から周りの三角形を引くと求めやすいよ。初めて出会った後は、1周の長さ÷速さの和の時間ごとに出会う。"},{"title":"類題1 1　長方形上の2点","hint1":"速さ×時間で進んだ道のりを求め、通り過ぎた辺の長さを引いて位置を書こう。","hint2":"面積は全体から周りの三角形を引くと求めやすいよ。初めて出会った後は、1周の長さ÷速さの和の時間ごとに出会う。"}],"基本問題1":[{"title":"1　2点と面積","hint1":"各点の道のりを出し、通り過ぎた辺を引いて現在の位置を書こう。","hint2":"底辺と高さがすぐ分からなければ、長方形全体から周りの3つの三角形を引こう。"}],"基本問題2":[{"title":"2　出会う時刻と場所","hint1":"初めの間隔を、2点が近づく速さで割ろう。","hint2":"次の出会いまでは1周分の間隔を縮める。場所は、片方の道のりから周を引き、残りを辺に沿ってたどろう。"}],"基礎演習1":[{"title":"1　2点と三角形の面積","hint1":"時刻ごとに2点の道のりを求め、今いる辺と頂点からの距離を書こう。","hint2":"直接求めやすいときは底辺×高さ÷2、難しいときは長方形から周りの三角形を引こう。"}],"基礎演習2":[{"title":"2　重なる時刻と位置","hint1":"初回は出発時の間隔を速さの和で割るよ。","hint2":"次からは1周分÷速さの和ごとに出会う。位置は片方の道のりを1周の長さで割った余りで考えよう。"}],"練習問題1":[{"title":"1　正方形で追い越す","hint1":"最初の間隔は1周分とは限らない。速い点が追いつくために縮める距離を図で確かめよう。","hint2":"次からは1周÷速さの差ごとに追い越す。その時刻の道のりを辺に沿ってたどり、場所を求めよう。"}],"練習問題2":[{"title":"2　2点が作る面積","hint1":"Qが頂点に着く時刻を出し、その時点のPの位置も描こう。","hint2":"台形になったら、目標面積から平行な2辺の和を求める。その和と2点の道のりの和の違いを図で確認しよう。"}],"標準演習1":[{"title":"1　長方形になる時刻","hint1":"長方形になる図を描き、向かい合う辺の等しい長さを使おう。","hint2":"2点の道のりの和を、もとの辺の長さで表す。その長さを速さの和で割ろう。"}],"標準演習2":[{"title":"2　等しい面積","hint1":"四角形の面積は台形として考え、上底＋下底を求めよう。","hint2":"2つの三角形は高さが等しいので、面積が等しい条件を底辺の等しさに直す。道のりの和か差を使おう。"}],"チャレンジ1":[{"title":"1　異なる道すじ","hint1":"2点が同じ辺上を進む区間に注目し、初めの間隔と速さの差を使おう。","hint2":"同じ頂点に同時に戻る時刻は、それぞれの道すじを1周する時間の最小公倍数だよ。"}],"例題2・類題2":[{"title":"例題2 2　面積のグラフ","hint1":"グラフの折れ目で点がどの頂点にいるかを対応させよう。","hint2":"速さ×区間の時間で辺の長さを求める。指定面積の時刻は、各直線区間で毎秒いくつ面積が変わるかを使い、増える側と減る側を探そう。"},{"title":"類題2 2　面積のグラフ","hint1":"グラフの折れ目で点がどの頂点にいるかを対応させよう。","hint2":"速さ×区間の時間で辺の長さを求める。指定面積の時刻は、各直線区間で毎秒いくつ面積が変わるかを使い、増える側と減る側を探そう。"}],"基本問題3":[{"title":"3　台形とグラフ","hint1":"各頂点に着く時刻を読み、道のりと三角形の面積から辺の長さを求めよう。","hint2":"同じ辺を動く間は面積が一定の割合で変わる。目標面積に増える時刻と減る時刻を別々に出そう。"}],"基本問題4":[{"title":"4　グラフから速さ","hint1":"最初の折れ目の面積から、その頂点までの高さを求めよう。","hint2":"その距離÷時間で速さが出る。残りの辺や空欄は、点の位置と底辺×高さ÷2で埋めよう。"}],"基礎演習3":[{"title":"3　面積のグラフ","hint1":"グラフの端と折れ目の面積が、図のどの三角形か確認しよう。","hint2":"台形の面積は三角形2つに分ける。指定面積までの増加分を、毎秒の増加分で割ろう。"}],"練習問題3":[{"title":"3　台形と等しい面積","hint1":"点が斜辺上にあるときは、平行線で区切った三角形の相似を使おう。","hint2":"底辺が同じなら面積比は高さの比。目標の高さになる場所を、別の辺にも探して時刻に直そう。"}],"標準演習3":[{"title":"3　台形上の移動グラフ","hint1":"最初の折れ目の面積から辺を出し、その辺を進む時間で割って速さを求めよう。","hint2":"各頂点の時刻と面積を埋める。指定された面積の水平線を引き、増加中・減少中の両方で時刻を求めよう。"}],"例題3・類題3":[{"title":"例題3 3　台形上の2点","hint1":"平行や長方形になる図を描き、等しくなる2本の線分に印をつけよう。","hint2":"折り返しの前後では道のりの式が変わる。面積は上底＋下底を先に求め、その和が毎秒どれだけ変わるかを調べよう。"},{"title":"類題3 3　台形上の2点","hint1":"平行や長方形になる図を描き、等しくなる2本の線分に印をつけよう。","hint2":"折り返しの前後では道のりの式が変わる。面積は上底＋下底を先に求め、その和が毎秒どれだけ変わるかを調べよう。"}],"基本問題5":[{"title":"5　線分が平行になる","hint1":"PQが指定された辺と平行になる位置を描こう。","hint2":"2点が動いた道のりを足すと、どの辺の長さの合計になるかな。それを速さの和で割ろう。"}],"基本問題6":[{"title":"6　台形上の移動と面積","hint1":"平行になるときは対応する線分が等しいことを使おう。","hint2":"面積から上底＋下底を求める。一方は毎秒増え、もう一方は減るので、その差で和の変化を考えよう。"}],"基本問題7":[{"title":"7　往復する点","hint1":"初めに平行になる図で、等しい線分を見つけよう。","hint2":"2回目は折り返した点の位置を「片道の2倍−進んだ道のり」と表し直そう。"}],"基礎演習4":[{"title":"4　平行になる線分","hint1":"平行になる位置にPQを描き、等しい長さを見つけよう。","hint2":"面積は上底＋下底に直す。その和は「もとの長さ＋2点の道のりの差」と表せるよ。"}],"練習問題4":[{"title":"4　六角形上の2点","hint1":"初めの出会いは周の長さ÷速さの和。同時に同じ頂点へ戻るのは1周時間の公倍数だよ。","hint2":"指定の線分と重なる組み合わせを描く。片方が頂点に着くたびの2点の位置を表にして最初の成立を探そう。"}],"練習問題7":[{"title":"7　3点と面積","hint1":"PRと中央の線の交点をSとしよう。上下の高さが等しいのでSの進み方はP・Rから求められるよ。","hint2":"三角形をQSを共通の底辺とする2つに分ける。一直線はQSが0、指定面積は必要なQSの長さに直し、出会い前後を調べよう。"}],"標準演習4":[{"title":"4　往復と平行四辺形","hint1":"平行四辺形ならPDとQCが等しくなるよ。","hint2":"2回目は両方の折り返しを図に書き、道のりの和がどの長さになるかを考えよう。"}],"標準演習6":[{"title":"6　3点が一直線","hint1":"PRと中央線の交点をSとする。上下が等しいので、Sの速さをP・Rの速さから求めよう。","hint2":"一直線はSとQが重なるとき。面積はQS×上下の高さの和÷2だから、目標面積をQSの長さに直そう。"}],"チャレンジ3":[{"title":"3　辺ではね返る点","hint1":"長方形を辺の向こうに裏返して並べると、はね返る道すじを一直線にできるよ。","hint2":"（1）広げた図の相似で位置を出す。（2）縦横に進む長さの比を使い、最初に格子の頂点を通る位置を探して、元の頂点名へ戻そう。"}],"例題4・類題4":[{"title":"例題4 4　円周上の2点","hint1":"1周する秒数で360度を割り、各点の毎秒の角度を出そう。","hint2":"重なるときは角の差が1周分、最も離れるときは半周分。正三角形になるときの中心角を求め、進む向きに合わせて角速度の和・差を使おう。"},{"title":"類題4 4　円周上の2点","hint1":"1周する秒数で360度を割り、各点の毎秒の角度を出そう。","hint2":"重なるときは角の差が1周分、最も離れるときは半周分。正三角形になるときの中心角を求め、進む向きに合わせて角速度の和・差を使おう。"}],"基本問題8":[{"title":"8　円周上で重なる","hint1":"各点の1周時間から毎秒の角度を求めよう。","hint2":"反対向きなら和、同じ向きなら差で1周分の角度を割ろう。"}],"基本問題9":[{"title":"9　中心角と距離","hint1":"各条件を満たす中心角を図に書こう。","hint2":"最も離れるのは直径の両端、重なるのは1周分進んだとき。2点が反対向きなら毎秒の角度を足そう。"}],"基礎演習5":[{"title":"5　円周上の追いつき","hint1":"360度÷1周の秒数で毎秒の角度を出そう。","hint2":"出会いは和、追いつきは差で1周分を割る。進む方向を小問ごとに確かめよう。"}],"基礎演習6":[{"title":"6　直角三角形になる","hint1":"円周上の三角形が直角なら、その斜辺は直径だよ。","hint2":"AP・AQ・PQのどれが直径になるかを別々に調べる。指定された時間内の時刻を並べ、重複を除こう。"}],"練習問題5":[{"title":"5　円周上の直角三角形","hint1":"1周時間から角速度を求め、半周分離れる時刻を出そう。","hint2":"AP・AQ・PQが直径になる時刻を別々に並べる。点が重なって三角形ができない場合は除こう。"}],"練習問題6":[{"title":"6　2つの円周","hint1":"同じ接点へ戻る時刻は2つの1周時間の公倍数だよ。","hint2":"指定された位置関係を図に描き、2点が進んだ中心角の和が半周か1周かを考えよう。"}],"標準演習5":[{"title":"5　円周上の直角三角形","hint1":"最も離れるのはPQが直径のとき。ただし最初の直角三角形ではAPやAQが先に直径になることもあるよ。","hint2":"3つの線分が直径になる時刻を別々に求め、指定時間内のものを順に並べて数えよう。"}],"チャレンジ2":[{"title":"2　円周上の3点","hint1":"Cを止めたと考え、A・Bの角速度からCの角速度を引こう。","hint2":"3点が重なる周期をそろえる。正三角形はCから見てA・Bが120度と240度の位置にあるときで、入れ替わる場合も調べよう。"}]},"6u-17":{"例題1・類題1":[{"title":"例題1 1　底面積・水量・深さ","hint1":"底面積・水量・深さのうち、何が同じで何が違うかを表にしよう。","hint2":"水量の比は底面積の比×深さの比。水量が同じなら底面積と深さは逆比になるよ。"},{"title":"類題1 1　底面積・水量・深さ","hint1":"底面積・水量・深さのうち、何が同じで何が違うかを表にしよう。","hint2":"水量の比は底面積の比×深さの比。水量が同じなら底面積と深さは逆比になるよ。"}],"基本問題1":[{"title":"1　同じ量の水","hint1":"同じ量を入れたとき、深い容器ほど底面積は小さいよ。","hint2":"（2）は底面積の条件を確かめ直し、同じ水量を使って深さの比を作ろう。"}],"基本問題2":[{"title":"2　水量と深さから比","hint1":"底面積の比は、それぞれの水量の比の数を深さの比の数で割ろう。","hint2":"水量を同じにしたときは、底面積の逆比が深さの比だよ。"}],"基礎演習1":[{"title":"1　底面積と深さ","hint1":"同じ量なら、底面積×深さが同じになるよ。","hint2":"分かっている底面積の比から深さを、深さの比から底面積を求めよう。"}],"練習問題1":[{"title":"1　水量の比","hint1":"底面積の比と深さの比を、それぞれ対応させてかけよう。","hint2":"合計水量を、求めた水量の比に分けよう。"}],"例題2・類題2":[{"title":"例題2 2　3つの容器","hint1":"水量÷深さで底面積の比を出し、その比の数を仮の底面積として書こう。","hint2":"同じ水量に分けるなら合計÷3。同じ深さにするなら合計水量÷底面積の合計だよ。2つを区別しよう。"},{"title":"類題2 2　3つの容器","hint1":"水量÷深さで底面積の比を出し、その比の数を仮の底面積として書こう。","hint2":"同じ水量に分けるなら合計÷3。同じ深さにするなら合計水量÷底面積の合計だよ。2つを区別しよう。"}],"基本問題3":[{"title":"3　3つの容器","hint1":"各容器の底面積の比をそろえ、比の数×元の深さを足そう。","hint2":"同じ深さなら底面積の合計で割る。同じ水量なら3等分して、指定の容器の底面積で割ろう。"}],"基礎演習2":[{"title":"2　3つに分ける水","hint1":"同じ水量を入れた容器の深さの逆比から、底面積比を求めよう。","hint2":"3つの底面積を同じ単位の比にそろえる。水量を合計し、深さをそろえるなら底面積の合計で割ろう。"}],"練習問題2":[{"title":"2　3つの底面積","hint1":"AとC、BとCの比を出し、Cの比の数をそろえよう。","hint2":"比の数を仮の底面積にして全水量を求める。同量に3等分したCの水量を、Cの底面積で割ろう。"}],"練習問題3":[{"title":"3　上下を入れ替える","hint1":"2つの円柱の底面積は、半径の比を2回かけた比だよ。","hint2":"水のない部分に注目しよう。上下を逆にしても空気の体積は同じ。空気の高さを求め、全高から引こう。"}],"標準演習1":[{"title":"1　水量と深さをそろえる","hint1":"Cを共通にして、A・B・Cの底面積比をそろえよう。","hint2":"水量を等しくするなら全水量÷3を各底面積で割る。深さを等しくするなら全水量÷底面積の合計だよ。"}],"例題3・類題3":[{"title":"例題3 3　仕切りのある容器","hint1":"グラフの折れ目で、水がどこまで入ったかを図に描こう。","hint2":"同じ高さまで入れるなら時間の比＝底面積の比。仕切りを越えて両側の水位がそろう前後を分けて考えよう。"},{"title":"類題3 3　仕切りのある容器","hint1":"グラフの折れ目で、水がどこまで入ったかを図に描こう。","hint2":"同じ高さまで入れるなら時間の比＝底面積の比。仕切りを越えて両側の水位がそろう前後を分けて考えよう。"}],"基本問題4":[{"title":"4　仕切りとグラフ","hint1":"奥行きが同じなので、底面積の比は横の長さの比になるよ。","hint2":"仕切りの高さまでの水量と、それより上の水量を、かかった時間で比べよう。グラフの横ばいは別の区画に水が入る時間だよ。"}],"基礎演習3":[{"title":"3　仕切りの高さ","hint1":"仕切りに届くまでに入った水量を求め、最初の区画の底面積で割ろう。","hint2":"同じ高さを満たす時間の比は底面積の比。奥行きが同じなので横の長さの比にもなるよ。"}],"練習問題4":[{"title":"4　2枚の仕切り","hint1":"水そうを、仕切りの高さでいくつかの直方体に分け、各部分に水が入る時間を書こう。","hint2":"同じ高さの部分は時間の比＝底面積の比。最後は全体の底面積と目標水位から必要な水量を出して時間に直そう。"}],"練習問題5":[{"title":"5　段差の水そう","hint1":"グラフの折れ目の水位を、段差の高さと結びつけよう。","hint2":"各区間の時間÷水位の上昇が、その区間の底面積に比例する。奥行きが同じなので横の長さの比に直せるよ。"}],"標準演習2":[{"title":"2　仕切りへの給水","hint1":"最初の仕切りまでの体積と時間から、毎秒入る水量を出そう。","hint2":"同じ高さまで入る部分どうしの時間比から横の長さを求める。最後は水そう全体の容積÷毎秒の水量だよ。"}],"チャレンジ1":[{"title":"1　2つの蛇口と仕切り","hint1":"一定時間で全体に入る水量を高さで比べよう。仕切りの片側では、Bだけの場合とA＋Bの場合の水位上昇を比べられるよ。","hint2":"同じ時間・同じ底面積なら高さの比が給水量の比。AとBを分けてから、各区画に入った水量を合計し、同じ高さでの底面積比を出そう。"}],"例題4・類題4":[{"title":"例題4 4　角柱と水位","hint1":"水中に入った角柱の体積と、押し上げられた水の体積は等しいよ。","hint2":"底に立てて水面から出る場合は、水の入る底面積から角柱分を引く。水位が角柱の高さを超えるなら、全部沈む場合として計算し直そう。"},{"title":"類題4 4　角柱と水位","hint1":"水中に入った角柱の体積と、押し上げられた水の体積は等しいよ。","hint2":"底に立てて水面から出る場合は、水の入る底面積から角柱分を引く。水位が角柱の高さを超えるなら、全部沈む場合として計算し直そう。"}],"基本問題5":[{"title":"5　沈めたおもり","hint1":"加えた水量÷水位の上昇から、水そうの底面積を求めよう。","hint2":"水位上昇分の体積に、こぼれた水の量も加えると、沈めたおもりの体積になるよ。"}],"基本問題6":[{"title":"6　角柱を引き上げる","hint1":"角柱の底面積を水そうの底面積から引き、水の入る部分を求めよう。","hint2":"角柱を上げて空いた部分の体積だけ、水が下へ移る。その体積を水が入る底面積で割って、水位の低下を求めよう。"}],"基本問題7":[{"title":"7　おもりを増やす","hint1":"同じ水量を、何本分の底面積を引いた場所に入れるかを考えよう。","hint2":"3本の場合、仮に出した水位がおもりの高さを超えないか確認する。超えたら水量＋おもり全体の体積を、水そうの底面積で割ろう。"}],"基礎演習4":[{"title":"4　角柱を立てる・上げる","hint1":"水そうから角柱分を引いた底面積を求めよう。","hint2":"押しのける体積と水位上昇分、引き上げて空く体積と水位低下分を、それぞれ等しくしよう。"}],"基礎演習5":[{"title":"5　おもりと水そう","hint1":"おもり全体の体積を、水位の上がった分で割ると水そうの底面積が出るよ。","hint2":"図3は水の入る底面積からおもり分を引く。水位をかけて体積を求め、Lへの単位換算をしよう。"}],"練習問題6":[{"title":"6　おもりの本数","hint1":"水量は一定。1本と2本のときの水位の逆比が、水が入る底面積の比になるよ。","hint2":"底面積の差がおもり1本分。3本のときは水位がおもりの高さを超えるか調べ、全部沈むなら水とおもりの全体積で求めよう。"}],"練習問題7":[{"title":"7　おもりの引き上げ","hint1":"図2で水から出ている部分が、図3で新しく沈む体積に当たるよ。","hint2":"その体積÷水位の差で水そうの底面積を出す。図2の水量は、水が入る底面積×深さだよ。"}],"練習問題8":[{"title":"8　円柱の出し入れ","hint1":"半径の比から底面積の比を求め、押しのけた体積と増えた水の体積を等しくしよう。","hint2":"水面より上へ出す場合は、水の入る底面積を使う。水位の変化と円柱自身の移動を分け、最後に水面から出た高さを求めよう。"}],"標準演習3":[{"title":"3　円柱のおもり","hint1":"おもりを沈めて増える部分と、水位が上がって増える部分の高さを図に書こう。","hint2":"体積が同じだから底面積は高さの逆比。水そうの底面積を求めたら、水量を出しておもりを除いた深さへ戻そう。"}],"標準演習4":[{"title":"4　おもりの本数と水位","hint1":"1本と2本の深さから、水の入る底面積の比を出そう。差がおもり1本分だよ。","hint2":"水量を比の単位で表し、元の水位を求める。3本では高さを超えるか確認して、水量＋おもり体積を使うか決めよう。"}],"チャレンジ2":[{"title":"2　水中の容器","hint1":"（1）は押しのけた体積を、水が入る残りの底面積に移して考えよう。","hint2":"（2）は容器を外から見た体積すべてが鉄ではない。水面下の外側の体積から、水の入った内側の空洞を引き、その分の水位上昇を元に戻そう。"}],"例題5・類題5":[{"title":"例題5 5　傾けた容器","hint1":"横から見て、水の部分が台形か三角形かを描こう。こぼれる前は水量が同じだよ。","hint2":"断面積×奥行きで水量を出す。こぼれた量は前後の差、元へ戻した深さは残った水量÷底面積だよ。"},{"title":"類題5 5　傾けた容器","hint1":"横から見て、水の部分が台形か三角形かを描こう。こぼれる前は水量が同じだよ。","hint2":"断面積×奥行きで水量を出す。こぼれた量は前後の差、元へ戻した深さは残った水量÷底面積だよ。"}],"基本問題8":[{"title":"8　傾けてこぼす","hint1":"こぼれる前は、断面の面積が元の長方形と同じになるよ。","hint2":"こぼれた後は残った水の断面を描く。残量×奥行き、元の量との差、残量÷底面積を問いに合わせて使おう。"}],"基本問題9":[{"title":"9　傾いた水面の高さ","hint1":"同じ水の形を逆さに重ねると直方体になるよ。","hint2":"向かい合う高さの和で作る直方体の半分が水量。元に戻した深さは、その2つの高さの平均だよ。"}],"基礎演習6":[{"title":"6　傾けた水量","hint1":"こぼれる前は、台形の断面積＝元の長方形の断面積だよ。","hint2":"傾けて残った水は三角柱として計算する。元の水量から引けばこぼれた量、残量から戻した深さも求められるよ。"}],"標準演習5":[{"title":"5　傾いた水面と水量","hint1":"底まで水がある図では、向かい合う2本の水の高さの和は、元の深さの2倍だよ。","hint2":"少しこぼした前後の「水平に戻した深さ」の差を求める。こぼした量÷深さの差で底面積が出るので、残った水から最初の水量へ戻そう。"}]},"6u-18":{"例題1・類題1":[{"title":"例題1 1　切り口の形","hint1":"同じ面にある2点を結ぼう。向かい合う平行な面では、切り口の線も平行になるよ。","hint2":"見た目で形を決めず、辺が等しい・平行・直角の理由を、もとの正方形の面から確かめよう。"},{"title":"類題1 1　切り口の形","hint1":"同じ面にある2点を結ぼう。向かい合う平行な面では、切り口の線も平行になるよ。","hint2":"見た目で形を決めず、辺が等しい・平行・直角の理由を、もとの正方形の面から確かめよう。"}],"基本問題1":[{"title":"1　3点を通る切り口","hint1":"指定の点を同じ面の上で結び、向かいの面には平行な線を描こう。","hint2":"何本の辺ができるかな。長さが等しい理由と直角になる理由を、立方体の面から確かめて名前を考えよう。"}],"基礎演習1":[{"title":"1　切り口の名前","hint1":"同じ面の2点を結び、向かいの面の平行線から残りの辺を決めよう。","hint2":"辺が等しいか、直角かを確かめる。斜めに描かれた見取り図の見た目だけで判断しないでね。"}],"例題2・類題2":[{"title":"例題2 2　面を延ばす切り口","hint1":"今ある2点だけで結べない面は、辺や面を立方体の外へ延ばそう。","hint2":"切り口の線を延長して共通の面上の点を作り、そこから次の点と結ぶ。立方体の辺と交わるところを順につなごう。"},{"title":"類題2 2　面を延ばす切り口","hint1":"今ある2点だけで結べない面は、辺や面を立方体の外へ延ばそう。","hint2":"切り口の線を延長して共通の面上の点を作り、そこから次の点と結ぶ。立方体の辺と交わるところを順につなごう。"}],"基本問題2":[{"title":"2　多角形の切り口","hint1":"まだ次の交点が分からないときは、分かる切り口の線と立方体の辺を外へ延ばそう。","hint2":"同じ平面上にできた交点を利用し、各面の切り口をつなぐ。最後に線が閉じることを確認して辺を数えよう。"}],"基礎演習2":[{"title":"2　延長して作る切り口","hint1":"分かる切り口の線を延長して、立方体の外で面と交わる点を作ろう。","hint2":"その点と次の指定点を同じ面上で結び、立方体の辺との交点を拾って閉じた形にしよう。"}],"例題3・類題3":[{"title":"例題3 3　斜めに切った体積","hint1":"同じ立体を逆さにして重ね、直方体にできないかな。","hint2":"重ねたときの高さは、向かい合う2本の高さの和。できた直方体の体積を2で割ろう。"},{"title":"類題3 3　斜めに切った体積","hint1":"同じ立体を逆さにして重ね、直方体にできないかな。","hint2":"重ねたときの高さは、向かい合う2本の高さの和。できた直方体の体積を2で割ろう。"}],"基本問題3":[{"title":"3　大きい方の体積","hint1":"切り口を描くと、横から見た断面が台形になるよ。","hint2":"その台形を底面とする角柱として考える。台形の高さと、角柱の奥行きを取り違えないでね。"}],"基本問題4":[{"title":"4　切り口の位置と体積","hint1":"平行な面の切り口の線から、向かい合う高さの和を求めよう。","hint2":"同じ立体を逆さに重ねた直方体の体積を2で割ろう。"}],"基本問題5":[{"title":"5　2つの体積の比","hint1":"それぞれ同じ立体を2個ずつ重ね、直方体にしよう。","hint2":"底面積が同じなら体積比は高さの比。向かい合う2つの高さの和どうしを比べよう。"}],"基本問題6":[{"title":"6　斜めに切った円柱","hint1":"同じものを逆さに重ねると円柱になるよ。","hint2":"底面積×向かい合う高さの平均で求めよう。"}],"基礎演習3":[{"title":"3　円柱と立方体","hint1":"円柱は同じものを逆さに重ねると、高さのそろった円柱になるよ。","hint2":"立方体は切った2つを回して比べると合同か確かめられる。合同なら全体の半分だよ。"}],"練習問題1":[{"title":"1　高さが違う三角柱","hint1":"底面を同じ三角形とする3つの三角すいに、体積を移して考えよう。","hint2":"底面積×3本の高さの平均で求められる。四角形の底面にこの3本平均をそのまま使わないでね。"}],"練習問題5":[{"title":"5　分けて体積を求める","hint1":"直方体の辺と平行な補助線を引いて、柱とすいに分けよう。","hint2":"両端の三角柱・中央の四角すい・残りの角柱のように、重ならない部分へ分けて足そう。"}],"標準演習1":[{"title":"1　切り取った立体を分ける","hint1":"中央と両端で分けると、中央は三角柱、両端は同じ四角すいになるよ。","hint2":"中央の長さは全体から両端の長さを引く。柱とすいで、体積の式の÷3の有無を区別しよう。"}],"標準演習2":[{"title":"2　三角柱の高さの平均","hint1":"底面の三角形の面積を先に求めよう。","hint2":"斜めに切った上面までの3本の高さを足して3で割り、底面積にかけよう。"}],"標準演習5":[{"title":"5　直方体と表面積の差","hint1":"切断後の立体を逆さに重ね、どんな角柱になるか考えよう。","hint2":"表面積の差は共通の切り口や等しい面を除くと簡単になる。残る帯状の側面だけを求めよう。"}],"例題4・類題4":[{"title":"例題4 4　すい体の差","hint1":"切り口の辺を延ばし、先が1点に集まる大きな三角すいを作ろう。","hint2":"相似な三角形から足りない高さを出す。大きな三角すい−外側の小さな三角すいで求めよう。"},{"title":"類題4 4　すい体の差","hint1":"切り口の辺を延ばし、先が1点に集まる大きな三角すいを作ろう。","hint2":"相似な三角形から足りない高さを出す。大きな三角すい−外側の小さな三角すいで求めよう。"}],"基本問題7":[{"title":"7　切り口と体積","hint1":"切り口を完成し、辺の平行と長さから形を判断しよう。","hint2":"斜めの線を延ばして頂点を作る。相似から高さを出し、大きい三角すいから小さいものを引こう。"}],"基本問題8":[{"title":"8　相似で切断","hint1":"向かい合う面にできる三角形を比べて、切り口が辺を分ける長さを求めよう。","hint2":"外へ延長して大きな三角すいを作る。相似比から高さを出し、不要な小さいすい体を引こう。"}],"基礎演習4":[{"title":"4　表面積の差と体積","hint1":"表面積を比べるとき、共通の切り口は打ち消せるよ。残りの面だけ比べよう。","hint2":"体積は斜めの線を延長して頂点を作り、大きい三角すいから小さい三角すいを引こう。"}],"練習問題2":[{"title":"2　切り取った三角すい","hint1":"底面にできる直角三角形と、それに垂直な高さを選ぼう。","hint2":"切り口の面積は展開図で考える。広げた全体から、分かる3つの直角三角形の面積を引こう。"}],"練習問題3":[{"title":"3　体積と表面積の差","hint1":"面上の相似で切り口の位置を出し、線を延ばして大きいすい体を作ろう。","hint2":"体積はすい体の差。表面積の差では切り口が共通なので、元の直方体の表面がどちら側に分かれたかだけ数えよう。"}],"練習問題4":[{"title":"4　五角形の切り口","hint1":"向かい合う面の三角形を比べ、等しい長さを見つけよう。","hint2":"延長して大きな三角すいにし、外にはみ出した小さい三角すいを引く。相似な立体の体積比は長さの比を3回かけるよ。"}],"練習問題6":[{"title":"6　段差と切断","hint1":"（1）は直方体を合同な2つに分けていないかな。","hint2":"（2）の体積は（1）から小さい三角すいを引く。切り口の面積は、展開して求まる大きい三角形2つから、小さい三角形を引こう。"}],"練習問題9":[{"title":"9　2つの切断面","hint1":"同じ平面上で三角形の底辺・高さの比を使い、面積比を求めよう。","hint2":"最小の立体を三角すいとして見つける。比べる三角すいの高さが共通なら、体積比は底面積比になるよ。"}],"標準演習3":[{"title":"3　頂点を切り落とす","hint1":"切り落とす各部分を、底面と高さの分かる三角すいとして見よう。","hint2":"合同なすい体をまとめて立方体から引く。次の小問で残る部分も、どの面を底面にするかを決めよう。"}],"標準演習4":[{"title":"4　三角すいと展開図","hint1":"直角を含む面を底面にすると、高さが立方体の辺で表せるよ。","hint2":"展開すると正方形に整理できる。全表面積から分かる3つの面を引いて、切り口の面積を求めよう。"}],"標準演習6":[{"title":"6　複雑な切り口の位置","hint1":"上・前・横から見た図に切断線を移し、面ごとの相似で辺の分け方を求めよう。","hint2":"延長して大きい三角すいを作り、外にはみ出す3つを引く。互いに相似なので、長さの比を3回かけて体積比をそろえよう。"}],"チャレンジ1":[{"title":"1　四角すいの切断","hint1":"（1）は小さい四角すいと全体の相似比を3回かけ、残る体積を考えよう。（2）は向かい合う辺の中点を結ぶ三角形で左右に分け、それを底面として3本の高さの平均を使おう。","hint2":"（3）は対角線を含む三角形の図に直し、同じ高さの三角形の面積比から辺を分ける比を求める。体積も高さが共通のすい体に分けて比べよう。"}],"チャレンジ2":[{"title":"2　2つの立体の共通部分","hint1":"（1）は立方体から合同な三角すいを切り取った残りとして考えよう。","hint2":"（2）の共通部分を三角すいとして描く。大きい三角すいと高さを共通にして底面の相似を使うので、ここは長さの比の2乗で比べるよ。"}],"例題5・類題5":[{"title":"例題5 5　小立方体の切断・穴","hint1":"1段ずつ真上から見た方眼を描き、切られる場所や穴の通る場所を塗ろう。","hint2":"穴が重なる立方体は1個として数える。切断は面が小立方体の内部を通るものを数え、辺に触れるだけのものと区別しよう。"},{"title":"類題5 5　小立方体の切断・穴","hint1":"1段ずつ真上から見た方眼を描き、切られる場所や穴の通る場所を塗ろう。","hint2":"穴が重なる立方体は1個として数える。切断は面が小立方体の内部を通るものを数え、辺に触れるだけのものと区別しよう。"}],"基本問題9":[{"title":"9　切られる個数","hint1":"各段の上面と下面に切り口の線を描こう。","hint2":"2本の線の間を切断面が通る。方眼の内部を切る立方体を1段ずつ数えよう。"}],"基本問題10":[{"title":"10　穴が開く個数","hint1":"各段の方眼に、上・前・横からの穴を書き込もう。","hint2":"1つでも印があれば穴が開いている。同じ立方体を重ねて引かず、印のないマスを数えよう。"}],"基礎演習5":[{"title":"5　切られる小立方体","hint1":"段ごとに上側と下側の切り口を描こう。","hint2":"その間を通る切断面が、どのマスの内部を切るか数える。段をまたぐ同じ列も、段が違えば別の立方体だよ。"}],"基礎演習6":[{"title":"6　穴を開けた後","hint1":"各方向からの穴を、各段の同じ方眼に重ねて描こう。","hint2":"穴のないマスを数える。別々の方向の個数をそのまま足すと、重なった立方体を2度数えてしまうよ。"}],"練習問題7":[{"title":"7　切断と穴","hint1":"各段で切られる立方体に印をつけよう。","hint2":"同じ方眼に穴を書き加え、穴によってなくなったものを除く。切られる個数と穴の個数を別々に引かないでね。"}],"練習問題8":[{"title":"8　穴のある切り口","hint1":"切り口の三角形を、段の境界で区切ろう。","hint2":"各段を上から見た穴の位置と切断線の交点を、切り口の図に移す。立体全体の穴をそのまま塗らず、切断面が通る部分だけ描こう。"}],"標準演習7":[{"title":"7　穴と切断面","hint1":"各段の方眼に穴を塗り、残る立方体を数えよう。","hint2":"切断面の上下の線も加える。穴を切り口の三角形へ移し、残った立方体のうち内部を切られるものだけ数えよう。"}]},"6u-19":{"例題1・類題1":[{"title":"例題1 1　切り落とす面・辺・頂点","hint1":"面ごとに辺を数えると、1本を2回数えるよ。頂点も、何枚の面が集まるかで割ろう。","hint2":"頂点を1つ切ると、古い頂点はなくなり、新しい頂点・辺・面ができる。1か所の変化を調べてから全体へ広げよう。"},{"title":"類題1 1　切り落とす面・辺・頂点","hint1":"面ごとに辺を数えると、1本を2回数えるよ。頂点も、何枚の面が集まるかで割ろう。","hint2":"頂点を1つ切ると、古い頂点はなくなり、新しい頂点・辺・面ができる。1か所の変化を調べてから全体へ広げよう。"}],"基本問題1":[{"title":"1　頂点を切り落とす","hint1":"もとの立体の面・辺・頂点をまず数えよう。","hint2":"1頂点に何本の辺が集まるかな。切るとできる頂点・辺・面の数を調べ、古い頂点が消える分も入れよう。"}],"基礎演習1":[{"title":"1　切断前後の面・辺・頂点","hint1":"1つだけ切る、辺の中点まで切る、さらに切る場合を分けて描こう。","hint2":"辺の中点で新しい頂点が隣と共通になる場合がある。単純に「1頂点あたり」をかけず、同じ点を重ねて数えていないか確かめよう。"}],"練習問題1":[{"title":"1　切り落とした体積と面積","hint1":"小さい三角すいと元の三角すいの相似比を出そう。","hint2":"体積比は3乗、面積比は2乗。表面積は切り落として消えた3面分を引き、新しい切り口1面分を足そう。"}],"標準演習1":[{"title":"1　正十二面体を切る","hint1":"五角形の辺を全て数えると各辺を2回、頂点を全て数えると1頂点を何回数えるかな。","hint2":"頂点1つを切ったときにできる頂点・辺・面を調べ、古い頂点が消える分も含めて全体に広げよう。"}],"チャレンジ1":[{"title":"1　面・辺・頂点の数","hint1":"元の面が残る部分と、頂点を切って新しくできた面を分けて数えよう。","hint2":"各面の辺を全部足したら2で割る。頂点は1か所に集まる面の枚数を図で確認し、その重複を除こう。"}],"例題2・類題2":[{"title":"例題2 2　表面の最短のひも","hint1":"ひもが通る面を順に開き、出発点と到着点を直線で結ぼう。","hint2":"辺をまたぐところに相似な直角三角形ができる。横の長さの比から、求める縦の長さを出そう。"},{"title":"類題2 2　表面の最短のひも","hint1":"ひもが通る面を順に開き、出発点と到着点を直線で結ぼう。","hint2":"辺をまたぐところに相似な直角三角形ができる。横の長さの比から、求める縦の長さを出そう。"}],"基本問題2":[{"title":"2　展開図と最短距離","hint1":"小問ごとに、ひもが通る面を順に横へ並べよう。","hint2":"ひもを1本の直線で結ぶと相似な直角三角形ができる。展開図全体の横幅と部分の横幅を比べよう。"}],"基本問題3":[{"title":"3　円すいに巻くひも","hint1":"展開したおうぎ形の弧は底面の円周と同じ。中心角を求めよう。","hint2":"最短のひもは展開図上の直線。できる三角形の角に注目すると、長さが分かる辺と等しくなるよ。"}],"基礎演習2":[{"title":"2　表面を通る最短距離","hint1":"指定の順に面を開き、両端を1本の直線で結ぼう。","hint2":"対応する直角三角形の横幅の比から縦の長さを求める。辺の反対側からの長さを聞かれていれば全長から引こう。"}],"練習問題2":[{"title":"2　直方体を回るひも","hint1":"ひもが同じ面を2回通るなら、その面も2つ描いて一直線にしよう。","hint2":"全体と部分の直角三角形で、横の長さの比をそろえて求めよう。"}],"練習問題3":[{"title":"3　円すいの展開図","hint1":"底面の円周と母線から展開図のおうぎ形の角を求めよう。","hint2":"直線のひもを描き、必要な垂線を下ろす。30度を含む直角三角形の辺の関係で面積に必要な高さを出そう。"}],"標準演習2":[{"title":"2　周回するひも","hint1":"側面を通る順に何周分も開いて、ひもを直線にしよう。","hint2":"相似な直角三角形の縦横の比を使う。途中2点間の長さは、全高から上下の不要な長さを引こう。"}],"標準演習3":[{"title":"3　円すいの糸と面積","hint1":"展開図のおうぎ形の角を、底面半径と母線の比から出そう。","hint2":"糸と弧に囲まれる面積は、おうぎ形から三角形を引く。30度の直角三角形を使って必要な高さを求めよう。"}],"例題3・類題3":[{"title":"例題3 3　投影図から体積","hint1":"上から見た図で底面、正面や横から見た図で高さを確認し、見取り図を描こう。","hint2":"柱体かすい体か、組み合わせかを分けて体積を計算する。斜めの辺を立体の高さに使わないでね。"},{"title":"類題3 3　投影図から体積","hint1":"上から見た図で底面、正面や横から見た図で高さを確認し、見取り図を描こう。","hint2":"柱体かすい体か、組み合わせかを分けて体積を計算する。斜めの辺を立体の高さに使わないでね。"}],"基本問題4":[{"title":"4　円柱の投影図","hint1":"円が見える方向を底面側として、半径と高さを読み取ろう。","hint2":"体積は底面積×高さ。表面積は円2枚と、円周×高さの長方形だよ。"}],"基本問題5":[{"title":"5　四角すいの投影図","hint1":"体積に使う垂直な高さと、三角形の側面の高さを区別して書こう。","hint2":"体積は底面積×高さ÷3。表面積は底面と4枚の三角形を足そう。"}],"基本問題6":[{"title":"6　斜めに切った立体","hint1":"各方向で同じ高さになる頂点を対応させ、切り口を描こう。","hint2":"同じ立体を逆さに重ねると直方体になる。できた直方体の体積を2で割ろう。"}],"基礎演習3":[{"title":"3　投影図から名前","hint1":"真上から見た多角形を底面として考えよう。","hint2":"側面から見て上まで同じ太さなら柱、頂点へ集まるならすい。底面の辺の数を名前に結びつけよう。"}],"練習問題4":[{"title":"4　三角すいの投影図","hint1":"底面の三角形と、そこから頂点までの垂直な高さを読み取ろう。","hint2":"表面積では各三角形の高さを別に確認する。立体の高さをすべての側面に使わないでね。"}],"練習問題5":[{"title":"5　切り取った体積","hint1":"切り取った部分を、大きい三角すいから小さい三角すいを引いた形にしよう。","hint2":"その切り取った体積を、元の立方体から引く。どちらを求めているか最後に確かめよう。"}],"標準演習4":[{"title":"4　組み合わせた立体","hint1":"投影図から、下の柱と上のすいの境目を描こう。","hint2":"体積は2つを足す。表面積は接して隠れる面を除き、外に出た三角形・長方形・台形を足そう。"}],"例題4・類題4":[{"title":"例題4 4　積み木の最大・最小","hint1":"上から見た各マスに、置ける段数を書こう。正面と横の両方の高さを超えられないよ。","hint2":"最大は両方の上限内で積む。最小は各列の最高段を満たす場所をまとめ、他を低くする。表面積は見えないくぼみの面も確かめよう。"},{"title":"類題4 4　積み木の最大・最小","hint1":"上から見た各マスに、正面図で許される最高段を書こう。横からの図はまだ与えられていないよ。","hint2":"最小は各マスに1個ずつ置き、正面の各列で1か所だけ必要な高さまで積む。最大は全マスを上限まで積む。最大の配置から外側の面を数えよう。"}],"基本問題7":[{"title":"7　積み木の段数と体積","hint1":"上面図に段数を書き、正面と横から見た最高段に一致するか確かめよう。","hint2":"全部の段数を足せば立方体の個数。1個の体積をかけて全体の体積にしよう。"}],"基本問題8":[{"title":"8　積み木の個数の範囲","hint1":"上面図の各マスに、正面図で許される最高段を書こう。最大はその高さまで、最小は各列で1か所だけ最高段を満たすように積む。","hint2":"上面図で見える各マスには最低1個必要だよ。最大の配置で横からの図を描き、外に出る面を数えて表面積を求めよう。"}],"基礎演習4":[{"title":"4　積み木の範囲と横の図","hint1":"上面図の各マスに、正面図のその列で許される最高段を書こう。横からの図は、自分で最大の配置から描くよ。","hint2":"最大は全マスを上限まで、最小は各マスに1個と各列に必要な最高段だけを置く。最大の配置で横から見える最高段と、外側の面を数えよう。"}],"練習問題6":[{"title":"6　組み立てた立体の表面積","hint1":"個数は各段に分けて足そう。","hint2":"3方向の投影図に見える面を2倍するだけでは足りない。くぼみの中など、真正面・真横・真上から見えない面も加えよう。"}],"練習問題8":[{"title":"8　投影図から体積の範囲","hint1":"上面図の各マスに、正面と横から許される高さを書こう。","hint2":"最大は2方向の上限の小さい方まで。最小は高い列の条件を同じマスで満たし、他は上面図を保つ最小の高さにしよう。"}],"標準演習5":[{"title":"5　積み木の最大・最小","hint1":"正面・横の両方の最高段を満たすよう、上面図に段数を書こう。","hint2":"最小は高い段の役目をまとめ、最大は各マスを上限まで積む。表面積は段差に出る面も確かめよう。"}],"チャレンジ3":[{"title":"3　体積・表面積の範囲","hint1":"上面図に最小・最大の段数を入れ、正面・横の最高段を変えないことを確かめよう。","hint2":"表面積は体積とは別に調べる。内部の列を高低にすると投影図に隠れた壁が増えるので、隣同士の高さの差で数えよう。"}],"例題5・類題5":[{"title":"例題5 5　塗られた面","hint1":"底も塗るかを問題文で確認し、各立方体の上下左右前後を調べよう。","hint2":"塗られない面積は、立方体全部の6面の合計から外側の面積を引く。指定枚数だけ塗られた個数は、各段の方眼に塗られた面数を書いて数えよう。"},{"title":"類題5 5　塗られた面","hint1":"底も塗るかを問題文で確認し、各立方体の上下左右前後を調べよう。","hint2":"全体の表面積は外に出た面の合計。指定枚数だけ塗られた立方体は、各段の方眼に塗られた面数を書いて数えよう。"}],"基本問題9":[{"title":"9　塗った面・塗らない面","hint1":"まず組み立てた立体の外に出ている面を数えよう。","hint2":"塗られない面は全立方体の6面の合計から外側の面を引く。指定枚数塗られた個数は段ごとに面数を書いて数えよう。"}],"基本問題10":[{"title":"10　見えない面も数える","hint1":"前後・左右・上下から見える面を数え、くぼみに隠れる面がないか確認しよう。","hint2":"各立方体について隣と接する面を除き、塗られた枚数を各段の図へ書こう。"}],"基礎演習5":[{"title":"5　塗られた面の個数","hint1":"全体の表面積は、外に出た小正方形の数×1面の面積だよ。","hint2":"指定枚数だけ塗られた個数は、1段ごとに上下も含めて面数を書き込もう。"}],"練習問題7":[{"title":"7　さいころの目","hint1":"1列について、接する面の目が同じという条件を使って端の目を追おう。","hint2":"立体全体で向かい合う外側の面を組にできる。前後と左右を組にし、上の面を別に足そう。"}],"練習問題9":[{"title":"9　穴のある立方体","hint1":"小立方体に分け、穴の交わる中央を重ねて数えず体積を引こう。","hint2":"表面積は、穴の入口を除いた外側＋穴の内壁。くり抜いた部分の表面を考え、外に開いた面を除こう。"}],"練習問題10":[{"title":"10　積み重ねと塗られた面","hint1":"まず各段を方眼に描き、立方体の総数を数えよう。","hint2":"上下左右前後に隣の立方体がある面は塗られない。各マスに残りの面数を書いて、指定の個数を拾おう。"}],"標準演習6":[{"title":"6　角柱と円柱の穴","hint1":"くり抜いた形を角柱と円柱に分ける。交わる角柱の中央は2度数えないでね。","hint2":"表面積は外側から穴の入口を引き、内側の壁を足す。穴どうしが交わる部分には壁がないことに注意しよう。"}],"チャレンジ2":[{"title":"2　隠れた面と塗られた面","hint1":"前後左右上下に見える面だけでなく、中央の低い部分に向いた壁も数えよう。","hint2":"立方体ごとの塗られた面数を各段に書く。上の段の床や下の段の天井になる面も忘れず確認しよう。"}]},"6u-20":{"基本問題1":[{"title":"1　長方形の周りを動く点","hint1":"（1）10秒後のPとQを図に記入し、長方形から周りの三角形を引こう。","hint2":"（2）最初の間隔を2人の速さの和で割る。（3）次からは1周分近づくたびに出会うよ。6回目の時刻からPの位置を求めよう。"}],"基本問題2":[{"title":"2　点の移動と面積グラフ","hint1":"（1）10秒後にどの頂点を通るかな？ 移動距離からAB、三角形の面積からADとBCを求めよう。","hint2":"（2）面積36cm²の横線とグラフの交点を2つ探そう。増える区間と減る区間で別々に計算しよう。"}],"基本問題3":[{"title":"3　正方形上の2点と面積","hint1":"（1）長方形になるのはAPとBQが等しいとき。APが増え、BQが減る様子を図にしよう。","hint2":"（2）面積からAP＋BQを求めよう。APは毎秒4cm増え、BQは15cmから毎秒1cm減る。その和が毎秒どれだけ増えるか考えよう。"}],"基礎演習1":[{"title":"1　長方形上で重なる点","hint1":"最初の出会いは、AからB・Cを通ってDまでの道のりを、2人の速さの和で割ろう。","hint2":"その後は1周分ずつ近づくと出会う。5回目は最初の時刻に4回分を足し、Pの進んだ距離から位置を探そう。"}],"基礎演習2":[{"title":"2　円周上の出会い・追いつき","hint1":"2人が1秒で何周進むかを、1÷1周の秒数で表そう。","hint2":"反対向きは和、同じ向きは差で考える。間隔が1周分変わるまでの時間を求めよう。"}],"練習問題1":[{"title":"1　正方形を周回する点","hint1":"（1）PQが辺に垂直になる図を描き、2点の横の位置をそろえよう。（2）同じ向きなので速さの差を使うよ。","hint2":"（2）最初にQが追いつくまでに縮める間隔と、その後の1周分を分ける。（3）両者が頂点に来る時刻を表にし、初めて同じ辺にいる時間を探そう。"}],"練習問題2":[{"title":"2　長方形上の点と面積","hint1":"（1）面積を半分にするためのAP＋BQを求めよう。","hint2":"（2）AQCPの平行な2辺はAPとQC。面積からその和を求め、APが増える分とQCが減る分の差を使おう。"}],"練習問題3":[{"title":"3　台形上の点と面積","hint1":"（1）Pの位置を描き、台形から三角形APDとPBCを引こう。","hint2":"（2）PがA・Bにあるときの面積を比べると、移動中の1秒あたりの増加量がわかるよ。"}],"練習問題4":[{"title":"4　円周上の点と直角","hint1":"円周と速さから、PとQが1秒に動く中心角を求めよう。反対向きなので角度の変化は和だよ。","hint2":"最初の直角までの角度と、次の直角までの角度は違うね。最初の時間に、その後19回分の間隔を足そう。"}],"標準演習1":[{"title":"1　動く2点と四角形の面積","hint1":"PBQDの平行な2辺はPDとBQ。面積から、その和を求めよう。","hint2":"PDは36cmから毎秒8cm減り、BQは毎秒5cm増える。この和が1秒にどれだけ変わるかを使おう。"}],"標準演習2":[{"title":"2　円周上の点と直角三角形","hint1":"円周上の3点が直角三角形を作るのは、どれか2点を結ぶ線が直径になるときだよ。","hint2":"AP・AQ・PQの3組に分け、半周の間隔になる時刻を求めよう。Pが初めて1周するまで、という範囲内か確認しよう。"}],"チャレンジ1":[{"title":"1　2点が元の位置で重なるとき","hint1":"（1）PがOに戻る時刻を並べよう。Qは大回りと小回りで1周の時間が変わるので、交互に足そう。","hint2":"（2）三角形OPQは長方形の半分を超えられるかな？ 最大になる頂点の組を調べ、2点が同時にそこに来る最初の時刻を探そう。"}],"チャレンジ2":[{"title":"2　円周上の点と三角形","hint1":"（1）1秒で動く角度の差を使う。（2）3秒後の2点を描き、底辺OAへの高さを下ろそう。","hint2":"（2）30度の角がある直角三角形を使えるよ。（3）OA・OBの長さは一定。高さがいちばん大きくなる角度を探そう。"}],"基本問題4":[{"title":"4　水の体積の比","hint1":"底面積の比と深さの比を、それぞれの容器についてかけよう。","hint2":"Aの体積に当たる数とBの体積に当たる数を求め、同じ数で割って比を簡単にしよう。"}],"基本問題5":[{"title":"5　水を移したあとの深さ","hint1":"底面積を⑩と③として、それぞれの水量を表そう。","hint2":"水量の合計を、底面積の合計で割ると、移し替えた後の共通の深さが求められるよ。"}],"基本問題6":[{"title":"6　仕切りのある水そう","hint1":"（1）横線の間はBに水がたまるよ。AとBの底面積の比から、Bを満たす時間を求めよう。","hint2":"（2）最初の24分から毎分の水量を求める。仕切りより上の15cmを満たす時間から全体の底面積を出し、AとBの分を引こう。残った面積に仕切りの高さをかけると体積になるよ。"}],"基本問題7":[{"title":"7　石を沈めたときにこぼれる水","hint1":"水面から容器の上まで、空いていた部分の体積を求めよう。","hint2":"石の体積のうち、その空きに入りきらない分が、こぼれる水の体積だよ。"}],"基本問題8":[{"title":"8　傾けた容器と水の深さ","hint1":"横から見た水の形を描こう。向きを逆にした同じ形を合わせると長方形になるよ。","hint2":"同じ水の形を2つ合わせた長方形の高さを2で割ろう。その平均が、容器を戻したときの深さになるよ。"}],"基礎演習3":[{"title":"3　2つの容器と水の深さ","hint1":"（1）同じ水量なら、深さの比は底面積の比の逆だよ。","hint2":"（2）底面積を③と⑤に置き、それぞれの水量を足そう。それを底面積の合計で割ろう。"}],"基礎演習4":[{"title":"4　傾いた容器と水面","hint1":"傾けた後の両端の深さを、12cmと□cmとして横からの図を描こう。","hint2":"水量が変わらないので、2つの深さの平均が、傾ける前の8cmになるよ。"}],"練習問題5":[{"title":"5　角柱を水そうに入れる","hint1":"（1）水面を棒の上端まで上げるのに必要な体積を、棒1本の体積と比べよう。端数が出たら本数はどうするかな？","hint2":"（2）（3）水量を、容器の底面積から棒の底面積を引いた面積で割ろう。求めた深さが棒の高さ以下か確かめよう。"}],"練習問題6":[{"title":"6　傾けた容器と円柱","hint1":"2つの円柱の中心を通る縦の断面を描こう。傾いた水面で切り取られる空気の高さは、横の距離に比例するよ。","hint2":"左右対称なので、空気の平均の高さは中心位置の高さで考えられる。内側と外側の平均の差が6cmになることを使い、空気の高さから水の深さに戻そう。"}],"標準演習3":[{"title":"3　仕切りの高さと注水グラフ","hint1":"最初の6分と、その後の横線3分は、それぞれ片側を同じ高さまで満たす時間だよ。","hint2":"その時間比が底面積の比になる。仕切りの位置と毎分の水量を求め、全体の水量から満水の時刻を出そう。"}],"標準演習4":[{"title":"4　角柱の出し入れと水位","hint1":"（1）棒の底面積を引いた面積に、水が入るよ。","hint2":"（2）棒の下の4cm分には、容器の底面全体に水が入る。その水量を引き、残りを棒の横の底面積で割って4cmに足そう。"}],"チャレンジ3":[{"title":"3　容器のある水そうとグラフ","hint1":"満水までの18分から毎分の水量を求めよう。グラフの横線では、どの容器に水がたまっているかな？","hint2":"2分まで・2〜5分・5分以降を分ける。12分で水面がAの上端に届くことからAの高さを出し、各区間の水量から底面積を求めよう。"}],"チャレンジ4":[{"title":"4　角柱を入れた水の体積","hint1":"（1）A・Bで水面が上がる高さの比は、沈んだ部分の体積の比。底面積90・130で割って、沈んだ高さの比に直そう。","hint2":"高さの差5cmから元の深さと容器の底面積を求める。（2）元の水量からこぼれた量を引き、Cの横に水が入る面積で割ろう。"}],"チャレンジ5":[{"title":"5　容器の底面積と水位","hint1":"水より上の「空気」に注目しよう。逆さにしても空気の体積は変わらないね。","hint2":"底面の一辺の比を面積の比に直し、空気の高さの比を逆にする。水面の高さの差5cmを使って細い部分Aの高さを調べ、次の条件でも同じ空気の体積を使おう。"}],"基本問題9":[{"title":"9　立方体の切り口の形","hint1":"指定された点を、同じ面にあるものどうしから結ぼう。途中で線を立体の内側に通さないようにね。","hint2":"向かい合う面の切り口は平行になるよ。できた多角形について、辺の長さ・平行な辺・角を調べよう。"}],"基本問題10":[{"title":"10　直方体の切断","hint1":"（1）面EHDAの切り口はPQと平行。対応する辺の長さの増減を使ってRを決めよう。","hint2":"（2）同じ立体を逆さにして合わせると直方体にできるよ。合わせた高さはAD＋QG。最後に体積を半分にしよう。"}],"基本問題11":[{"title":"11　切り口と体積の比","hint1":"（1）向かい合う面の切り口を平行に描き、辺の長さも比べよう。","hint2":"（2）EPとGQを上へ延ばして交点を作る。大きな三角すいから上の小さな三角すいを引き、立方体全体と比べよう。"}],"基礎演習5":[{"title":"5　切り口の形と体積","hint1":"同じ面の点を結び、向かい合う面には平行な線を描こう。","hint2":"切り口の辺の長さを比べて形を判断する。体積は、切った2つの立体を裏返すと重なるか考えよう。"}],"練習問題7":[{"title":"7　立方体の切断と体積","hint1":"（1）延長してできる三角すいC-GTUは、直角をはさむCT・CUを底面に使えるよ。","hint2":"（2）相似からBRとDSを求める。大きな三角すいから、立方体の外へ出た小さな三角すい2個を引こう。"}],"練習問題8":[{"title":"8　切り口と展開図","hint1":"（1）向かい合う面で平行に線を引き、できた切り口を等しい三角形に分けよう。","hint2":"PQとACの長さの比から小三角形と三角形ACFの面積を比べる。（2）展開図では、同じ頂点の名前をそろえてから各面の線を描こう。"}],"標準演習5":[{"title":"5　立方体を切った体積","hint1":"BPとGQを延ばし、辺FEの延長との交点Oを作ろう。相似で必要な長さを求めよう。","hint2":"切り落とす部分は、大きな三角すいO-BFGから小さな三角すいO-PEQを引いたもの。それを立方体から引こう。"}],"チャレンジ6":[{"title":"6　角すいと切断の体積","hint1":"（1）元の角すいから、上の小さい角すいを引こう。（2）横から見た図で三角形FIGと三角形BIAを比べ、FIとIBの比を求めよう。","hint2":"（3）対角線BDを通る縦の断面で、台形HJIFの辺と高さを求める。不要な部分を、頂点がGの角すいと頂点がAの2つの角すいに分けて引こう。"}],"チャレンジ7":[{"title":"7　立方体の切断と相似","hint1":"（1）DE・EG・GDは、どの面の対角線かな？（2）D・H・F・Bを通る縦の断面を描こう。","hint2":"断面の相似な三角形DHRとPQRを比べる。（3）角すいP-EFGHから角すいR-EGHを引こう。高さは断面から求められるよ。"}],"チャレンジ8":[{"title":"8　段差のある立体の切断","hint1":"欠けた部分を補って立方体にし、同じ切断面を延ばそう。","hint2":"まず立方体の半分の体積を考える。そこに含まれる余分な小さな角すいを、段差の位置で相似を使って求め、引こう。"}],"基本問題12":[{"title":"12　切り落とした面・辺・頂点","hint1":"1つの頂点を切ると、新しい面・辺・頂点がいくつでき、元の何がなくなるかな？","hint2":"元の6面・12辺・8頂点を出発点にしよう。8か所を切っても、元の面や辺が残ることに注意しよう。"}],"基本問題13":[{"title":"13　展開図と最短距離","hint1":"通る3つの側面を横につなげて開き、AとHを直線で結ぼう。","hint2":"横幅の合計と、P・Qまでの横幅の比を使おう。相似から高さが求められるよ。BPとPFを取り違えないでね。"}],"基本問題14":[{"title":"14　積み木と投影図","hint1":"最多は、上から見える各マスを、正面図が許す高さまで積もう。","hint2":"最少は、各マスにまず1個置く。その後、正面図の高さが見えるように必要な所だけ高くしよう。表面積は隣の山との高さの差も数えるよ。"}],"基礎演習6":[{"title":"6　立体の頂点・辺・面","hint1":"まず1つの角だけ切って、新しい面・辺・頂点を数えよう。","hint2":"元の頂点はなくなるけれど、元の辺は短くなって残るね。その増減を8か所分にしよう。"}],"基礎演習7":[{"title":"7　展開図と最短距離","hint1":"（1）AからGまで通る2面を開こう。直線がBCを横切る位置を、辺の長さの比で求めよう。","hint2":"（2）AからPまで通る2面を開く。ADとAH、DRとHPが対応する三角形を探そう。"}],"練習問題9":[{"title":"9　最短の道すじと切断","hint1":"（1）通る3面を開いてEとGを結び、横幅の比からAPを求めよう。","hint2":"（2）PRとQGが平行になることを使う。（3）同じ立体を逆さに合わせるか、高さの平均を使って体積を求めよう。"}],"練習問題10":[{"title":"10　積み重ねた立方体の切断","hint1":"穴を通る小立方体を除いてから、切断面を各段に描こう。","hint2":"残ったものを「丸ごと」「角が切れた大きい方」「角の小さい三角すい」に分ける。三角すいは底面積×高さ÷3で求め、個数分を足そう。"}],"練習問題11":[{"title":"11　円すいの表面の最短距離","hint1":"底面の円周から、おうぎ形の中心角を求めよう。両端に現れるBを直線で結ぶとひもの道だよ。","hint2":"Aからその直線に垂線を下ろす。できる直角三角形を、正三角形の半分として見られないかな？"}],"練習問題12":[{"title":"12　積み木の表面と色","hint1":"上から見た各マスを、正面図で許される高さまで積もう。（1）は上下・左右・前後に分けて外側の面を数えよう。","hint2":"（2）小立方体を1個ずつ見て、隣に立方体がない面に印をつける。底にも色を塗る条件なので、最下段の底面も忘れないでね。"}],"標準演習6":[{"title":"6　立方体の穴と個数","hint1":"4段それぞれについて、4×4のマス目を描こう。","hint2":"横・縦・上からの穴が通るマスに印をつける。同じマスを2回消さず、印のないマスを合計しよう。"}],"標準演習7":[{"title":"7　投影図と積み木の表面積","hint1":"最多は、各マスで正面・横の両方が許す高さまで積もう。","hint2":"最多の配置で、上下・前後・左右の外に出る面を数えよう。表面積は、隣の高さとの差で現れる側面も確かめよう。"}],"標準演習8":[{"title":"8　立体のくりぬき","hint1":"（1）2本の穴の体積を引くと、交差部分を2回引いてしまうね。その分を戻そう。","hint2":"（2）元の表面から穴の入口を引き、穴の内側の壁を足そう。2本の穴が交差して壁がなくなる所は除こう。"}],"チャレンジ9":[{"title":"9　円柱に巻いた糸","hint1":"（1）円柱アの側面を2周分、円柱イの側面を1周分開こう。横幅と高さを比べてみよう。","hint2":"（2）円柱アの2周分の線を、1周分の長方形に重ねて描く。ひもと側面の辺で囲まれる平行四辺形の底辺と高さを求めよう。"}],"チャレンジ10":[{"title":"10　積み木の体積・表面積の範囲","hint1":"（1）（2）上から見える各マスにまず1個置く。最多は許される高さまで、最少は必要な列だけ高くしよう。","hint2":"表面積は、へこみの内側の面も数えるよ。1個の1面は一辺2cmの正方形。体積と面積で、かける数を取り違えないでね。"}],"チャレンジ11":[{"title":"11　正八面体と切り口","hint1":"（1）元の面の残りと、新しくできた面を分けて数えよう。辺は2つの面で共有しているよ。","hint2":"（2）①三角形で中点を結ぶと辺が半分になることを2回使う。②切り口を等しい三角形に分け、ABCとの辺の比を2乗して面積を比べよう。"}]}};allLessonHints["6u-6"]=lesson6Hints;
let hinted=new Set();try{const value=JSON.parse(localStorage.getItem(storageKey)||'[]');if(Array.isArray(value))hinted=new Set(value.filter(v=>typeof v==='string'))}catch{}
let explained=new Set();try{const value=JSON.parse(localStorage.getItem('shinen-math-explanations-current-attempt-v1')||'[]');if(Array.isArray(value))explained=new Set(value.filter(v=>typeof v==='string'))}catch{}
const starts=new Map(), states=new WeakMap();
function renderHint(container,key){container.replaceChildren();const [unitId,label]=key.split('|');const parts=allLessonHints[unitId]?.[label]?.filter(part=>!label.includes('・類題')||!part.title.startsWith('例題'));if(!parts){container.textContent='分かっている条件に印をつけ、何を求める問題かを確かめてみよう。図や表に書き出すのもおすすめです。';return}for(const part of parts){const block=document.createElement('section'),title=document.createElement('h4'),first=document.createElement('p'),second=document.createElement('details'),summary=document.createElement('summary'),detail=document.createElement('p');title.textContent=part.title;first.textContent='ヒント1：'+part.hint1;summary.textContent='ヒント2を表示';detail.textContent=part.hint2;second.append(summary,detail);block.append(title,first,second);container.append(block)}}

const rowFor=(key)=>{const [unitId,label]=key.split('|');const unit=document.getElementById(unitId);return [...(unit?.querySelectorAll('.study-problem-row')||[])].find(row=>(row.dataset.studyLabel||row.querySelector('.problem-heading strong')?.textContent.trim()||row.querySelector('strong')?.textContent.trim())===label)};
function updateRating(key){
 const row=rowFor(key);if(!row)return;
 const group=row.querySelector('.study-ratings'),locked=hinted.has(key)||explained.has(key),explanationUsed=explained.has(key);
 group.dataset.hintLocked=String(locked);
 for(const mark of (explanationUsed?['◎','◯','△']:['◎','◯'])){
  const button=[...group.querySelectorAll('button[data-result]')].find(b=>b.dataset.result===mark);
  if(!button)continue;
  if(locked&&button.getAttribute('aria-pressed')==='true')button.click();
  button.title=explanationUsed?'解説を見た問題は×以下で記録してください。':locked?'ヒントを見た問題は△以下で記録してください。':'';
 }
 const selected=[...group.querySelectorAll('button[data-result]')].find(b=>b.getAttribute('aria-pressed')==='true')?.dataset.result;
 group.querySelector('button[data-result="◯"]').disabled=locked;group.querySelector('button[data-result="△"]').disabled=explanationUsed;
 group.querySelector('button[data-result="◎"]').disabled=locked||!['◯','△','◎'].includes(selected);
 for(const [dialog,state] of active)if(state.key===key){
  for(const b of dialog.querySelectorAll('.answer-review-actions button[data-review-result]')){
   if(b.dataset.reviewResult==='◯')b.disabled=locked;
   if(b.dataset.reviewResult==='△')b.disabled=explanationUsed;if(b.dataset.reviewResult==='△')b.textContent='△ミスした・ヒントを見て解いた';
  }
 }
}
const active=new Map();
function saveHintState(){try{localStorage.setItem(storageKey,JSON.stringify([...hinted]));localStorage.setItem('shinen-math-explanations-current-attempt-v1',JSON.stringify([...explained]))}catch{}}
function usedHint(key){hinted.add(key);saveHintState();updateRating(key)}
window.markStudyAssistanceUsed=(unit,label)=>{if(unit&&label){const key=unit+'|'+label;explained.add(key);saveHintState();updateRating(key)}};
function clearHint(key){const hadHint=hinted.delete(key),hadExplanation=explained.delete(key);if(!hadHint&&!hadExplanation)return;saveHintState();updateRating(key)}
function keyFrom(trigger){const unit=trigger?.closest('.unit')?.id,row=trigger?.closest('.study-problem-row'),label=row?.dataset.studyLabel||row?.querySelector('.problem-heading strong')?.textContent.trim()||row?.querySelector('strong')?.textContent.trim();return unit&&label?unit+'|'+label:null}
function panelFor(key,reveal,dialog){const panel=document.createElement('section');panel.className='thinking-gate';panel.innerHTML='<p class="thinking-time" role="status" aria-live="off"></p><p>ノートで考えてから、いまの状態を選んでください。</p><div class="thinking-choices" role="group" aria-label="考えた結果"><button type="button" data-result="solved">解けた</button><button type="button" data-result="partial">途中まで</button><button type="button" data-result="stuck">解けなかった</button></div><button type="button" class="thinking-hint" aria-expanded="false" hidden>考えるヒント</button><div class="thinking-hint-text" hidden></div><p class="thinking-instruction"></p>';
const actions=reveal.closest('.answer-actions');if(actions)actions.before(panel);else reveal.before(panel);const time=panel.querySelector('.thinking-time'),message=panel.querySelector('.thinking-instruction'),hint=panel.querySelector('.thinking-hint'),hintText=panel.querySelector('.thinking-hint-text'),choices=[...panel.querySelectorAll('[data-result]')];let selection='',timer=null,hintUsedThisAttempt=false;renderHint(hintText,key);
if(!starts.has(key))starts.set(key,Date.now());reveal.disabled=true;
const update=()=>{const left=Math.max(0,seconds-Math.floor((Date.now()-starts.get(key))/1000));time.textContent=left?`答えを開けるまで、あと${left}秒`:'考える時間が終わりました。';message.textContent=left?`あと${left}秒。考えた状態を選んでください。`:selection?'準備ができました。「答えを表示」を押してください。':'考えた状態を選ぶと答えを表示できます。';reveal.disabled=left>0||!selection;if(!left){clearInterval(timer);timer=null}};
choices.forEach(button=>button.addEventListener('click',()=>{selection=button.dataset.result;if(!hintUsedThisAttempt)clearHint(key);choices.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));hint.hidden=selection==='solved';if(hint.hidden){hintText.hidden=true;hint.setAttribute('aria-expanded','false')}update()}));
hint.addEventListener('click',()=>{if(hint.hidden)return;hintText.hidden=!hintText.hidden;hint.setAttribute('aria-expanded',String(!hintText.hidden));if(!hintText.hidden){hintUsedThisAttempt=true;usedHint(key)}});
reveal.addEventListener('click',()=>{if(reveal.disabled)return;panel.hidden=true;clearInterval(timer);timer=null},true);
dialog.addEventListener('close',()=>{clearInterval(timer);timer=null;active.delete(dialog);panel.remove()},{once:true});
update();timer=setInterval(update,250);return panel}
const previous=window.prepareAnswerReview;
window.prepareAnswerReview=(dialog,trigger)=>{previous?.(dialog,trigger);const key=keyFrom(trigger),reveal=dialog.querySelector('button[id^="answer-reveal"],.lower-answer-reveal');if(!key||!reveal)return;const old=states.get(dialog);old?.panel.remove();const panel=panelFor(key,reveal,dialog);states.set(dialog,{key,panel});active.set(dialog,{key});updateRating(key)};
// Problem videos that open directly need the same gate.
const videoDialog=document.createElement('dialog');videoDialog.className='answer-dialog thinking-video-dialog';videoDialog.innerHTML='<h3>解説動画を見る前に</h3><p class="thinking-time" role="status"></p><p>ノートで考えてから、いまの状態を選んでください。</p><div class="thinking-choices" role="group" aria-label="考えた結果"><button type="button" data-result="solved">解けた</button><button type="button" data-result="partial">途中まで</button><button type="button" data-result="stuck">解けなかった</button></div><button type="button" class="thinking-hint" aria-expanded="false" hidden>考えるヒント</button><div class="thinking-hint-text" hidden></div><p class="thinking-instruction"></p><button type="button" class="thinking-video-open" disabled>解説動画を開く</button><button type="button" class="thinking-video-cancel">戻る</button>';document.body.append(videoDialog);
let target=null,key='',selection='',timer=null,approved=null,hintUsedThisAttempt=false;const open=videoDialog.querySelector('.thinking-video-open'),time=videoDialog.querySelector('.thinking-time'),message=videoDialog.querySelector('.thinking-instruction'),hint=videoDialog.querySelector('.thinking-hint'),hintText=videoDialog.querySelector('.thinking-hint-text'),choices=[...videoDialog.querySelectorAll('[data-result]')];
function updateVideo(){if(!videoDialog.open||!key)return;const left=Math.max(0,seconds-Math.floor((Date.now()-starts.get(key))/1000));time.textContent=left?`解説を開けるまで、あと${left}秒`:'考える時間が終わりました。';message.textContent=left?`あと${left}秒。考えた状態を選んでください。`:selection?'準備ができました。解説動画を開けます。':'考えた状態を選ぶと解説動画を開けます。';open.disabled=left>0||!selection;if(!left){clearInterval(timer);timer=null}}
document.addEventListener('click',event=>{const button=event.target.closest?.('.upper-problem-play');if(!button||button===approved)return;const nextKey=keyFrom(button);if(!nextKey)return;event.preventDefault();event.stopImmediatePropagation();target=button;key=nextKey;selection='';hintUsedThisAttempt=false;choices.forEach(b=>b.setAttribute('aria-pressed','false'));hint.hidden=true;hintText.hidden=true;hint.setAttribute('aria-expanded','false');renderHint(hintText,key);if(!starts.has(key))starts.set(key,Date.now());videoDialog.showModal();updateVideo();timer=setInterval(updateVideo,250)},true);
choices.forEach(button=>button.addEventListener('click',()=>{selection=button.dataset.result;if(!hintUsedThisAttempt)clearHint(key);choices.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));hint.hidden=selection==='solved';if(hint.hidden){hintText.hidden=true;hint.setAttribute('aria-expanded','false')}updateVideo()}));
hint.addEventListener('click',()=>{if(hint.hidden)return;hintText.hidden=!hintText.hidden;hint.setAttribute('aria-expanded',String(!hintText.hidden));if(!hintText.hidden){hintUsedThisAttempt=true;usedHint(key)}});
open.addEventListener('click',()=>{if(open.disabled||!target)return;const button=target;videoDialog.close();approved=button;try{button.click()}finally{approved=null}});
videoDialog.querySelector('.thinking-video-cancel').addEventListener('click',()=>videoDialog.close());videoDialog.addEventListener('close',()=>{clearInterval(timer);timer=null;target?.focus();target=null;key=''});
for(const key of new Set([...hinted,...explained]))updateRating(key);
const style=document.createElement('style');style.textContent='.thinking-gate{margin:14px 0;padding:16px;border-radius:14px;background:#f1f7fa;color:#17364b}.thinking-time{font-weight:700;font-size:1.1rem}.thinking-choices{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}.thinking-choices button,.thinking-hint,.thinking-video-open,.thinking-video-cancel{font:inherit;min-height:44px;padding:9px 14px;border:1px solid #879ca9;border-radius:10px;background:white;color:#17364b}.thinking-choices button[aria-pressed="true"]{background:#145b78;color:#fff}.thinking-hint-text{padding:8px 12px;background:#fff;border-radius:8px}.thinking-hint-text section+section{border-top:1px solid #d9e3e8;margin-top:12px;padding-top:12px}.thinking-hint-text h4{margin:8px 0}.thinking-hint-text p{line-height:1.6}.thinking-hint-text summary{cursor:pointer;font-weight:700;color:#145b78}.thinking-instruction{font-size:.92rem}.thinking-video-open:disabled,button[id^="answer-reveal"]:disabled,.lower-answer-reveal:disabled{opacity:.5;cursor:not-allowed}.thinking-gate[hidden],.thinking-hint[hidden],.thinking-hint-text[hidden]{display:none}';document.head.append(style);
})();
